INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('a39d8cbc-4a94-5566-b201-170447f94b47'::uuid, 'cf9d25e7-0a62-5245-a82d-4467f7305645'::uuid, 'Quelle famille de constituants apporte le plus d’énergie par gramme ?', 'mcq', '["Les glucides","Les protides","Les lipides","Les fibres"]'::jsonb, 2, 'Un gramme de lipide apporte environ 9 kcal, contre environ 4 kcal pour un gramme de glucide ou de protide.', 1),
    ('84a73af1-6d7a-502d-895d-277c22d74342'::uuid, 'cf9d25e7-0a62-5245-a82d-4467f7305645'::uuid, 'Un acide aminé essentiel est un acide aminé…', 'mcq', '["Que l’organisme ne sait pas synthétiser","Présent dans toutes les protéines","Qui fournit le plus d’énergie","Qui n’existe que dans la viande"]'::jsonb, 0, 'Essentiel signifie « indispensable à apporter par l’alimentation », car l’organisme ne le fabrique pas.', 2),
    ('ee072846-ed87-57c6-9310-17ba68bd1dff'::uuid, 'cf9d25e7-0a62-5245-a82d-4467f7305645'::uuid, 'Lequel de ces constituants est un micronutriment ?', 'mcq', '["L’amidon","Les triglycérides","Les protéines","La vitamine C"]'::jsonb, 3, 'Les vitamines sont nécessaires à très faible dose : ce sont des micronutriments.', 3),
    ('82ab57d9-b3d1-5f12-9f81-b8964ffc5511'::uuid, 'cf9d25e7-0a62-5245-a82d-4467f7305645'::uuid, 'La cellulose est un aliment non digestible par l’être humain.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’être humain n’a pas l’enzyme qui hydrolyse la cellulose : elle forme les fibres, utiles au transit.', 4),
    ('5f63ca27-3f19-5dc0-8728-64470a9064b7'::uuid, 'cf9d25e7-0a62-5245-a82d-4467f7305645'::uuid, 'Quels sont les deux acides gras essentiels ?', 'mcq', '["Acide palmitique et acide stéarique","Acide linoléique et acide alpha-linolénique","Acide oléique et acide acétique","Cholestérol et glycérol"]'::jsonb, 1, 'Ce sont un oméga-6 et un oméga-3, que l’organisme ne sait pas produire.', 5),
    ('c8fff95a-e15b-59c3-99fb-d7973c3a51fc'::uuid, 'cf9d25e7-0a62-5245-a82d-4467f7305645'::uuid, '« Riche en fibres » inscrit sur un paquet de céréales est…', 'mcq', '["Une recommandation officielle","Un besoin quantitatif","Un micronutriment","Une allégation"]'::jsonb, 3, 'L’allégation est une affirmation commerciale sur l’emballage, encadrée par la réglementation.', 6),
    ('32e6c38a-44c4-5148-8acd-7f7a308b364a'::uuid, 'cf9d25e7-0a62-5245-a82d-4467f7305645'::uuid, 'Un aliment contient 10 g de glucides et 5 g de lipides. Quelle énergie apporte-t-il environ ?', 'mcq', '["130 kcal","60 kcal","85 kcal","45 kcal"]'::jsonb, 2, '10 × 4 + 5 × 9 = 40 + 45 = 85 kcal.', 7),
    ('c0890e94-140e-572c-8375-bf93d3588cf7'::uuid, 'cf9d25e7-0a62-5245-a82d-4467f7305645'::uuid, 'Les besoins quantitatifs correspondent…', 'mcq', '["À l’énergie qu’il faut apporter chaque jour","Aux molécules que l’organisme ne sait pas fabriquer","Aux vitamines seulement","À la quantité d’eau bue"]'::jsonb, 0, 'Le besoin quantitatif est d’abord un besoin énergétique ; le besoin qualitatif concerne la nature des nutriments.', 8),
    ('9cdcd164-3032-5934-b61c-54251c96ddf5'::uuid, 'cf9d25e7-0a62-5245-a82d-4467f7305645'::uuid, 'Quel minéral participe au transport du dioxygène dans le sang ?', 'mcq', '["Le sodium","Le fer","Le calcium","Le potassium"]'::jsonb, 1, 'Le fer est au cœur de l’hémoglobine ; sa carence provoque une anémie.', 9),
    ('b99b3547-7137-54a1-8fcf-6e8965e34966'::uuid, 'cf9d25e7-0a62-5245-a82d-4467f7305645'::uuid, 'Quelle famille de constituants sert d’abord à construire les cellules et les enzymes ?', 'mcq', '["Les glucides","Les protides","Les fibres","L’eau"]'::jsonb, 1, 'Les protéines sont les molécules de construction et de fonction : enzymes, transporteurs, hormones peptidiques.', 10),
    ('48b094a8-337a-59fd-bdae-8ec1ead438c1'::uuid, 'cf9d25e7-0a62-5245-a82d-4467f7305645'::uuid, 'Une carence prolongée en vitamine C provoque…', 'mcq', '["Le rachitisme","Le diabète","L’anémie","Le scorbut"]'::jsonb, 3, 'Le scorbut des marins au long cours venait du manque de fruits et légumes frais.', 11),
    ('c3f808e3-0f8b-5ce6-adb6-b3de23142423'::uuid, 'cf9d25e7-0a62-5245-a82d-4467f7305645'::uuid, 'Les protides et les glucides apportent la même énergie par gramme, environ 4 kcal.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Environ 17 kJ par gramme pour chacun, contre environ 38 kJ pour les lipides.', 12),
    ('b91d48d9-59b1-5bc9-8bac-e3e99c4ad8a6'::uuid, '8749a813-f535-59a0-a47a-0f319955bb68'::uuid, 'La lumière du tube digestif appartient…', 'mcq', '["Au milieu extérieur","Au milieu intérieur","Au sang","À la lymphe"]'::jsonb, 0, 'Tant qu’une molécule n’a pas traversé la paroi intestinale, elle reste dans le milieu extérieur.', 1),
    ('538d0b80-53a1-5861-9724-4fd43e8339a2'::uuid, '8749a813-f535-59a0-a47a-0f319955bb68'::uuid, 'Quelle glande annexe produit la bile ?', 'mcq', '["Le pancréas","L’estomac","Le foie","Les glandes salivaires"]'::jsonb, 2, 'La bile est produite par le foie et stockée dans la vésicule biliaire.', 2),
    ('18f74f73-6bb5-5eac-ac12-1f64fea2722c'::uuid, '8749a813-f535-59a0-a47a-0f319955bb68'::uuid, 'Une hydrolyse est une réaction qui…', 'mcq', '["Oxyde une molécule","Forme une liaison en libérant de l’eau","Coupe une liaison grâce à une molécule d’eau","Transporte une molécule"]'::jsonb, 2, 'Hydro-lyse : couper par l’eau. La réaction inverse, une condensation, libère de l’eau.', 3),
    ('b8d19bcd-e0f4-56cc-98f6-fe88980a355d'::uuid, '8749a813-f535-59a0-a47a-0f319955bb68'::uuid, 'La pepsine agit dans l’estomac à un pH optimal voisin de…', 'mcq', '["2","7","8","12"]'::jsonb, 0, 'La pepsine est adaptée à l’acidité gastrique due à l’acide chlorhydrique.', 4),
    ('b96a260a-221c-5ab7-ad54-46c252a2f85c'::uuid, '8749a813-f535-59a0-a47a-0f319955bb68'::uuid, 'Les sels biliaires sont des enzymes qui hydrolysent les lipides.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils émulsionnent les lipides : c’est une action chimique, pas enzymatique. L’hydrolyse est faite par la lipase.', 5),
    ('b1411991-48e0-586e-b20d-9a8a2be5d992'::uuid, '8749a813-f535-59a0-a47a-0f319955bb68'::uuid, 'Quel est le produit de l’action de l’amylase sur l’amidon ?', 'mcq', '["Le glucose seul","Le lactose","Le saccharose","Le maltose"]'::jsonb, 3, 'L’amylase libère surtout du maltose, un diholoside ensuite hydrolysé en glucose par la maltase.', 6),
    ('fa5b0ba7-2844-58f0-867f-305c3941830f'::uuid, '8749a813-f535-59a0-a47a-0f319955bb68'::uuid, 'Le péristaltisme est dû…', 'mcq', '["Aux enzymes pancréatiques","Aux contractions des muscles lisses de la paroi","Aux muscles squelettiques de l’abdomen","Au microbiote"]'::jsonb, 1, 'C’est une digestion mécanique : les muscles lisses se contractent de proche en proche.', 7),
    ('47c81a80-d188-5d01-a679-c42b052b9125'::uuid, '8749a813-f535-59a0-a47a-0f319955bb68'::uuid, 'Après ébullition, la salive n’hydrolyse plus l’amidon. Pourquoi ?', 'mcq', '["L’amidon a été détruit","Il manque de l’eau","Le pH est devenu trop acide","L’amylase a été dénaturée"]'::jsonb, 3, 'La chaleur détruit la structure tridimensionnelle de l’enzyme, donc son site actif.', 8),
    ('e6d64401-394d-5d77-9dc7-352ad1b5cb39'::uuid, '8749a813-f535-59a0-a47a-0f319955bb68'::uuid, 'Une glande exocrine déverse sa sécrétion…', 'mcq', '["Dans le sang","Dans la lymphe","Dans une cavité ou vers l’extérieur","Dans le liquide intracellulaire"]'::jsonb, 2, 'Le pancréas exocrine déverse son suc dans le duodénum ; le pancréas endocrine libère ses hormones dans le sang.', 9),
    ('a3f02d13-ef0d-5e13-8a23-8d8b4366ae4f'::uuid, '8749a813-f535-59a0-a47a-0f319955bb68'::uuid, 'La lipase pancréatique hydrolyse les triglycérides en…', 'mcq', '["Acides gras et monoglycérides","Acides aminés","Glucose","Cholestérol"]'::jsonb, 0, 'Elle coupe les liaisons ester entre le glycérol et les acides gras.', 10),
    ('f6d7690a-e759-5e18-8e36-9a19d4e8bb07'::uuid, '8749a813-f535-59a0-a47a-0f319955bb68'::uuid, 'Le microbiote intestinal vit avec nous en…', 'mcq', '["Parasitisme","Symbiose","Compétition","Prédation"]'::jsonb, 1, 'Les deux partenaires y gagnent : nous le nourrissons, il fermente les fibres et produit des vitamines.', 11),
    ('03229a2d-4bff-5343-a9f0-bc7d69ecf4e0'::uuid, '8749a813-f535-59a0-a47a-0f319955bb68'::uuid, 'Dans l’expérience amylase-amidon, le tube sans salive sert de…', 'mcq', '["Substrat","Témoin","Réactif","Catalyseur"]'::jsonb, 1, 'Le témoin montre que la disparition de l’amidon est bien due à la salive.', 12),
    ('9db0a422-21ad-5c71-a1e9-07fb8a0ce76d'::uuid, 'd88f68b6-c7e2-57c6-917a-a397c269bcb9'::uuid, 'Où a lieu l’essentiel de l’absorption des nutriments ?', 'mcq', '["Dans l’estomac","Dans l’œsophage","Dans le gros intestin","Dans l’intestin grêle"]'::jsonb, 3, 'Sa surface d’environ 200 m² et sa paroi fine en font l’organe de l’absorption.', 1),
    ('9064e5ef-8d8c-50af-a0af-dc09416092a5'::uuid, 'd88f68b6-c7e2-57c6-917a-a397c269bcb9'::uuid, 'Les microvillosités sont portées par…', 'mcq', '["La membrane apicale des entérocytes","La membrane basale des entérocytes","Les capillaires sanguins","Les chylifères"]'::jsonb, 0, 'Elles forment la bordure en brosse, côté lumière.', 2),
    ('15595981-1733-5a2c-8e2c-8d95bc4ac8f3'::uuid, 'd88f68b6-c7e2-57c6-917a-a397c269bcb9'::uuid, 'Le co-transport Na⁺/glucose est un transport…', 'mcq', '["Passif, sans énergie","Par diffusion simple","Actif, utilisant le gradient de Na⁺","Par phagocytose"]'::jsonb, 2, 'Le glucose entre contre son gradient grâce au gradient de sodium entretenu par la pompe Na⁺/K⁺.', 3),
    ('af3bc2fd-9eeb-5e7e-a7d0-1fb7811ab22a'::uuid, 'd88f68b6-c7e2-57c6-917a-a397c269bcb9'::uuid, 'Par quelle voie les lipides absorbés rejoignent-ils d’abord la circulation ?', 'mcq', '["La veine porte hépatique","L’artère mésentérique","La lymphe","L’urine"]'::jsonb, 2, 'Emballés en chylomicrons, ils passent dans les chylifères puis la lymphe.', 4),
    ('2b535c41-efa6-5bc0-8fc7-228de4652a16'::uuid, 'd88f68b6-c7e2-57c6-917a-a397c269bcb9'::uuid, 'Un système porte relie…', 'mcq', '["Deux réseaux de capillaires successifs","Une artère et une veine sans capillaires","Le cœur et les poumons","Deux vaisseaux lymphatiques"]'::jsonb, 0, 'La veine porte relie les capillaires intestinaux aux capillaires du foie.', 5),
    ('9067395a-b035-5eb8-9302-8bce0588448e'::uuid, 'd88f68b6-c7e2-57c6-917a-a397c269bcb9'::uuid, 'La glycogénogenèse est…', 'mcq', '["La libération de glucose à partir du glycogène","La destruction des acides gras","La synthèse de lipides","La synthèse de glycogène à partir du glucose"]'::jsonb, 3, 'Genèse = fabrication. La glycogénolyse est l’inverse.', 6),
    ('205ddfcf-32f4-56f0-941d-4d9c64f40bb9'::uuid, 'd88f68b6-c7e2-57c6-917a-a397c269bcb9'::uuid, 'Les jonctions serrées entre entérocytes obligent les nutriments à traverser les cellules.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elles ferment l’espace entre cellules voisines : le passage est transcellulaire et contrôlé.', 7),
    ('d5417c0c-3225-50fb-b22c-1e5f28cd1405'::uuid, 'd88f68b6-c7e2-57c6-917a-a397c269bcb9'::uuid, 'Quelle cellule stocke les triglycérides en grande quantité ?', 'mcq', '["L’hépatocyte","L’adipocyte","L’entérocyte","Le globule rouge"]'::jsonb, 1, 'Le tissu adipeux est la grande réserve d’énergie de l’organisme.', 8),
    ('02c74253-12b8-5fe6-8af3-b2dac79bd69d'::uuid, 'd88f68b6-c7e2-57c6-917a-a397c269bcb9'::uuid, 'Une cellule polarisée est une cellule…', 'mcq', '["Chargée électriquement","Qui n’a pas de noyau","Qui se divise vite","Dont les deux faces ont des membranes différentes"]'::jsonb, 3, 'Membranes apicale et basale portent des transporteurs différents, ce qui oriente l’absorption.', 9),
    ('8e15d1e6-f3f2-57f3-ab91-b0c7839bd6a5'::uuid, 'd88f68b6-c7e2-57c6-917a-a397c269bcb9'::uuid, 'Un transport passif se fait…', 'mcq', '["Contre le gradient de concentration","Toujours avec de l’ATP","Dans le sens du gradient, sans énergie","Uniquement pour les ions"]'::jsonb, 2, 'Il suit le gradient ; un transporteur peut le faciliter sans dépenser d’énergie.', 10),
    ('1ef7e2c1-99c7-55bf-9d33-b68ea9b933a2'::uuid, 'd88f68b6-c7e2-57c6-917a-a397c269bcb9'::uuid, 'Le glycogène du muscle peut être libéré sous forme de glucose dans le sang.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Seul le foie libère du glucose dans le sang ; le muscle garde son glycogène pour lui-même.', 11),
    ('a7ab6cd8-cbf9-5c79-abbe-6dae4ae74ac5'::uuid, 'd88f68b6-c7e2-57c6-917a-a397c269bcb9'::uuid, 'Quel vaisseau conduit le glucose absorbé vers le foie ?', 'mcq', '["La veine porte hépatique","La veine cave","L’aorte","Le canal thoracique"]'::jsonb, 0, 'Le foie reçoit en premier les nutriments hydrosolubles, qu’il peut stocker ou transformer.', 12),
    ('1661a007-5ee9-5cf7-b250-4d3113bd1859'::uuid, '893adba2-8713-54af-8e2c-c025f404126b'::uuid, 'Quelle est la valeur de consigne de la glycémie à jeun ?', 'mcq', '["0,1 g·L⁻¹","Environ 1 g·L⁻¹","5 g·L⁻¹","10 g·L⁻¹"]'::jsonb, 1, 'La glycémie à jeun reste voisine de 1 g·L⁻¹, soit environ 5,5 mmol·L⁻¹.', 1),
    ('dbae85ce-b79a-5831-af7e-88eda0cdb71d'::uuid, '893adba2-8713-54af-8e2c-c025f404126b'::uuid, 'Quelles cellules sécrètent l’insuline ?', 'mcq', '["Les cellules α des îlots de Langerhans","Les cellules β des îlots de Langerhans","Les hépatocytes","Les adipocytes"]'::jsonb, 1, 'Les cellules β réagissent à l’hyperglycémie en libérant de l’insuline.', 2),
    ('2a4b3897-b1fb-53f7-92d5-90f546bf09b2'::uuid, '893adba2-8713-54af-8e2c-c025f404126b'::uuid, 'Le glucagon a pour effet principal…', 'mcq', '["De faire entrer le glucose dans les muscles","De détruire les cellules β","De stocker les lipides","De stimuler la glycogénolyse dans le foie"]'::jsonb, 3, 'Il fait libérer du glucose par le foie : la glycémie remonte.', 3),
    ('800e507d-cc73-5495-b288-0485fd5d7f5e'::uuid, '893adba2-8713-54af-8e2c-c025f404126b'::uuid, 'L’insuline est la seule hormone hypoglycémiante.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Plusieurs hormones font monter la glycémie, une seule la fait baisser : d’où la gravité du diabète.', 4),
    ('253c18d4-d777-50ff-8db0-e44bf162a489'::uuid, '893adba2-8713-54af-8e2c-c025f404126b'::uuid, 'Dans la boucle de régulation, le foie joue le rôle…', 'mcq', '["D’effecteur","De capteur","De grandeur régulée","De messager"]'::jsonb, 0, 'Il reçoit l’ordre hormonal et stocke ou libère le glucose.', 5),
    ('71de6d84-0589-5dc6-9af4-73e9ae12457d'::uuid, '893adba2-8713-54af-8e2c-c025f404126b'::uuid, 'Le diabète de type 1 est dû…', 'mcq', '["À une résistance à l’insuline","À un excès de glucagon","À la destruction auto-immune des cellules β","À un manque de glucose"]'::jsonb, 2, 'Le système immunitaire détruit les cellules productrices : il faut injecter de l’insuline.', 6),
    ('f2271976-4245-5952-a9f9-74c7b36fb41a'::uuid, '893adba2-8713-54af-8e2c-c025f404126b'::uuid, 'Une hormone est transportée jusqu’à ses cellules cibles par…', 'mcq', '["Les nerfs","La lymphe seulement","Le sang","L’urine"]'::jsonb, 2, 'Sécrétée par une glande endocrine, elle circule dans le sang et agit sur les cellules qui ont son récepteur.', 7),
    ('171d23d7-49d1-54eb-ae14-f16446f28175'::uuid, '893adba2-8713-54af-8e2c-c025f404126b'::uuid, 'Après un repas riche en glucides, on observe…', 'mcq', '["Une hausse de l’insulinémie","Une baisse de l’insulinémie","Une hausse du glucagon","Une glycogénolyse intense"]'::jsonb, 0, 'L’hyperglycémie stimule les cellules β, qui libèrent de l’insuline.', 8),
    ('195eae07-0259-55f2-9e94-2fd09573ddf8'::uuid, '893adba2-8713-54af-8e2c-c025f404126b'::uuid, 'La régulation de la glycémie fonctionne par…', 'mcq', '["Rétroaction positive","Action nerveuse seulement","Absence de rétroaction","Rétroaction négative"]'::jsonb, 3, 'Toute variation déclenche une réponse qui la corrige : c’est le propre de l’homéostasie.', 9),
    ('5f46ead6-d92c-52f4-baa6-3d161a0cf582'::uuid, '893adba2-8713-54af-8e2c-c025f404126b'::uuid, 'Lors d’une hyperglycémie provoquée, une glycémie supérieure à 2 g·L⁻¹ à 2 h évoque…', 'mcq', '["Une hypoglycémie","Un diabète","Une réponse normale","Un jeûne prolongé"]'::jsonb, 1, 'Chez une personne saine, la glycémie est revenue sous 1,4 g·L⁻¹ à 2 h.', 10),
    ('644c6dd3-3a6f-5af7-b978-46b0a38c69bc'::uuid, '893adba2-8713-54af-8e2c-c025f404126b'::uuid, 'Le diabète de type 2 est d’abord lié…', 'mcq', '["À une absence totale d’insuline","À une infection","À un excès d’insuline","À une résistance des cellules à l’insuline"]'::jsonb, 3, 'L’insuline est produite mais les cellules y répondent mal ; surpoids et sédentarité en sont des facteurs.', 11),
    ('a55b4232-6884-57cf-a448-881375ca831d'::uuid, '893adba2-8713-54af-8e2c-c025f404126b'::uuid, 'Quel organe consomme presque exclusivement du glucose et souffre en premier d’une hypoglycémie ?', 'mcq', '["Le foie","Le rein","Le cerveau","Le tissu adipeux"]'::jsonb, 2, 'D’où les malaises, la confusion puis la perte de connaissance en cas d’hypoglycémie sévère.', 12),
    ('19556d98-15c8-5ddd-bb44-a09cccf8a51e'::uuid, '98b57834-3b63-57cd-9c21-3462e445d588'::uuid, 'Quelle est l’unité fonctionnelle du rein ?', 'mcq', '["Le néphron","Le glomérule","L’uretère","La capsule"]'::jsonb, 0, 'Le néphron filtre, réabsorbe et sécrète : il forme l’urine à lui seul.', 1),
    ('e448efb0-efca-5a0d-a5c1-6b9e1c127b9a'::uuid, '98b57834-3b63-57cd-9c21-3462e445d588'::uuid, 'Quel conduit relie un rein à la vessie ?', 'mcq', '["L’urètre","L’uretère","L’aorte","Le tube collecteur"]'::jsonb, 1, 'L’uretère part du rein ; l’urètre évacue l’urine de la vessie vers l’extérieur.', 2),
    ('559d2c13-764c-51df-8b5a-bdcf0bccc72c'::uuid, '98b57834-3b63-57cd-9c21-3462e445d588'::uuid, 'Où a lieu la filtration du plasma ?', 'mcq', '["Dans l’anse de Henlé","Dans le glomérule","Dans la vessie","Dans le tube collecteur"]'::jsonb, 1, 'Le plasma passe du glomérule dans la capsule de Bowman : c’est l’urine primitive.', 3),
    ('a3bd23fd-2688-5dc1-bfdb-967e841df363'::uuid, '98b57834-3b63-57cd-9c21-3462e445d588'::uuid, 'Normalement, l’urine primitive contient…', 'mcq', '["Des globules rouges","Beaucoup de protéines","Des plaquettes","Du glucose"]'::jsonb, 3, 'Le glucose est filtré, puis réabsorbé en totalité dans le tube proximal.', 4),
    ('f148935f-69db-5dc9-a6e8-1f52cf497a41'::uuid, '98b57834-3b63-57cd-9c21-3462e445d588'::uuid, 'Les podocytes appartiennent à…', 'mcq', '["La barrière de filtration glomérulaire","La vessie","L’anse de Henlé","L’urètre"]'::jsonb, 0, 'Leurs pédicelles ménagent des fentes qui retiennent les grosses molécules.', 5),
    ('b5952a77-fd75-50b4-8056-71a0b8c68b85'::uuid, '98b57834-3b63-57cd-9c21-3462e445d588'::uuid, 'Pourquoi du glucose apparaît-il dans l’urine au-delà de 1,8 g·L⁻¹ de glycémie ?', 'mcq', '["La filtration s’arrête","L’ADH manque","Les transporteurs de réabsorption sont saturés","Le glucose est sécrété"]'::jsonb, 2, 'Tout le glucose filtré ne peut plus être repris : c’est la glycosurie du diabète.', 6),
    ('73eb75ae-bb47-57ce-bba8-5bc23d5272e0'::uuid, '98b57834-3b63-57cd-9c21-3462e445d588'::uuid, 'L’ADH est libérée par…', 'mcq', '["Le pancréas","Le rein","La neurohypophyse","Le foie"]'::jsonb, 2, 'Elle est produite par l’hypothalamus et stockée puis libérée par la neurohypophyse.', 7),
    ('b86f8b27-9c00-517c-9fef-37a7d2896805'::uuid, '98b57834-3b63-57cd-9c21-3462e445d588'::uuid, 'L’ADH augmente la réabsorption d’eau en…', 'mcq', '["Faisant insérer des aquaporines","Détruisant les néphrons","Augmentant la filtration","Bloquant le sodium"]'::jsonb, 0, 'Les aquaporines sont des canaux à eau : l’eau retourne au sang et l’urine se concentre.', 8),
    ('fa6d9738-5b29-58b5-a1ea-fe59a60927cf'::uuid, '98b57834-3b63-57cd-9c21-3462e445d588'::uuid, 'Un manque d’ADH provoque une diurèse très abondante.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est le diabète insipide : l’eau n’est plus réabsorbée dans le tube collecteur.', 9),
    ('0c4e8fd4-8521-5ada-b008-bf3f22a77847'::uuid, '98b57834-3b63-57cd-9c21-3462e445d588'::uuid, 'Quel déchet est bien plus concentré dans l’urine définitive que dans le plasma ?', 'mcq', '["Le glucose","Le calcium","L’albumine","L’urée"]'::jsonb, 3, 'L’urée est filtrée puis concentrée par la réabsorption de l’eau.', 10),
    ('a971ca7f-2322-5863-b4a7-71a176badfee'::uuid, '98b57834-3b63-57cd-9c21-3462e445d588'::uuid, 'La présence de protéines dans l’urine indique plutôt…', 'mcq', '["Un diabète","Une lésion de la barrière de filtration","Un excès d’ADH","Une déshydratation"]'::jsonb, 1, 'Les grosses protéines ne franchissent pas une barrière glomérulaire saine.', 11),
    ('31511dd1-9623-5beb-8a05-a64547aa94db'::uuid, '98b57834-3b63-57cd-9c21-3462e445d588'::uuid, 'Environ quel volume de plasma les reins filtrent-ils chaque jour ?', 'mcq', '["1,5 L","18 L","1 800 L","180 L"]'::jsonb, 3, 'Environ 180 L filtrés pour 1,5 L d’urine : plus de 99 % de l’eau est réabsorbée.', 12),
    ('b0f3ba45-8771-5526-964e-8b066040f7a7'::uuid, '66f9479d-df7f-57ef-8ff8-9ae4b1de91e1'::uuid, 'Quelles sont les gonades masculines ?', 'mcq', '["La prostate","Les vésicules séminales","Les testicules","L’épididyme"]'::jsonb, 2, 'Les gonades produisent les gamètes et des hormones sexuelles.', 1),
    ('d57efd2d-67e5-5bee-9e7d-7780dae1d6ef'::uuid, '66f9479d-df7f-57ef-8ff8-9ae4b1de91e1'::uuid, 'Quelles cellules sécrètent la testostérone ?', 'mcq', '["Les cellules de Leydig","Les cellules de Sertoli","Les spermatozoïdes","Les cellules de l’hypophyse"]'::jsonb, 0, 'Elles sont situées entre les tubes séminifères.', 2),
    ('7be63ff9-0ed1-5e11-8f8b-eb9c336540e4'::uuid, '66f9479d-df7f-57ef-8ff8-9ae4b1de91e1'::uuid, 'La spermatogenèse a lieu…', 'mcq', '["Dans la prostate","Dans les tubes séminifères","Dans le canal déférent","Dans l’hypophyse"]'::jsonb, 1, 'Les cellules germinales s’y différencient en spermatozoïdes, de la périphérie vers la lumière du tube.', 3),
    ('689e9148-98e4-5b49-8bdb-17ff3d17720d'::uuid, '66f9479d-df7f-57ef-8ff8-9ae4b1de91e1'::uuid, 'La voix grave et la pilosité sont des caractères sexuels…', 'mcq', '["Primaires","Secondaires","Héréditaires seulement","Embryonnaires"]'::jsonb, 1, 'Ils apparaissent à la puberté sous l’effet des hormones sexuelles.', 4),
    ('a12a7740-5e74-51de-852c-3e49a141a439'::uuid, '66f9479d-df7f-57ef-8ff8-9ae4b1de91e1'::uuid, 'Quelle hormone l’hypothalamus sécrète-t-il pour stimuler l’hypophyse ?', 'mcq', '["La LH","La FSH","La testostérone","La GnRH"]'::jsonb, 3, 'La GnRH déclenche la libération de LH et de FSH par l’hypophyse.', 5),
    ('b26dbc9b-90a3-5b02-b8f8-284400b16630'::uuid, '66f9479d-df7f-57ef-8ff8-9ae4b1de91e1'::uuid, 'La LH stimule chez l’homme…', 'mcq', '["Les cellules de Leydig","La prostate","Les ovaires","Le foie"]'::jsonb, 0, 'Elle déclenche la sécrétion de testostérone.', 6),
    ('c1a26e59-ac06-594f-931b-89c5bd1e9d4a'::uuid, '66f9479d-df7f-57ef-8ff8-9ae4b1de91e1'::uuid, 'La testostérone est une hormone…', 'mcq', '["Peptidique","Glucidique","Stéroïde","Nucléique"]'::jsonb, 2, 'Comme toutes les hormones sexuelles, elle dérive du cholestérol et porte un noyau stérane.', 7),
    ('8952b0d3-6a36-535b-9132-b4aaf529674c'::uuid, '66f9479d-df7f-57ef-8ff8-9ae4b1de91e1'::uuid, 'Chez l’homme, un excès de testostérone freine la sécrétion de LH et de FSH.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est un rétrocontrôle négatif, qui maintient la testostéronémie à peu près constante.', 8),
    ('bb82b74e-6864-559c-b372-5fb77ac530c7'::uuid, '66f9479d-df7f-57ef-8ff8-9ae4b1de91e1'::uuid, 'Pourquoi la prise de stéroïdes anabolisants diminue-t-elle la production de spermatozoïdes ?', 'mcq', '["Ils détruisent les spermatozoïdes","Ils bloquent l’urètre","Ils freinent LH et FSH par rétrocontrôle négatif","Ils augmentent la GnRH"]'::jsonb, 2, 'Sans LH ni FSH, les testicules ne sont plus stimulés.', 9),
    ('c2fa877c-f682-5235-8dc7-ed516b247d70'::uuid, '66f9479d-df7f-57ef-8ff8-9ae4b1de91e1'::uuid, 'Quelle voie génitale conduit les spermatozoïdes de l’épididyme vers l’urètre ?', 'mcq', '["Le canal déférent","L’uretère","La trompe","Le tube séminifère"]'::jsonb, 0, 'Les spermatozoïdes mûrissent dans l’épididyme puis empruntent le canal déférent.', 10),
    ('32c8f4f5-25a7-5bd7-988c-3a04757e4d6f'::uuid, '66f9479d-df7f-57ef-8ff8-9ae4b1de91e1'::uuid, 'La prostate est…', 'mcq', '["Une gonade","Une hormone","Une voie génitale","Une glande annexe"]'::jsonb, 3, 'Elle produit une partie du liquide séminal.', 11),
    ('a0762321-0f43-52bb-a7b0-c038995c6686'::uuid, '66f9479d-df7f-57ef-8ff8-9ae4b1de91e1'::uuid, 'Une régulation où chaque glande stimule la suivante s’appelle…', 'mcq', '["Un rétrocontrôle positif","Une cascade de régulation","Une homéostasie","Une diffusion"]'::jsonb, 1, 'Hypothalamus, puis hypophyse, puis gonade : chaque étage commande le suivant.', 12),
    ('c51d7a81-2a95-5d85-9566-ac73d6f616f0'::uuid, '9ef40f0d-8076-55b2-8b62-57d690efd878'::uuid, 'Quelle hormone est sécrétée par le corps jaune ?', 'mcq', '["La FSH","La GnRH","La LH","La progestérone"]'::jsonb, 3, 'Le corps jaune sécrète surtout de la progestérone, et aussi des œstrogènes.', 1),
    ('50dd3770-a9c9-5e44-88a9-7a663b7a2342'::uuid, '9ef40f0d-8076-55b2-8b62-57d690efd878'::uuid, 'Qu’est-ce qui déclenche l’ovulation ?', 'mcq', '["La chute de la progestérone","Les menstruations","Un pic de LH","La hCG"]'::jsonb, 2, 'Le pic de LH provoque la rupture du follicule mûr environ 36 h plus tard.', 2),
    ('7f72b5ab-deb0-5570-9924-b6f69b4277f9'::uuid, '9ef40f0d-8076-55b2-8b62-57d690efd878'::uuid, 'Pendant la phase folliculaire, l’endomètre…', 'mcq', '["Prolifère sous l’effet des œstrogènes","Se détruit","Reste inchangé","Devient un corps jaune"]'::jsonb, 0, 'Les œstrogènes font épaissir la muqueuse utérine.', 3),
    ('4df3e973-2299-5e6b-accc-f4accd169784'::uuid, '9ef40f0d-8076-55b2-8b62-57d690efd878'::uuid, 'Les menstruations sont provoquées par…', 'mcq', '["La hausse de la LH","La chute de la progestérone et des œstrogènes","L’ovulation","La hausse de la FSH"]'::jsonb, 1, 'Sans hormones ovariennes, l’endomètre n’est plus entretenu et se détache.', 4),
    ('88235739-e9ce-5763-83ea-ae17d1b585e8'::uuid, '9ef40f0d-8076-55b2-8b62-57d690efd878'::uuid, 'En fin de phase folliculaire, le rétrocontrôle des œstrogènes devient positif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Au-delà d’une valeur seuil, les œstrogènes stimulent la libération massive de LH.', 5),
    ('fe15e5f6-fdaf-525d-a9d2-81061cc8201c'::uuid, '9ef40f0d-8076-55b2-8b62-57d690efd878'::uuid, 'Comment la pilule combinée empêche-t-elle l’ovulation ?', 'mcq', '["En détruisant les ovocytes","Par un rétrocontrôle négatif permanent qui supprime le pic de LH","En augmentant la FSH","En bloquant les trompes"]'::jsonb, 1, 'Sans pic de LH, le follicule ne libère pas d’ovocyte.', 6),
    ('1e0441f7-14be-51bf-8ef1-fb88c7d8d663'::uuid, '9ef40f0d-8076-55b2-8b62-57d690efd878'::uuid, 'Le premier jour du cycle correspond…', 'mcq', '["À l’ovulation","Au pic de LH","À la formation du corps jaune","Au premier jour des règles"]'::jsonb, 3, 'Par convention, le cycle commence avec les menstruations.', 7),
    ('1f99f33d-d6d6-5c5f-b6bb-8d141891945a'::uuid, '9ef40f0d-8076-55b2-8b62-57d690efd878'::uuid, 'Qu’est-ce qui maintient le corps jaune en cas de grossesse ?', 'mcq', '["L’hormone hCG sécrétée par l’embryon","La FSH","La testostérone","L’insuline"]'::jsonb, 0, 'La hCG entretient la sécrétion de progestérone : pas de règles. C’est elle que détectent les tests de grossesse.', 8),
    ('f3c2d472-1b0e-57f1-aeb7-6f5bbeb346d0'::uuid, '9ef40f0d-8076-55b2-8b62-57d690efd878'::uuid, 'La FSH stimule…', 'mcq', '["La sécrétion de hCG","La destruction de l’endomètre","La croissance des follicules","La glaire cervicale"]'::jsonb, 2, 'FSH signifie hormone folliculo-stimulante.', 9),
    ('9c92481e-2719-5368-93b7-a2bde284bbf4'::uuid, '9ef40f0d-8076-55b2-8b62-57d690efd878'::uuid, 'Un progestatif épaissit la glaire cervicale, ce qui…', 'mcq', '["Favorise la nidation","Déclenche l’ovulation","Bloque le passage des spermatozoïdes","Provoque les règles"]'::jsonb, 2, 'C’est le mode d’action principal de la pilule progestative seule.', 10),
    ('e26d1028-60c9-5238-bc35-5337eb0c02da'::uuid, '9ef40f0d-8076-55b2-8b62-57d690efd878'::uuid, 'Dans une FIV, pourquoi injecte-t-on de la FSH ?', 'mcq', '["Pour faire mûrir plusieurs follicules","Pour bloquer l’ovulation","Pour provoquer les règles","Pour détruire le corps jaune"]'::jsonb, 0, 'On cherche à obtenir plusieurs ovocytes à ponctionner.', 11),
    ('7a315314-cff5-5ece-80fa-56d390b94f45'::uuid, '9ef40f0d-8076-55b2-8b62-57d690efd878'::uuid, 'La nidation a lieu dans…', 'mcq', '["L’ovaire","La trompe","Le col de l’utérus","L’endomètre"]'::jsonb, 3, 'L’embryon s’implante dans la muqueuse utérine préparée par la progestérone.', 12),
    ('b0d26abc-9a70-5d2b-8b1b-02d5827372f5'::uuid, '55819910-fe99-591f-95fa-fa4054ae2d77'::uuid, 'Combien de chromosomes contient un gamète humain ?', 'mcq', '["46","23","92","44"]'::jsonb, 1, 'Les gamètes sont haploïdes : un chromosome de chaque paire.', 1),
    ('9d147ee5-bd9d-58e7-bc0f-d9df79e4c583'::uuid, '55819910-fe99-591f-95fa-fa4054ae2d77'::uuid, 'La méiose produit, à partir d’une cellule…', 'mcq', '["2 cellules diploïdes identiques","1 cellule haploïde","4 cellules diploïdes","4 cellules haploïdes"]'::jsonb, 3, 'Deux divisions successives donnent quatre cellules à 23 chromosomes.', 2),
    ('afac6fab-b263-54ea-86d2-c9ee44f3afb7'::uuid, '55819910-fe99-591f-95fa-fa4054ae2d77'::uuid, 'Pendant la méiose I se séparent…', 'mcq', '["Les chromatides sœurs","Les mitochondries","Les chromosomes homologues","Les deux noyaux"]'::jsonb, 2, 'C’est la division réductionnelle : le nombre de chromosomes est divisé par deux.', 3),
    ('2f6c7d5e-3f54-5d05-a085-ce3c3f5eb78d'::uuid, '55819910-fe99-591f-95fa-fa4054ae2d77'::uuid, 'L’ovocyte libéré à l’ovulation est bloqué en…', 'mcq', '["Métaphase II","Prophase I","Anaphase I","Interphase"]'::jsonb, 0, 'Il n’achève la méiose II qu’après la pénétration du spermatozoïde.', 4),
    ('4eb726dd-4cb4-5d62-ad97-4a0c84fb55de'::uuid, '55819910-fe99-591f-95fa-fa4054ae2d77'::uuid, 'Pourquoi l’ovogenèse est-elle une division asymétrique ?', 'mcq', '["Elle produit 4 ovocytes","L’ovocyte garde presque tout le cytoplasme, les globules polaires dégénèrent","Elle ne dure qu’un jour","Elle se fait sans méiose"]'::jsonb, 1, 'Une seule cellule utile, riche en réserves, est produite par ovogenèse.', 5),
    ('143648a4-82f4-59e9-a10b-61e03989bb7c'::uuid, '55819910-fe99-591f-95fa-fa4054ae2d77'::uuid, 'Le génome mitochondrial est transmis…', 'mcq', '["Par le père seulement","Par la mère seulement","Par les deux parents","Au hasard"]'::jsonb, 1, 'Les mitochondries du zygote viennent de l’ovocyte.', 6),
    ('215b0a1a-5c40-5a28-9c3e-fd3bced110c9'::uuid, '55819910-fe99-591f-95fa-fa4054ae2d77'::uuid, 'La mitose est une division équationnelle.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Les cellules filles ont le même nombre de chromosomes que la cellule mère.', 7),
    ('97e3303e-eb4f-5ff1-a55f-6ced95d09a33'::uuid, '55819910-fe99-591f-95fa-fa4054ae2d77'::uuid, 'La trisomie 21 résulte le plus souvent…', 'mcq', '["D’une mutation d’un gène","D’une erreur de la mitose du zygote seulement","D’une infection","D’une mauvaise séparation des chromosomes pendant la méiose"]'::jsonb, 3, 'Un gamète à deux chromosomes 21 donne, après fécondation, une cellule à 47 chromosomes.', 8),
    ('aa368acc-f8ce-52fd-b5ec-3d428e637fdf'::uuid, '55819910-fe99-591f-95fa-fa4054ae2d77'::uuid, 'Quel document permet de compter et classer les chromosomes d’une cellule ?', 'mcq', '["Un caryotype","Un arbre généalogique","Une électrophorèse de protéines","Un antibiogramme"]'::jsonb, 0, 'Les chromosomes photographiés en métaphase sont rangés par paires.', 9),
    ('5bbe6e2f-01b3-5fa3-a460-456bb8cc762c'::uuid, '55819910-fe99-591f-95fa-fa4054ae2d77'::uuid, 'Combien de spermatozoïdes une cellule germinale donne-t-elle après méiose ?', 'mcq', '["1","2","4","8"]'::jsonb, 2, 'Contrairement à l’ovogenèse, la spermatogenèse garde les quatre produits de la méiose.', 10),
    ('36c1ce61-08d4-5864-8627-9620e1f42467'::uuid, '55819910-fe99-591f-95fa-fa4054ae2d77'::uuid, 'La fécondation rétablit la diploïdie par…', 'mcq', '["La duplication de l’ADN","La mitose de l’ovocyte","L’additivité des génomes nucléaires des deux gamètes","La perte d’un globule polaire"]'::jsonb, 2, '23 chromosomes paternels + 23 maternels = 46 chromosomes.', 11),
    ('2426e202-6fb4-55f3-89fd-69ad508541c6'::uuid, '55819910-fe99-591f-95fa-fa4054ae2d77'::uuid, 'Chaque chromosome, au début de la méiose, est formé de…', 'mcq', '["Deux chromatides","Une seule chromatide","Quatre chromatides","Aucune chromatide"]'::jsonb, 0, 'L’ADN a été répliqué avant la division : chaque chromosome porte deux chromatides sœurs.', 12),
    ('be6960ff-1072-59a5-99b7-d6e4097d4339'::uuid, 'a75bfd4d-ae38-5c94-8f7b-f8532aca1e48'::uuid, 'Un allèle est…', 'mcq', '["Un chromosome entier","Un gamète","Une protéine","Une version d’un gène"]'::jsonb, 3, 'Un même gène peut exister en plusieurs versions qui diffèrent par leur séquence.', 1),
    ('7a18882c-d5be-5387-8e4f-dfddfe37337b'::uuid, 'a75bfd4d-ae38-5c94-8f7b-f8532aca1e48'::uuid, 'Un individu A//a est…', 'mcq', '["Homozygote dominant","Hétérozygote","Homozygote récessif","Haploïde"]'::jsonb, 1, 'Il porte deux allèles différents du même gène.', 2),
    ('fabccbbd-0c89-5dfa-9997-a6adbbcf5ead'::uuid, 'a75bfd4d-ae38-5c94-8f7b-f8532aca1e48'::uuid, 'Le crossing-over est responsable du brassage…', 'mcq', '["Interchromosomique","Cytoplasmique","Mitochondrial","Intrachromosomique"]'::jsonb, 3, 'Il échange des portions de chromatides entre chromosomes homologues en prophase I.', 3),
    ('921c4826-a6aa-5b91-9346-8894dc7e9210'::uuid, 'a75bfd4d-ae38-5c94-8f7b-f8532aca1e48'::uuid, 'Deux parents sains ont un enfant atteint. L’allèle responsable est…', 'mcq', '["Dominant","Forcément sur le chromosome Y","Récessif","Mitochondrial"]'::jsonb, 2, 'Les parents portent l’allèle sans l’exprimer : ils sont hétérozygotes.', 4),
    ('428e9cb6-5e91-5477-92fa-6d3fd55701be'::uuid, 'a75bfd4d-ae38-5c94-8f7b-f8532aca1e48'::uuid, 'Quelle est la probabilité d’un enfant a//a pour deux parents A//a ?', 'mcq', '["1/4","1/2","3/4","0"]'::jsonb, 0, 'L’échiquier donne une case a//a sur quatre.', 5),
    ('ad4a2148-e687-5f0c-aec7-308d4cf00463'::uuid, 'a75bfd4d-ae38-5c94-8f7b-f8532aca1e48'::uuid, 'Le brassage interchromosomique a lieu…', 'mcq', '["En prophase I","En anaphase I","Pendant la fécondation","En interphase"]'::jsonb, 1, 'Les homologues de chaque paire partent au hasard vers l’un ou l’autre pôle.', 6),
    ('dcb2de4d-d4bc-574a-b7ec-305a7d4eaacd'::uuid, 'a75bfd4d-ae38-5c94-8f7b-f8532aca1e48'::uuid, 'Dans la drépanocytose, la mutation remplace l’acide glutamique par…', 'mcq', '["La lysine","La valine","La sérine","La cystéine"]'::jsonb, 1, 'Une seule base change (GAG → GTG), et un acide aminé hydrophobe prend la place d’un acide aminé chargé.', 7),
    ('3b80b523-f3b8-57ba-ac3d-ac819c00386b'::uuid, 'a75bfd4d-ae38-5c94-8f7b-f8532aca1e48'::uuid, 'Le phénotype peut se décrire à l’échelle moléculaire.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La forme d’une protéine (hémoglobine S) est déjà un phénotype, avant même la forme des globules rouges.', 8),
    ('e4a0ff4f-ca1d-51dd-93ce-df3d8edeff73'::uuid, 'a75bfd4d-ae38-5c94-8f7b-f8532aca1e48'::uuid, 'Combien de gamètes différents le seul brassage interchromosomique permet-il chez l’humain ?', 'mcq', '["46","23²","2⁴⁶","2²³, environ 8 millions"]'::jsonb, 3, 'Chacune des 23 paires se sépare au hasard : 2 possibilités par paire.', 9),
    ('306d3df0-5f6b-5b67-be52-eed257dea562'::uuid, 'a75bfd4d-ae38-5c94-8f7b-f8532aca1e48'::uuid, 'Dans un arbre généalogique, un rond plein représente…', 'mcq', '["Une femme atteinte","Un homme sain","Un homme atteint","Une femme saine"]'::jsonb, 0, 'Rond = femme, carré = homme ; le symbole plein signale une personne atteinte.', 10),
    ('0bef5117-6cc7-51d1-9cda-c6492eff9ff6'::uuid, 'a75bfd4d-ae38-5c94-8f7b-f8532aca1e48'::uuid, 'Un gène porté par le chromosome X est porté par…', 'mcq', '["Un autosome","L’ADN mitochondrial","Un gonosome","Un plasmide"]'::jsonb, 2, 'Les chromosomes sexuels X et Y sont les gonosomes ; les 22 autres paires sont des autosomes.', 11),
    ('bc1f64c1-0359-5794-8c54-bad5f0a36023'::uuid, 'a75bfd4d-ae38-5c94-8f7b-f8532aca1e48'::uuid, 'Deux vrais jumeaux ont le même génotype.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ils proviennent d’une seule cellule-œuf qui s’est séparée en deux embryons.', 12),
    ('cafc5b96-eef1-5bf8-bc3d-89aeca8cc6df'::uuid, '07b765e9-f68f-5707-ad01-f3476004b096'::uuid, 'Le D-glucose est un…', 'mcq', '["Cétohexose","Aldopentose","Aldohexose","Diholoside"]'::jsonb, 2, 'Il a 6 carbones et une fonction aldéhyde.', 1),
    ('90673bf6-33c5-5471-8495-891fcbd07b8c'::uuid, '07b765e9-f68f-5707-ad01-f3476004b096'::uuid, 'Le D-fructose porte une fonction…', 'mcq', '["Cétone","Aldéhyde","Acide carboxylique","Amine"]'::jsonb, 0, 'C’est un cétohexose : sa fonction carbonyle est sur le carbone 2.', 2),
    ('e89372ff-73a2-5594-a957-7029d72a7105'::uuid, '07b765e9-f68f-5707-ad01-f3476004b096'::uuid, 'Le saccharose est formé de…', 'mcq', '["Glucose + glucose","Glucose + galactose","Fructose + galactose","Glucose + fructose"]'::jsonb, 3, 'C’est le sucre de table, extrait de la betterave ou de la canne.', 3),
    ('120c5dc3-d915-52c7-a100-1f5abe9f6081'::uuid, '07b765e9-f68f-5707-ad01-f3476004b096'::uuid, 'Quelle liaison relie deux oses ?', 'mcq', '["La liaison peptidique","La liaison osidique","La liaison ester","Le pont disulfure"]'::jsonb, 1, 'Elle se forme avec élimination d’eau et se coupe par hydrolyse.', 4),
    ('34c7740c-b4a4-56d3-a17c-221f070f8db4'::uuid, '07b765e9-f68f-5707-ad01-f3476004b096'::uuid, 'Le glycogène est une réserve…', 'mcq', '["Végétale","Lipidique","Bactérienne seulement","Animale"]'::jsonb, 3, 'Il est stocké dans le foie et les muscles.', 5),
    ('bc42ea9b-fa87-5af4-ac7e-73207df750e4'::uuid, '07b765e9-f68f-5707-ad01-f3476004b096'::uuid, 'Le désoxyribose diffère du ribose par…', 'mcq', '["Un carbone en plus","Une fonction cétone","Un –OH en moins sur le carbone 2","Un groupe phosphate"]'::jsonb, 2, 'D’où son nom : désoxy- signifie « un oxygène en moins ».', 6),
    ('786e3a9d-5ba6-5962-b692-72568a7218d8'::uuid, '07b765e9-f68f-5707-ad01-f3476004b096'::uuid, 'Dans une projection de Fischer, la lettre D signifie que le –OH de l’avant-dernier carbone est…', 'mcq', '["À droite","À gauche","En haut","Absent"]'::jsonb, 0, 'C’est la convention qui définit la série D des oses.', 7),
    ('d55593ed-8b5c-5c47-b6af-71d53eab78a0'::uuid, '07b765e9-f68f-5707-ad01-f3476004b096'::uuid, 'L’amidon et la cellulose sont tous deux des polymères de glucose.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ils ne diffèrent que par l’orientation des liaisons osidiques, ce qui suffit à rendre la cellulose indigestible pour nous.', 8),
    ('ed352e23-56e6-51a4-b254-486535505f13'::uuid, '07b765e9-f68f-5707-ad01-f3476004b096'::uuid, 'Le groupe –COOH caractérise la fonction…', 'mcq', '["Alcool","Acide carboxylique","Aldéhyde","Ester"]'::jsonb, 1, 'On le retrouve dans les acides aminés et les acides gras.', 9),
    ('f410c2b7-30b2-5205-8ea6-cbc89b8f94a3'::uuid, '07b765e9-f68f-5707-ad01-f3476004b096'::uuid, 'L’hydrolyse d’un oside donne du glucose et du galactose. Il s’agit…', 'mcq', '["Du maltose","Du lactose","Du saccharose","De l’amidon"]'::jsonb, 1, 'Le lactose du lait est formé de galactose et de glucose.', 10),
    ('61863e48-98b7-5ac5-b7d6-554739dd70a4'::uuid, '07b765e9-f68f-5707-ad01-f3476004b096'::uuid, 'Un holoside est un oside formé…', 'mcq', '["D’oses et de protéines","D’un seul ose","D’oses et de lipides","Uniquement d’oses"]'::jsonb, 3, 'Maltose, saccharose, amidon et glycogène sont des holosides.', 11),
    ('cc609050-ca45-5502-a872-76f1095fa754'::uuid, '07b765e9-f68f-5707-ad01-f3476004b096'::uuid, 'Le D-ribose est un aldopentose qui entre dans la composition…', 'mcq', '["De l’ARN","De l’ADN","De l’amidon","Du glycogène"]'::jsonb, 0, 'Le ribose est l’ose de l’ARN ; l’ADN contient du désoxyribose.', 12),
    ('47a7ea5a-0a2d-5429-b493-86d6a0e05d4a'::uuid, '81a0c531-2555-52e5-a8fa-0f59ccf5c1f0'::uuid, 'Quelles fonctions un acide α-aminé porte-t-il sur son carbone α ?', 'mcq', '["Deux fonctions alcool","Une fonction aldéhyde et une fonction cétone","Une fonction amine et une fonction acide carboxylique","Une fonction ester"]'::jsonb, 2, 'D’où son nom : acide (–COOH) aminé (–NH₂).', 1),
    ('eff6d377-6bd1-52b7-9d69-d7f2fba1c26e'::uuid, '81a0c531-2555-52e5-a8fa-0f59ccf5c1f0'::uuid, 'Quel acide aminé forme des ponts disulfure ?', 'mcq', '["La valine","La sérine","La cystéine","La lysine"]'::jsonb, 2, 'Son radical porte un groupe –SH ; deux –SH peuvent se lier par une liaison covalente S–S.', 2),
    ('d5829737-c096-5043-9086-9e7fc7d32bb7'::uuid, '81a0c531-2555-52e5-a8fa-0f59ccf5c1f0'::uuid, 'La liaison peptidique relie…', 'mcq', '["Le –COOH d’un acide aminé et le –NH₂ du suivant","Deux oses","Deux radicaux R","Deux cystéines"]'::jsonb, 0, 'C’est une fonction amide, formée avec élimination d’eau.', 3),
    ('418e7eb6-d47c-5ff5-9680-ae5b13ec0578'::uuid, '81a0c531-2555-52e5-a8fa-0f59ccf5c1f0'::uuid, 'La structure primaire d’une protéine est…', 'mcq', '["Sa forme en 3D","Sa masse","Le nombre de ponts disulfure","La séquence de ses acides aminés"]'::jsonb, 3, 'Elle est lue de l’extrémité N-terminale vers l’extrémité C-terminale.', 4),
    ('4c3d8730-55fd-50b8-9e82-43f434cd7ea1'::uuid, '81a0c531-2555-52e5-a8fa-0f59ccf5c1f0'::uuid, 'La valine est un acide aminé…', 'mcq', '["Chargé positivement","Hydrophobe","Chargé négativement","Soufré"]'::jsonb, 1, 'Son radical est une chaîne carbonée sans groupe polaire.', 5),
    ('7fa44bfa-362d-5ae0-8752-51700861f153'::uuid, '81a0c531-2555-52e5-a8fa-0f59ccf5c1f0'::uuid, 'À pH 7, la lysine est chargée…', 'mcq', '["Négativement","Doublement négativement","Elle est neutre","Positivement"]'::jsonb, 3, 'Son radical se termine par une fonction amine, protonée en –NH₃⁺.', 6),
    ('7e017773-46e4-5204-afdd-380eb4202d7d'::uuid, '81a0c531-2555-52e5-a8fa-0f59ccf5c1f0'::uuid, 'Les protéines humaines sont formées d’acides aminés de la série L.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'En projection de Fischer, leur –NH₂ est à gauche du carbone α.', 7),
    ('80906cd3-bdcd-5f1c-9bcc-9d06af675172'::uuid, '81a0c531-2555-52e5-a8fa-0f59ccf5c1f0'::uuid, 'Pourquoi le carbone α est-il asymétrique (sauf pour la glycine) ?', 'mcq', '["Il est chargé","Il porte deux hydrogènes","Il porte quatre groupes différents","Il est lié à un soufre"]'::jsonb, 2, 'Un carbone asymétrique porte quatre substituants tous différents.', 8),
    ('18ea9811-0305-519a-a4e4-06657c2e673a'::uuid, '81a0c531-2555-52e5-a8fa-0f59ccf5c1f0'::uuid, 'Une protéine dénaturée par la chaleur…', 'mcq', '["A perdu sa forme tridimensionnelle","A perdu sa séquence","Est devenue un glucide","Fonctionne mieux"]'::jsonb, 0, 'Les liaisons faibles sont rompues ; la séquence, tenue par des liaisons covalentes, reste intacte.', 9),
    ('10a449c0-4575-504b-9af4-cf5fa31f9c1d'::uuid, '81a0c531-2555-52e5-a8fa-0f59ccf5c1f0'::uuid, 'Dans une protéine soluble, les radicaux hydrophobes sont plutôt…', 'mcq', '["À la surface, au contact de l’eau","Regroupés au cœur de la protéine","Absents","Liés à l’ADN"]'::jsonb, 1, 'Ils fuient l’eau : ces interactions hydrophobes stabilisent le repliement.', 10),
    ('8e5e6a2f-5e2a-5642-8c20-b474acb88874'::uuid, '81a0c531-2555-52e5-a8fa-0f59ccf5c1f0'::uuid, 'Une liaison ionique dans une protéine peut s’établir entre…', 'mcq', '["Deux valines","Une lysine et un acide glutamique","Deux sérines","Une glycine et une valine"]'::jsonb, 1, 'Charges opposées : le radical + de la lysine attire le radical − de l’acide glutamique.', 11),
    ('11923700-59ae-51b8-9cc7-303b24bb6b04'::uuid, '81a0c531-2555-52e5-a8fa-0f59ccf5c1f0'::uuid, 'Quel acide aminé n’a pas de carbone asymétrique ?', 'mcq', '["La sérine","La cystéine","La lysine","La glycine"]'::jsonb, 3, 'Son radical est un simple H : le carbone α porte deux H.', 12),
    ('6920a921-d4f6-5300-a90c-8eb167773dc5'::uuid, 'd27f4f8d-268a-5bbb-b648-649b9f8218d0'::uuid, 'Un acide gras saturé…', 'mcq', '["Ne possède aucune double liaison C=C","Possède au moins une double liaison C=C","Est toujours liquide","Contient un noyau stérane"]'::jsonb, 0, 'Saturé en hydrogène : toutes ses liaisons carbone-carbone sont simples.', 1),
    ('8c7b8962-9b48-52b8-a682-9c99b2f52440'::uuid, 'd27f4f8d-268a-5bbb-b648-649b9f8218d0'::uuid, 'Que signifie la notation C18:1 (9) ?', 'mcq', '["9 carbones et 18 hydrogènes","18 doubles liaisons","18 carbones, 1 double liaison partant du carbone 9","1 carbone et 9 oxygènes"]'::jsonb, 2, 'On numérote depuis le carbone de la fonction acide carboxylique.', 2),
    ('6470b003-feda-5ffb-bf03-48aa47bf4df5'::uuid, 'd27f4f8d-268a-5bbb-b648-649b9f8218d0'::uuid, 'Un triglycéride est formé de…', 'mcq', '["Trois glycérols","Glucose et trois acides gras","Glycérol et trois acides gras","Un phosphate et deux acides gras"]'::jsonb, 2, 'C’est un triester du glycérol : la forme de réserve des lipides.', 3),
    ('504c3e91-f1df-56ba-9ee1-ef10ac4c117d'::uuid, 'd27f4f8d-268a-5bbb-b648-649b9f8218d0'::uuid, 'Une molécule amphiphile possède…', 'mcq', '["Une partie hydrophile et une partie hydrophobe","Uniquement une partie hydrophobe","Uniquement une partie hydrophile","Un noyau stérane"]'::jsonb, 0, 'Le phospholipide a une tête hydrophile et deux queues hydrophobes.', 4),
    ('361d09a8-1fc7-57db-907a-183519a2afc1'::uuid, 'd27f4f8d-268a-5bbb-b648-649b9f8218d0'::uuid, 'Dans une bicouche phospholipidique, les queues hydrophobes sont…', 'mcq', '["Tournées vers l’eau","Liées à l’ADN","À l’extérieur de la cellule","Face à face au centre de la membrane"]'::jsonb, 3, 'Elles fuient l’eau et se regroupent au cœur de la bicouche.', 5),
    ('93ab2fec-eebf-517a-bc61-7285083aa5e3'::uuid, 'd27f4f8d-268a-5bbb-b648-649b9f8218d0'::uuid, 'Quelle molécule contient un noyau stérane ?', 'mcq', '["L’acide oléique","La testostérone","Le glycérol","Le glucose"]'::jsonb, 1, 'Les hormones stéroïdes dérivent du cholestérol et en gardent le noyau à quatre cycles.', 6),
    ('4cc6c0e4-de2c-5bc6-809b-1858b0390796'::uuid, 'd27f4f8d-268a-5bbb-b648-649b9f8218d0'::uuid, 'Une liaison O–H est polaire parce que…', 'mcq', '["Elle est ionique","Elle est double","Elle contient du carbone","L’oxygène est plus électronégatif que l’hydrogène"]'::jsonb, 3, 'L’oxygène attire les électrons de la liaison : il porte une charge partielle négative.', 7),
    ('85256aa8-7c40-5e84-8ba4-17c54e42bb41'::uuid, 'd27f4f8d-268a-5bbb-b648-649b9f8218d0'::uuid, 'Un récepteur membranaire fait entrer son messager dans la cellule.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il le fixe et déclenche une réponse ; c’est le transporteur qui fait traverser une molécule.', 8),
    ('6aa86a67-5c41-5e89-a47b-4d6b530ce7ff'::uuid, 'd27f4f8d-268a-5bbb-b648-649b9f8218d0'::uuid, 'Pourquoi les huiles sont-elles liquides à 20 °C ?', 'mcq', '["Elles contiennent de l’eau","Elles n’ont pas d’acides gras","Leurs acides gras insaturés, coudés, s’empilent mal","Elles sont chauffées"]'::jsonb, 2, 'Les doubles liaisons coudent les chaînes et empêchent un empilement serré.', 9),
    ('bc67077a-5757-5b52-a3f8-d6bc6b8ac4a8'::uuid, 'd27f4f8d-268a-5bbb-b648-649b9f8218d0'::uuid, 'Une aquaporine est…', 'mcq', '["Un transporteur d’eau","Un récepteur hormonal","Un phospholipide","Une hormone"]'::jsonb, 0, 'C’est un canal protéique qui laisse passer l’eau à travers la membrane.', 10),
    ('6fd95278-2b0f-57c6-9e59-77db8275c403'::uuid, 'd27f4f8d-268a-5bbb-b648-649b9f8218d0'::uuid, 'Quelle molécule traverse facilement la bicouche lipidique sans protéine ?', 'mcq', '["Un ion Na⁺","Une petite molécule apolaire comme le dioxygène","Le glucose","Une protéine"]'::jsonb, 1, 'Le cœur hydrophobe de la bicouche laisse passer les petites molécules apolaires.', 11),
    ('10e7dced-4063-5a3c-8385-c1a4c3dc0f63'::uuid, 'd27f4f8d-268a-5bbb-b648-649b9f8218d0'::uuid, 'Les zones hydrophiles d’une biomolécule interagissent avec l’eau par…', 'mcq', '["Des ponts disulfure","Des liaisons hydrogène","Des liaisons peptidiques","Des liaisons osidiques"]'::jsonb, 1, 'Les groupes polaires (–OH, –NH, C=O) forment des liaisons hydrogène avec l’eau.', 12),
    ('eeef7fc5-30ce-5d59-a456-01229307faa6'::uuid, 'c648e2a1-ee9d-52bb-831b-fc6a7593bac8'::uuid, 'Un nucléotide est formé de…', 'mcq', '["Un ose et un phosphate seulement","Un acide aminé et un ose","Trois acides gras et un glycérol","Un phosphate, un ose et une base azotée"]'::jsonb, 3, 'Ce sont les trois composants de chaque « lettre » de l’ADN ou de l’ARN.', 1),
    ('b9c3dd71-bd32-5172-8ef4-4827e5e0a1fe'::uuid, 'c648e2a1-ee9d-52bb-831b-fc6a7593bac8'::uuid, 'Quelle base remplace la thymine dans l’ARN ?', 'mcq', '["L’uracile","La cytosine","L’adénine","La guanine"]'::jsonb, 0, 'L’ARN utilise A, U, G et C.', 2),
    ('88c49e3d-ded4-5fa1-8194-9567074b1c9c'::uuid, 'c648e2a1-ee9d-52bb-831b-fc6a7593bac8'::uuid, 'Dans l’ADN, la guanine s’apparie avec…', 'mcq', '["L’adénine","La thymine","La cytosine","L’uracile"]'::jsonb, 2, 'G-C, avec trois liaisons hydrogène.', 3),
    ('d36392d2-ceb8-52af-9af5-33e77fde502d'::uuid, 'c648e2a1-ee9d-52bb-831b-fc6a7593bac8'::uuid, 'Les deux brins d’ADN sont antiparallèles.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’un va de 5′ en 3′, l’autre de 3′ en 5′.', 4),
    ('7962e301-04c7-5f74-b517-6d1266918c5f'::uuid, 'c648e2a1-ee9d-52bb-831b-fc6a7593bac8'::uuid, 'Quel est le brin complémentaire de 5′-AATG-3′, écrit de 5′ vers 3′ ?', 'mcq', '["5′-TTAC-3′","5′-GTAA-3′","5′-CATT-3′","5′-AATG-3′"]'::jsonb, 2, 'Complémentaire : 3′-TTAC-5′, qu’on réécrit de 5′ vers 3′ : 5′-CATT-3′.', 5),
    ('c8dd223f-8365-5e1b-96d5-5920dc659ab2'::uuid, 'c648e2a1-ee9d-52bb-831b-fc6a7593bac8'::uuid, 'Quel ose contient l’ADN ?', 'mcq', '["Le désoxyribose","Le ribose","Le glucose","Le fructose"]'::jsonb, 0, 'ADN = acide désoxyribonucléique.', 6),
    ('a23a0a8c-1966-520a-ab8e-50126bec237e'::uuid, 'c648e2a1-ee9d-52bb-831b-fc6a7593bac8'::uuid, 'Les nucléotides d’un brin sont reliés par des liaisons…', 'mcq', '["Peptidiques","Disulfure","Osidiques","Phosphodiester"]'::jsonb, 3, 'Elles relient le phosphate d’un nucléotide à l’ose du suivant.', 7),
    ('67b04a7c-d12c-5164-b9aa-679bfd00760d'::uuid, 'c648e2a1-ee9d-52bb-831b-fc6a7593bac8'::uuid, 'Pourquoi un ADN riche en G-C se dénature-t-il à plus haute température ?', 'mcq', '["G et C sont plus lourds","Les paires G-C comptent trois liaisons hydrogène","Il est plus court","Il contient de l’uracile"]'::jsonb, 1, 'Il faut plus d’énergie pour rompre trois liaisons hydrogène que deux.', 8),
    ('3302f530-7410-5bcf-affd-954915073f95'::uuid, 'c648e2a1-ee9d-52bb-831b-fc6a7593bac8'::uuid, 'Un ADN contient 30 % d’adénine. Quel est son pourcentage de guanine ?', 'mcq', '["30 %","70 %","40 %","20 %"]'::jsonb, 3, 'A = T = 30 %, il reste 40 % pour G + C, avec G = C = 20 %.', 9),
    ('68c3658e-2816-5e17-a26a-7d6b12e109be'::uuid, 'c648e2a1-ee9d-52bb-831b-fc6a7593bac8'::uuid, 'L’hybridation moléculaire repose sur…', 'mcq', '["La liaison osidique","Les ponts disulfure","La complémentarité des bases","Les interactions ioniques des protéines"]'::jsonb, 2, 'Deux brins complémentaires se réassocient par liaisons hydrogène : une sonde repère ainsi sa séquence cible.', 10),
    ('1591f5bb-9cbb-55c1-944d-50928d19730e'::uuid, 'c648e2a1-ee9d-52bb-831b-fc6a7593bac8'::uuid, 'L’ARN messager est en général…', 'mcq', '["Simple brin et court","Double brin et très long","Circulaire","Fait d’acides aminés"]'::jsonb, 0, 'Il ne copie qu’un gène, sous la forme d’un seul brin.', 11),
    ('07384e26-3a34-57dc-ab1d-4587289398e7'::uuid, 'c648e2a1-ee9d-52bb-831b-fc6a7593bac8'::uuid, 'Par convention, une séquence nucléotidique s’écrit…', 'mcq', '["De 3′ vers 5′","De 5′ vers 3′","De la base la plus lourde à la plus légère","Dans n’importe quel sens"]'::jsonb, 1, 'C’est aussi le sens dans lequel les brins sont synthétisés.', 12),
    ('46259b2a-9fbd-58ca-a2a8-0aae066760c2'::uuid, '6bc4ec12-1cfd-5a24-a147-178f40569743'::uuid, 'Quelle est la taille typique d’une cellule animale ?', 'mcq', '["10 à 100 nm","10 à 100 µm","1 à 10 mm","1 à 10 cm"]'::jsonb, 1, 'On l’observe facilement au microscope optique.', 1),
    ('6a2a5c0d-376d-5261-96f4-abaca5888836'::uuid, '6bc4ec12-1cfd-5a24-a147-178f40569743'::uuid, 'Pour observer la structure d’un virus, on utilise…', 'mcq', '["Une loupe","Un microscope optique","Une radiographie","Un microscope électronique"]'::jsonb, 3, 'Les virus mesurent quelques dizaines à quelques centaines de nanomètres.', 2),
    ('dee9a3a0-073b-5834-8ebf-d0b2e2a86697'::uuid, '6bc4ec12-1cfd-5a24-a147-178f40569743'::uuid, 'Quel organite modifie et emballe les protéines dans des vésicules ?', 'mcq', '["L’appareil de Golgi","La mitochondrie","Le noyau","Le ribosome libre"]'::jsonb, 0, 'Les protéines venues du réticulum y sont triées puis expédiées.', 3),
    ('4506ceb6-c9ea-556c-9d81-996ba66f107f'::uuid, '6bc4ec12-1cfd-5a24-a147-178f40569743'::uuid, 'L’exocytose est…', 'mcq', '["L’entrée de molécules dans la cellule","La division du noyau","La libération du contenu d’une vésicule hors de la cellule","La synthèse d’ATP"]'::jsonb, 2, 'La membrane de la vésicule fusionne avec la membrane plasmique.', 4),
    ('ac43cb1e-1716-5f74-997d-e2e5566ecc51'::uuid, '6bc4ec12-1cfd-5a24-a147-178f40569743'::uuid, 'Une bactérie possède un noyau entouré d’une enveloppe.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est une cellule procaryote : son ADN est libre dans le cytoplasme.', 5),
    ('2f3142c1-88dd-5b00-88df-fe22dc954120'::uuid, '6bc4ec12-1cfd-5a24-a147-178f40569743'::uuid, 'Sur un cliché agrandi 500 fois, une cellule mesure 10 mm. Sa taille réelle est…', 'mcq', '["50 µm","5 µm","20 µm","2 µm"]'::jsonb, 2, '10 mm / 500 = 0,02 mm = 20 µm.', 6),
    ('b03868a6-fc1b-5236-8896-9232466370cd'::uuid, '6bc4ec12-1cfd-5a24-a147-178f40569743'::uuid, 'La radiographie aux rayons X montre surtout…', 'mcq', '["Les os","Les tissus mous","Les ovaires","Les cellules"]'::jsonb, 0, 'Les tissus denses absorbent les rayons X et apparaissent blancs.', 7),
    ('88c07608-5397-572b-90c4-7c5451cc8319'::uuid, '6bc4ec12-1cfd-5a24-a147-178f40569743'::uuid, 'Pourquoi suit-on une grossesse par échographie plutôt que par radiographie ?', 'mcq', '["L’échographie montre mieux les os","Les rayons X ne traversent pas le corps","La radiographie est trop lente","Les ultrasons ne sont pas ionisants et montrent les tissus mous"]'::jsonb, 3, 'Pas de rayonnement ionisant pour le fœtus, et de bons contrastes pour les tissus mous.', 8),
    ('1793941a-fbdc-5af0-a9b8-ddbe99ba2d03'::uuid, '6bc4ec12-1cfd-5a24-a147-178f40569743'::uuid, 'Les pores nucléaires se trouvent…', 'mcq', '["Dans la membrane plasmique","Dans l’enveloppe du noyau","Dans la mitochondrie","Dans l’appareil de Golgi"]'::jsonb, 1, 'Ils permettent les échanges entre noyau et cytoplasme, par exemple la sortie des ARN messagers.', 9),
    ('ffa5a2e8-3665-5561-bcbc-093a4144b6b6'::uuid, '6bc4ec12-1cfd-5a24-a147-178f40569743'::uuid, 'Un épithélium repose sur…', 'mcq', '["Un pore nucléaire","Un chromosome","Un produit de contraste","Une membrane basale"]'::jsonb, 3, 'La membrane basale sépare l’épithélium du tissu conjonctif sous-jacent.', 10),
    ('ad8293eb-cadc-563b-b495-8d97fa4ed465'::uuid, '6bc4ec12-1cfd-5a24-a147-178f40569743'::uuid, '1 µm vaut…', 'mcq', '["1 000 mm","100 nm","1 000 nm","10 nm"]'::jsonb, 2, '1 µm = 10⁻⁶ m et 1 nm = 10⁻⁹ m.', 11),
    ('9c2bbc14-4bd8-5e8e-897a-58b16626d67a'::uuid, '6bc4ec12-1cfd-5a24-a147-178f40569743'::uuid, 'Dans quel ordre une protéine sécrétée circule-t-elle ?', 'mcq', '["Réticulum → Golgi → vésicule → exocytose","Golgi → réticulum → vésicule","Noyau → mitochondrie → Golgi","Vésicule → réticulum → noyau"]'::jsonb, 0, 'C’est la voie de sécrétion, observée par autoradiographie.', 12),
    ('3af35622-f8da-525b-944e-409de452e8e5'::uuid, '4149771e-3880-5487-94c3-5c9914c6d73a'::uuid, 'Le milieu intérieur est constitué…', 'mcq', '["Du liquide intracellulaire","Du liquide extracellulaire : plasma, liquide interstitiel, lymphe","Du contenu du tube digestif","De l’urine"]'::jsonb, 1, 'C’est le liquide qui baigne les cellules.', 1),
    ('f0721cb8-5250-5900-9201-7a4fa1fe3b0c'::uuid, '4149771e-3880-5487-94c3-5c9914c6d73a'::uuid, 'Quel ion est le plus concentré dans le liquide intracellulaire ?', 'mcq', '["Na⁺","K⁺","Cl⁻","Ca²⁺"]'::jsonb, 1, 'Les cellules sont riches en potassium, le milieu extracellulaire en sodium.', 2),
    ('ed398f47-07c9-54b0-9208-f689ad03f388'::uuid, '4149771e-3880-5487-94c3-5c9914c6d73a'::uuid, 'Le liquide interstitiel diffère du plasma surtout par…', 'mcq', '["Sa richesse en globules rouges","Sa richesse en K⁺","Son absence d’eau","Sa pauvreté en grosses protéines"]'::jsonb, 3, 'Les grosses protéines plasmatiques ne traversent pas la paroi des capillaires.', 3),
    ('967cf040-5da7-5d24-8c16-737e3ea4d09e'::uuid, '4149771e-3880-5487-94c3-5c9914c6d73a'::uuid, 'Environ quelle part de l’eau de l’organisme est dans les cellules ?', 'mcq', '["2/3","1/4","1/12","La totalité"]'::jsonb, 0, 'Le liquide intracellulaire est de loin le plus grand compartiment.', 4),
    ('ccde4caa-4d6e-5716-8406-02c29e8cec9d'::uuid, '4149771e-3880-5487-94c3-5c9914c6d73a'::uuid, 'Un globule rouge placé dans de l’eau pure…', 'mcq', '["Se ratatine","Ne change pas","Gonfle et peut éclater","Se divise"]'::jsonb, 2, 'L’eau entre par osmose vers le compartiment le plus concentré, ici la cellule.', 5),
    ('ee567fbe-c70e-589f-a7f9-9ffa3fda5c2d'::uuid, '4149771e-3880-5487-94c3-5c9914c6d73a'::uuid, 'Dans une boucle de régulation, la valeur de consigne est…', 'mcq', '["La réponse de l’effecteur","La perturbation","La valeur de référence autour de laquelle la grandeur est maintenue","Le capteur"]'::jsonb, 2, 'La grandeur régulée est comparée en permanence à cette valeur.', 6),
    ('0ff6ae50-af23-5987-9b7d-8daa1b7dd947'::uuid, '4149771e-3880-5487-94c3-5c9914c6d73a'::uuid, 'La lymphe ramène au sang une partie du liquide interstitiel.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle draine l’excédent de liquide sorti des capillaires.', 7),
    ('9b87817d-2cd4-557b-9fd0-a14935ec9b8a'::uuid, '4149771e-3880-5487-94c3-5c9914c6d73a'::uuid, 'Dans la régulation de l’eau, quel organe est l’effecteur ?', 'mcq', '["Le rein","Le pancréas","Le cœur","Le foie"]'::jsonb, 0, 'Sous l’effet de l’ADH, le tube collecteur réabsorbe plus ou moins d’eau.', 8),
    ('16eea14c-4da0-599c-a475-883c0c774aaf'::uuid, '4149771e-3880-5487-94c3-5c9914c6d73a'::uuid, 'Un intervalle physiologique permet…', 'mcq', '["De dater un fossile","De mesurer la taille d’une cellule","De classer les bactéries","De diagnostiquer un écart à la normale dans un bilan sanguin"]'::jsonb, 3, 'Un résultat hors de l’intervalle de référence signale un dysfonctionnement possible.', 9),
    ('6cdcda5a-8ece-592a-a909-979e9aa955ac'::uuid, '4149771e-3880-5487-94c3-5c9914c6d73a'::uuid, 'Le dioxygène traverse la membrane cellulaire par…', 'mcq', '["Transport actif","Diffusion","Exocytose","Osmose"]'::jsonb, 1, 'Petite molécule apolaire, il suit son gradient à travers la bicouche.', 10),
    ('2731c3bd-0134-5c84-8f18-368d325d3b58'::uuid, '4149771e-3880-5487-94c3-5c9914c6d73a'::uuid, 'L’homéostasie repose sur une rétroaction…', 'mcq', '["Positive","Aléatoire","Absente","Négative"]'::jsonb, 3, 'La réponse corrige l’écart à la consigne au lieu de l’amplifier.', 11),
    ('19636bab-ef7e-5759-8d46-e8ca18a1511a'::uuid, '4149771e-3880-5487-94c3-5c9914c6d73a'::uuid, 'Quel liquide contient des globules rouges ?', 'mcq', '["Le liquide interstitiel","La lymphe canalisée","Le sang","Le liquide intracellulaire"]'::jsonb, 2, 'Les globules rouges restent dans les vaisseaux sanguins ; seul le plasma filtre vers les tissus.', 12),
    ('6a6ff5ae-fc69-55e9-be7c-b112beda0afb'::uuid, '8675a43b-af6f-55c7-a8e5-0cc8215c414d'::uuid, 'Où a lieu la transcription chez les eucaryotes ?', 'mcq', '["Dans le noyau","Dans le cytoplasme","Dans le ribosome","Dans l’appareil de Golgi"]'::jsonb, 0, 'L’ARNm est fabriqué dans le noyau, puis sort par les pores nucléaires.', 1),
    ('f789fc49-dd28-54f3-82dc-62a8055b1d0d'::uuid, '8675a43b-af6f-55c7-a8e5-0cc8215c414d'::uuid, 'Quelle enzyme synthétise l’ARN messager ?', 'mcq', '["L’ADN polymérase","L’ARN polymérase","La ligase","L’amylase"]'::jsonb, 1, 'Elle copie le brin transcrit de l’ADN en ARN.', 2),
    ('bc08e849-097a-59c7-b714-165e941be11a'::uuid, '8675a43b-af6f-55c7-a8e5-0cc8215c414d'::uuid, 'Un codon est formé de…', 'mcq', '["Un nucléotide","Trois nucléotides","Deux nucléotides","Un acide aminé"]'::jsonb, 1, 'Chaque triplet de l’ARNm correspond à un acide aminé ou à un signal stop.', 3),
    ('43130513-1e61-5227-9636-0eb8c9d9871d'::uuid, '8675a43b-af6f-55c7-a8e5-0cc8215c414d'::uuid, 'Le codon AUG…', 'mcq', '["Est un codon stop","Code la valine","Ne code rien","Initie la traduction et code la méthionine"]'::jsonb, 3, 'Il fixe le cadre de lecture.', 4),
    ('211a2706-09bc-560c-9ee4-3d59353dd219'::uuid, '8675a43b-af6f-55c7-a8e5-0cc8215c414d'::uuid, 'Le brin transcrit est 3′-TAC-5′. Quel est le codon de l’ARNm ?', 'mcq', '["5′-AUG-3′","5′-ATG-3′","5′-UAC-3′","5′-TAC-3′"]'::jsonb, 0, 'Complémentaire du brin transcrit, avec U à la place de T.', 5),
    ('ab9ab4a8-2326-55a8-afeb-062b1721a047'::uuid, '8675a43b-af6f-55c7-a8e5-0cc8215c414d'::uuid, 'Une mutation non-sens…', 'mcq', '["Ne change rien à la protéine","Remplace un acide aminé par un autre","Fait apparaître un codon stop prématuré","Ajoute un gène"]'::jsonb, 2, 'La protéine est tronquée, souvent non fonctionnelle.', 6),
    ('f00138a5-5aa5-5190-b954-65221ebc4ad8'::uuid, '8675a43b-af6f-55c7-a8e5-0cc8215c414d'::uuid, 'Grâce à la redondance du code génétique, certaines mutations sont silencieuses.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Plusieurs codons codent le même acide aminé : la protéine reste identique.', 7),
    ('8184463e-5713-5a70-8428-b963e5f50203'::uuid, '8675a43b-af6f-55c7-a8e5-0cc8215c414d'::uuid, 'La mutation de la drépanocytose (Glu → Val) est une mutation…', 'mcq', '["Silencieuse","Non-sens","Faux-sens","Par décalage du cadre de lecture"]'::jsonb, 2, 'Un acide aminé est remplacé par un autre.', 8),
    ('273e985e-59f5-5d01-ae3e-2a306470a522'::uuid, '8675a43b-af6f-55c7-a8e5-0cc8215c414d'::uuid, 'Pourquoi la délétion d’un seul nucléotide a-t-elle souvent des effets graves ?', 'mcq', '["Elle décale le cadre de lecture : tous les codons suivants changent","Elle détruit l’ARN polymérase","Elle supprime un chromosome","Elle empêche la transcription"]'::jsonb, 0, 'La lecture par triplets est décalée à partir de la mutation.', 9),
    ('6ea0dbf7-4a9b-5ba1-a2f1-a8d897a7c350'::uuid, '8675a43b-af6f-55c7-a8e5-0cc8215c414d'::uuid, 'Où se fait la traduction ?', 'mcq', '["Dans le noyau","Dans la membrane plasmique","Dans les mitochondries uniquement","Sur les ribosomes du cytoplasme"]'::jsonb, 3, 'Les ribosomes lisent l’ARNm et assemblent les acides aminés.', 10),
    ('c81bcc39-4dcb-5f20-beb3-ff3e33c74654'::uuid, '8675a43b-af6f-55c7-a8e5-0cc8215c414d'::uuid, 'L’ARNm 5′-AUG CCU AAG UAA-3′ donne le peptide…', 'mcq', '["Met-Pro-Lys-Stop-Met","Met-Pro-Lys","Pro-Lys","Met-Lys-Pro"]'::jsonb, 1, 'UAA est un codon stop : il arrête la traduction sans ajouter d’acide aminé.', 11),
    ('5be2c126-2367-5ea8-98dd-0c427df11503'::uuid, '8675a43b-af6f-55c7-a8e5-0cc8215c414d'::uuid, 'Combien de codons comporte le code génétique ?', 'mcq', '["20","61","4","64"]'::jsonb, 3, '4³ = 64 codons : 61 codent des acides aminés, 3 sont des codons stop.', 12),
    ('900e23c0-da09-5ef1-aa73-62e17db7b513'::uuid, 'b05dceba-9b2a-5c69-b397-6d5aff38ce52'::uuid, 'Pendant quelle phase l’ADN est-il répliqué ?', 'mcq', '["G1","G2","S","M"]'::jsonb, 2, 'S comme synthèse : chaque chromosome passe de une à deux chromatides.', 1),
    ('08c4668b-e181-5b71-a0b9-45f122af4c25'::uuid, 'b05dceba-9b2a-5c69-b397-6d5aff38ce52'::uuid, 'La réplication est dite semi-conservative parce que…', 'mcq', '["Chaque molécule fille garde un brin ancien et reçoit un brin neuf","La moitié de l’ADN est détruite","Seule la moitié des gènes est copiée","Elle se fait à moitié dans le noyau"]'::jsonb, 0, 'Chaque brin parental sert de modèle.', 2),
    ('1c8b8df8-44e5-5fcb-8657-2eede95ac919'::uuid, 'b05dceba-9b2a-5c69-b397-6d5aff38ce52'::uuid, 'Quelle enzyme réplique l’ADN ?', 'mcq', '["L’ARN polymérase","L’ADN polymérase","La pepsine","La lipase"]'::jsonb, 1, 'Elle ajoute des nucléotides complémentaires du brin modèle.', 3),
    ('dffcd6ed-d46d-542b-aa69-b83be0291e63'::uuid, 'b05dceba-9b2a-5c69-b397-6d5aff38ce52'::uuid, 'Pendant l’anaphase de mitose, ce qui se sépare, ce sont…', 'mcq', '["Les chromosomes homologues","Les chromatides sœurs","Les noyaux","Les ribosomes"]'::jsonb, 1, 'Chaque cellule fille reçoit une chromatide de chaque chromosome.', 4),
    ('b7ee2045-ec02-519e-bd52-fc40ccfdc452'::uuid, 'b05dceba-9b2a-5c69-b397-6d5aff38ce52'::uuid, 'Le fuseau mitotique est constitué de…', 'mcq', '["Glycogène","Phospholipides","ARN messager","Microtubules"]'::jsonb, 3, 'Ces fibres protéiques tirent les chromatides vers les pôles.', 5),
    ('7f3d0e54-b59f-5956-abb7-d5562be0c4c2'::uuid, 'b05dceba-9b2a-5c69-b397-6d5aff38ce52'::uuid, 'En métaphase, les chromosomes…', 'mcq', '["S’alignent au centre de la cellule","Sont décondensés dans le noyau","Migrent vers les pôles","Se répliquent"]'::jsonb, 0, 'Ils forment la plaque équatoriale, le meilleur moment pour les photographier.', 6),
    ('cf3b8ab4-db34-54c3-abed-2def366407cd'::uuid, 'b05dceba-9b2a-5c69-b397-6d5aff38ce52'::uuid, 'Si une cellule en G1 contient une quantité q d’ADN, combien en contient-elle en G2 ?', 'mcq', '["q/2","q","2q","4q"]'::jsonb, 2, 'La phase S a doublé l’ADN.', 7),
    ('f8615544-0328-55c1-bbc7-e9e1c87a5f4a'::uuid, 'b05dceba-9b2a-5c69-b397-6d5aff38ce52'::uuid, 'Après une méiose complète, chaque gamète contient…', 'mcq', '["2q","q","q/2","4q"]'::jsonb, 2, 'Deux divisions successives à partir de 2q : q puis q/2.', 8),
    ('441aad9a-0069-56a3-81a2-37c1d10e7698'::uuid, 'b05dceba-9b2a-5c69-b397-6d5aff38ce52'::uuid, 'Les deux cellules filles d’une mitose ont la même information génétique.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La réplication fidèle puis la séparation des chromatides sœurs donnent deux copies identiques.', 9),
    ('a39af63f-27e8-5ad7-97f4-0f40de2e4f3c'::uuid, 'b05dceba-9b2a-5c69-b397-6d5aff38ce52'::uuid, 'Une cellule humaine montre 23 chromosomes à deux chromatides alignés au centre. C’est…', 'mcq', '["Une métaphase II de méiose","Une métaphase de mitose","Une prophase I","Une interphase"]'::jsonb, 0, 'La cellule est déjà haploïde mais ses chromosomes ont encore deux chromatides.', 10),
    ('c7fd2b3d-cffc-5b62-b6a6-178532d7ee97'::uuid, 'b05dceba-9b2a-5c69-b397-6d5aff38ce52'::uuid, 'Quelle est la phase la plus longue du cycle cellulaire en général ?', 'mcq', '["La mitose","L’anaphase","La métaphase","L’interphase"]'::jsonb, 3, 'La mitose ne dure qu’environ une heure sur un cycle de près d’un jour.', 11),
    ('05bc7083-8b00-557f-81be-42851b04f16c'::uuid, 'b05dceba-9b2a-5c69-b397-6d5aff38ce52'::uuid, 'Une erreur de réplication non corrigée est…', 'mcq', '["Une transcription","Une mutation","Une traduction","Une hybridation"]'::jsonb, 1, 'Elle sera transmise aux cellules filles.', 12),
    ('d63066d6-91d4-5667-a4aa-e6bbdf13252e'::uuid, '2cb2ace2-f2ab-504e-b71a-315145f15671'::uuid, 'Une réaction dont ΔrG’° vaut +20 kJ·mol⁻¹ est…', 'mcq', '["Endergonique","Exergonique","Toujours instantanée","Catalysée par l’ATP seul"]'::jsonb, 0, 'Un ΔrG’° positif signe une réaction endergonique, impossible seule dans le sens écrit en conditions standard.', 1),
    ('f605b3a9-46a2-57fc-9920-7ccd460553b3'::uuid, '2cb2ace2-f2ab-504e-b71a-315145f15671'::uuid, 'Le cycle de Calvin est une voie…', 'mcq', '["Catabolique","Anabolique","Fermentaire","De dégradation des lipides"]'::jsonb, 1, 'Il synthétise des glucides à partir de CO₂ : c’est de l’anabolisme, qui consomme de l’ATP.', 2),
    ('f1898f92-0fa4-55f3-88c9-b90a73363b13'::uuid, '2cb2ace2-f2ab-504e-b71a-315145f15671'::uuid, 'Réaction A : +13,8 kJ·mol⁻¹ ; hydrolyse de l’ATP : −30,5 kJ·mol⁻¹. ΔrG’° de la réaction couplée ?', 'mcq', '["+44,3 kJ·mol⁻¹","−44,3 kJ·mol⁻¹","−16,7 kJ·mol⁻¹","+16,7 kJ·mol⁻¹"]'::jsonb, 2, 'On additionne les ΔrG’° : 13,8 − 30,5 = −16,7 kJ·mol⁻¹, négatif, donc spontané.', 3),
    ('2bf4bcbe-9958-56c3-b956-cce414ea7742'::uuid, '2cb2ace2-f2ab-504e-b71a-315145f15671'::uuid, 'L’hydrolyse de l’ATP libère de l’énergie car elle rompt…', 'mcq', '["La liaison entre le ribose et l’adénine","Une liaison peptidique","Une liaison hydrogène de l’ADN","Une liaison à haut potentiel énergétique"]'::jsonb, 3, 'Les liaisons entre phosphates de l’ATP sont dites à haut potentiel énergétique.', 4),
    ('bd751048-2a94-533c-9519-bc8df4938bee'::uuid, '2cb2ace2-f2ab-504e-b71a-315145f15671'::uuid, 'Dans le couple NAD⁺/NADH, la forme réduite est…', 'mcq', '["NADH","NAD⁺","FAD","ADP"]'::jsonb, 0, 'NADH a capté deux électrons (et un proton) : c’est la forme réduite du coenzyme.', 5),
    ('83352852-03b6-5b8e-bb18-f237771f7d24'::uuid, '2cb2ace2-f2ab-504e-b71a-315145f15671'::uuid, 'Les électrons passent spontanément du couple au E’° le plus…', 'mcq', '["Haut vers le plus bas","Bas vers le plus haut","Proche de zéro vers le plus éloigné","Négatif vers un autre négatif seulement"]'::jsonb, 1, 'Le donneur a le potentiel le plus bas, l’accepteur le plus haut ; ΔE’° positif donne ΔrG’° négatif.', 6),
    ('b1688368-edc6-580b-bbd6-76036e4e33d8'::uuid, '2cb2ace2-f2ab-504e-b71a-315145f15671'::uuid, 'Une réaction couplée est spontanée si la somme de ses ΔrG’° est négative.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est tout l’intérêt du couplage : une étape endergonique est entraînée par une étape plus exergonique.', 7),
    ('45b2b32c-6f75-5880-83b6-a678fb5d370e'::uuid, '2cb2ace2-f2ab-504e-b71a-315145f15671'::uuid, 'Les conditions standard biologiques imposent notamment…', 'mcq', '["pH 0","100 °C","pH 7","Absence d’eau"]'::jsonb, 2, 'Le « prime » de ΔrG’° et E’° rappelle qu’on se place à pH 7.', 8),
    ('a551e6b2-8266-5bc6-ac45-ae7c23dcdd88'::uuid, '2cb2ace2-f2ab-504e-b71a-315145f15671'::uuid, 'Quel coenzyme est réduit en FADH₂ ?', 'mcq', '["NAD⁺","NADP⁺","ATP","FAD"]'::jsonb, 3, 'FAD capte deux électrons et deux protons : FAD + 2 e⁻ + 2 H⁺ → FADH₂.', 9),
    ('b3fcd027-3816-54ec-9f2c-374e53a902c0'::uuid, '2cb2ace2-f2ab-504e-b71a-315145f15671'::uuid, 'ΔrG’° = −n × F × ΔE’°. Si ΔE’° = +0,5 V et n = 2, ΔrG’° vaut environ…', 'mcq', '["−96,5 kJ·mol⁻¹","+96,5 kJ·mol⁻¹","−48 kJ·mol⁻¹","−9,65 kJ·mol⁻¹"]'::jsonb, 0, '2 × 96 500 × 0,5 = 96 500 J·mol⁻¹, soit −96,5 kJ·mol⁻¹ : réaction favorable.', 10),
    ('984e7c6b-49a9-57c3-83c5-2dc5c261a96f'::uuid, '2cb2ace2-f2ab-504e-b71a-315145f15671'::uuid, 'La glycogénolyse est…', 'mcq', '["Une synthèse de glycogène","Une dégradation de glycogène","Une fermentation","Une voie de la photosynthèse"]'::jsonb, 1, 'Le suffixe « -lyse » indique une dégradation : c’est une voie catabolique.', 11),
    ('bbf25bbb-4dc0-5dc6-b2ba-881baca58b24'::uuid, '2cb2ace2-f2ab-504e-b71a-315145f15671'::uuid, 'Une réaction à ΔrG’° positif ne peut jamais se produire dans une cellule.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle peut avoir lieu si elle est couplée, ou si les concentrations réelles rendent ΔrG négatif.', 12),
    ('f465f285-d453-577e-83a9-514001d62a49'::uuid, '04d0768b-cc46-52fb-b878-739ebbd757ad'::uuid, 'Où se déroule la glycolyse ?', 'mcq', '["Dans la matrice mitochondriale","Dans le noyau","Dans le cytoplasme","Sur la membrane interne de la mitochondrie"]'::jsonb, 2, 'La glycolyse est cytoplasmique, chez les procaryotes comme chez les eucaryotes.', 1),
    ('ee3ac42f-5892-57d2-a494-56d7991068a2'::uuid, '04d0768b-cc46-52fb-b878-739ebbd757ad'::uuid, 'Bilan net en ATP de la glycolyse par glucose ?', 'mcq', '["38","4","30","2"]'::jsonb, 3, 'Deux ATP nets, formés par phosphorylation au niveau du substrat.', 2),
    ('c25e7d47-ca73-593e-9830-b120c8985008'::uuid, '04d0768b-cc46-52fb-b878-739ebbd757ad'::uuid, 'L’accepteur final d’électrons de la respiration aérobie est…', 'mcq', '["Le dioxygène","Le pyruvate","Le NAD⁺","Le CO₂"]'::jsonb, 0, 'Le dioxygène est réduit en eau au bout de la chaîne respiratoire.', 3),
    ('086276d2-8808-5274-a70a-0919e0e07d34'::uuid, '04d0768b-cc46-52fb-b878-739ebbd757ad'::uuid, 'Le couplage chimio-osmotique relie…', 'mcq', '["La glycolyse et la fermentation","Le flux de protons à travers l’ATP synthase et la synthèse d’ATP","Le cycle de Krebs et la photosynthèse","La transcription et la traduction"]'::jsonb, 1, 'Le reflux des protons à travers l’ATP synthase fournit l’énergie de synthèse de l’ATP.', 4),
    ('2b5e5d57-c883-5241-ab0a-674930df04b5'::uuid, '04d0768b-cc46-52fb-b878-739ebbd757ad'::uuid, 'Le rôle essentiel des dernières étapes d’une fermentation est de…', 'mcq', '["Produire du dioxygène","Fabriquer 30 ATP","Réoxyder le NADH en NAD⁺","Fixer le CO₂"]'::jsonb, 2, 'Sans NAD⁺ régénéré, la glycolyse s’arrêterait faute d’accepteur d’électrons.', 5),
    ('4f660984-dec6-5cc3-af13-2235e89b8f73'::uuid, '04d0768b-cc46-52fb-b878-739ebbd757ad'::uuid, 'La fermentation alcoolique produit…', 'mcq', '["Du lactate seul","Du dioxygène","De l’eau et du CO₂","De l’éthanol et du CO₂"]'::jsonb, 3, 'Le pyruvate est décarboxylé en acétaldéhyde, lui-même réduit en éthanol.', 6),
    ('53d70b1b-eb48-52a4-8da0-e43349dfa2bf'::uuid, '04d0768b-cc46-52fb-b878-739ebbd757ad'::uuid, 'La phosphorylation oxydative a lieu…', 'mcq', '["Au niveau de la membrane interne mitochondriale","Dans le cytoplasme","Dans le noyau","Dans le chloroplaste"]'::jsonb, 0, 'Chaîne respiratoire et ATP synthase sont insérées dans la membrane interne.', 7),
    ('066da616-25de-5408-9478-dabcb571417d'::uuid, '04d0768b-cc46-52fb-b878-739ebbd757ad'::uuid, 'Une bactérie qui réduit le nitrate en absence d’O₂ fait…', 'mcq', '["Une fermentation","Une respiration anaérobie","Une photosynthèse","Une glycogénolyse"]'::jsonb, 1, 'Elle possède un accepteur final externe (le nitrate) : c’est une respiration, sans oxygène.', 8),
    ('c03ebf4c-8b6a-5acc-bfbf-ba0326d6081e'::uuid, '04d0768b-cc46-52fb-b878-739ebbd757ad'::uuid, 'Pourquoi la fermentation rapporte-t-elle peu d’ATP ?', 'mcq', '["Le glucose n’y est pas oxydé du tout","Elle détruit l’ATP formé","L’oxydation est partielle : le produit final garde de l’énergie","Elle a lieu dans la mitochondrie"]'::jsonb, 2, 'Lactate ou éthanol contiennent encore beaucoup d’énergie chimique.', 9),
    ('4625659d-b285-509e-9abc-76f30a46dd3a'::uuid, '04d0768b-cc46-52fb-b878-739ebbd757ad'::uuid, 'Dans le cycle de Krebs, le carbone du glucose est libéré sous forme de…', 'mcq', '["Glycogène","Éthanol","Lactate","CO₂"]'::jsonb, 3, 'Les décarboxylations du cycle de Krebs rejettent le carbone en CO₂.', 10),
    ('01387410-77aa-5579-bf43-aa2e0cd608bf'::uuid, '04d0768b-cc46-52fb-b878-739ebbd757ad'::uuid, 'Pour produire un maximum de biomasse de levures, on cultive…', 'mcq', '["En aérobiose","En anaérobiose stricte","Sans glucose","À pH 1"]'::jsonb, 0, 'La respiration donne bien plus d’ATP, donc plus de croissance.', 11),
    ('652a444b-1a55-532c-b7df-abdf8008ca26'::uuid, '04d0768b-cc46-52fb-b878-739ebbd757ad'::uuid, 'Anaérobie veut toujours dire fermentation.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Certaines bactéries respirent sans oxygène avec un autre accepteur final, comme le nitrate.', 12),
    ('dfe172e1-c5c6-55cd-b449-02612fead5b6'::uuid, '67b868d8-bcd5-5081-a4b8-fd3ff7903d1a'::uuid, 'Où se déroule le cycle de Calvin ?', 'mcq', '["Dans les thylakoïdes","Dans le stroma du chloroplaste","Dans la matrice mitochondriale","Dans le cytoplasme"]'::jsonb, 1, 'La fixation du CO₂ a lieu dans le stroma, grâce à l’ATP et au NADPH des thylakoïdes.', 1),
    ('e1471f09-3557-5bc8-b87e-ecb26617b47a'::uuid, '67b868d8-bcd5-5081-a4b8-fd3ff7903d1a'::uuid, 'Le dioxygène de la photosynthèse provient…', 'mcq', '["Du CO₂","Du glucose","De l’oxydation de l’eau","Du NADPH"]'::jsonb, 2, 'L’eau cède ses électrons à la chaîne photosynthétique et libère O₂.', 2),
    ('f32531e0-3967-5757-b1fb-2242ec54fed2'::uuid, '67b868d8-bcd5-5081-a4b8-fd3ff7903d1a'::uuid, 'Quelles molécules la chaîne photosynthétique fournit-elle au cycle de Calvin ?', 'mcq', '["NADH et CO₂","Glucose et O₂","Pyruvate et ATP","NADPH et ATP"]'::jsonb, 3, 'Le cycle de Calvin consomme NADPH (électrons) et ATP (énergie).', 3),
    ('8f551abd-f422-5e38-a63d-f5efa6fd2551'::uuid, '67b868d8-bcd5-5081-a4b8-fd3ff7903d1a'::uuid, 'Une plante verte est…', 'mcq', '["Photolithoautotrophe","Chimioorganohétérotrophe","Chimiolithoautotrophe","Photoorganohétérotrophe"]'::jsonb, 0, 'Énergie lumineuse, électrons de l’eau (minérale), carbone du CO₂.', 4),
    ('a4a7e49a-97b8-5308-b95e-032ab3d75a8e'::uuid, '67b868d8-bcd5-5081-a4b8-fd3ff7903d1a'::uuid, 'Le préfixe « organo- » renseigne sur…', 'mcq', '["La source d’énergie","La source d’électrons","La source de carbone","La température de culture"]'::jsonb, 1, 'Organo- : les électrons viennent d’une molécule organique ; litho- : d’un composé minéral.', 5),
    ('08e68727-5ef4-5d7e-96c0-5350ff0d89d2'::uuid, '67b868d8-bcd5-5081-a4b8-fd3ff7903d1a'::uuid, 'La nitrification transforme…', 'mcq', '["NO₃⁻ en N₂","N₂ en NH₄⁺","NH₄⁺ en NO₂⁻ puis NO₃⁻","La matière organique en NH₄⁺"]'::jsonb, 2, 'Deux étapes d’oxydation menées par des bactéries chimiolithoautotrophes.', 6),
    ('d8e08a12-f7ec-506c-bdee-da192c8ce1a1'::uuid, '67b868d8-bcd5-5081-a4b8-fd3ff7903d1a'::uuid, 'La dénitrification…', 'mcq', '["Enrichit le sol en nitrates","Fixe le CO₂","Est une photosynthèse","Rend l’azote à l’atmosphère sous forme de N₂"]'::jsonb, 3, 'C’est une respiration anaérobie qui utilise le nitrate comme accepteur final.', 7),
    ('8ae6706a-7006-5030-a0ed-37b9812d8737'::uuid, '67b868d8-bcd5-5081-a4b8-fd3ff7903d1a'::uuid, 'L’association Rhizobium – Fabacées est un exemple de…', 'mcq', '["Symbiose","Compétition","Parasitisme","Saprophytisme"]'::jsonb, 0, 'La bactérie fixe le diazote pour la plante, qui lui fournit des molécules organiques.', 8),
    ('c23f9bee-e20a-548c-864c-6edeec8a7ce7'::uuid, '67b868d8-bcd5-5081-a4b8-fd3ff7903d1a'::uuid, 'La minéralisation transforme de la matière organique en composés minéraux.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est l’inverse de l’assimilation ; l’ammonification en est un exemple.', 9),
    ('b4e1f1d3-1b6b-5979-90e0-7a7d7a3ceab2'::uuid, '67b868d8-bcd5-5081-a4b8-fd3ff7903d1a'::uuid, 'Une bactérie autotrophe peut se cultiver sur un milieu…', 'mcq', '["Obligatoirement riche en glucose","Sans source organique de carbone","Sans aucune source d’énergie","Contenant forcément du sang"]'::jsonb, 1, 'Elle tire son carbone du CO₂ : le milieu peut être entièrement minéral.', 10),
    ('dc7a80e9-9cea-567a-8070-488383ecc039'::uuid, '67b868d8-bcd5-5081-a4b8-fd3ff7903d1a'::uuid, 'Point commun entre chaîne respiratoire et chaîne photosynthétique ?', 'mcq', '["Elles consomment du CO₂","Elles ont lieu dans le noyau","Elles utilisent un gradient de protons et une ATP synthase","Elles produisent de l’éthanol"]'::jsonb, 2, 'Le couplage chimio-osmotique est commun aux deux.', 11),
    ('57cc1485-c78e-5d37-8d2f-fdc616fd2077'::uuid, '67b868d8-bcd5-5081-a4b8-fd3ff7903d1a'::uuid, 'Un ensemble de micro-organismes fixés sur une surface dans une matrice qu’ils sécrètent forme…', 'mcq', '["Un plasmide","Un auxanogramme","Un nodule","Un biofilm"]'::jsonb, 3, 'Le biofilm protège ses habitants et favorise leur coopération.', 12),
    ('631e1df3-39be-5fac-8b81-aed6b33d1b96'::uuid, '6bda461e-b0d7-528a-9626-557ae8ddf2d3'::uuid, 'Une enzyme qui n’agit que sur le glucose présente une spécificité…', 'mcq', '["De substrat","De réaction","De température","De pH"]'::jsonb, 0, 'Elle reconnaît une seule molécule : c’est la spécificité de substrat.', 1),
    ('1501bdeb-e70d-53fa-a904-c3e88b150983'::uuid, '6bda461e-b0d7-528a-9626-557ae8ddf2d3'::uuid, 'Le pepsinogène est…', 'mcq', '["Un coenzyme","Une proenzyme, forme inactive de la pepsine","Un inhibiteur compétitif","Un ion métallique"]'::jsonb, 1, 'Il est activé en pepsine dans le milieu acide de l’estomac.', 2),
    ('457d885d-793d-5722-b372-4fe75580d497'::uuid, '6bda461e-b0d7-528a-9626-557ae8ddf2d3'::uuid, 'La vitesse initiale se lit…', 'mcq', '["Sur le plateau final de la courbe","À la fin de la réaction","Comme la pente de la partie linéaire au début","Sur l’axe des ordonnées à t = 0"]'::jsonb, 2, 'Au début, la quantité de produit croît linéairement : la pente est v₀.', 3),
    ('8ccebdee-a1f0-5141-ad4e-d4a19005f8ee'::uuid, '6bda461e-b0d7-528a-9626-557ae8ddf2d3'::uuid, 'Quand v₀ n’augmente plus malgré l’ajout de substrat, l’enzyme est…', 'mcq', '["Dénaturée","Transformée en proenzyme","Inhibée par le froid","Saturée"]'::jsonb, 3, 'Tous les sites actifs sont occupés : v₀ atteint Vmax.', 4),
    ('46282cd0-98d7-56b6-83cc-360c31977072'::uuid, '6bda461e-b0d7-528a-9626-557ae8ddf2d3'::uuid, 'Km est la concentration en substrat pour laquelle…', 'mcq', '["v₀ = Vmax / 2","v₀ = Vmax","v₀ = 0","L’enzyme est dénaturée"]'::jsonb, 0, 'Un Km faible traduit une forte affinité de l’enzyme pour son substrat.', 5),
    ('2f8cf4b7-7d3c-5991-951e-27d65fbe5d5c'::uuid, '6bda461e-b0d7-528a-9626-557ae8ddf2d3'::uuid, 'Un inhibiteur analogue structural du substrat agit…', 'mcq', '["En dénaturant l’enzyme par la chaleur","En occupant le site actif à la place du substrat","En augmentant la température","En détruisant le produit"]'::jsonb, 1, 'Sa forme proche du substrat lui permet d’entrer en compétition pour le site actif.', 6),
    ('729f951f-a378-5938-b905-11efcdae5326'::uuid, '6bda461e-b0d7-528a-9626-557ae8ddf2d3'::uuid, 'Au-delà de la température optimale, l’activité chute car…', 'mcq', '["Le substrat s’évapore","Le pH devient neutre","L’enzyme se dénature","Le Km devient nul"]'::jsonb, 2, 'La structure tridimensionnelle est perdue, donc le site actif aussi.', 7),
    ('075175f6-42de-501d-8fd1-78327b7ce474'::uuid, '6bda461e-b0d7-528a-9626-557ae8ddf2d3'::uuid, 'Le NAD⁺ est, pour une déshydrogénase…', 'mcq', '["Un substrat unique","Un ion métallique","Un inhibiteur","Un coenzyme"]'::jsonb, 3, 'C’est un coenzyme, dérivé de la vitamine B3, qui accepte les électrons.', 8),
    ('9640753b-1f89-50db-bc4c-db37168474d8'::uuid, '6bda461e-b0d7-528a-9626-557ae8ddf2d3'::uuid, 'Un cofacteur resté fixé à l’enzyme de façon permanente est un…', 'mcq', '["Groupement prosthétique","Substrat","Produit","Anticorps"]'::jsonb, 0, 'Exemple : l’hème de certaines enzymes.', 9),
    ('533337fe-2aff-5760-9616-b869973a3305'::uuid, '6bda461e-b0d7-528a-9626-557ae8ddf2d3'::uuid, 'La rétro-inhibition, c’est…', 'mcq', '["L’activation d’une enzyme par la chaleur","L’inhibition d’une enzyme du début d’une voie par le produit final","La transformation d’une proenzyme","La dénaturation par un acide"]'::jsonb, 1, 'Le produit final règle sa propre production : c’est une boucle de régulation.', 10),
    ('7d1c384a-d9f3-5bde-b33e-cf7036df4cc9'::uuid, '6bda461e-b0d7-528a-9626-557ae8ddf2d3'::uuid, 'Un passage au réfrigérateur détruit définitivement une enzyme.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le froid ralentit l’activité sans dénaturer : c’est pourquoi on conserve les enzymes au froid.', 11),
    ('1e3c2303-02e7-58bd-8717-624ff7a8dd55'::uuid, '6bda461e-b0d7-528a-9626-557ae8ddf2d3'::uuid, 'Le pH optimal de la trypsine, enzyme intestinale, est proche de…', 'mcq', '["2","12","8","0"]'::jsonb, 2, 'Elle agit dans l’intestin grêle, légèrement basique, contrairement à la pepsine gastrique.', 12),
    ('69b203a8-955b-52dc-9cf6-3d7e7ce8b7fd'::uuid, '1d31faf8-49dc-5f42-96c1-799c87578cf1'::uuid, 'Un greffon provenant d’un autre individu est reconnu comme…', 'mcq', '["Soi","Anticorps","Microbiote","Non-soi"]'::jsonb, 3, 'Ses molécules de surface diffèrent de celles du receveur : il est rejeté sans traitement.', 1),
    ('82524246-9522-5633-b090-2e6ff27dc2ee'::uuid, '1d31faf8-49dc-5f42-96c1-799c87578cf1'::uuid, 'Le lysozyme des larmes agit en…', 'mcq', '["Hydrolysant le peptidoglycane bactérien","Acidifiant l’œil","Produisant des anticorps","Formant du mucus"]'::jsonb, 0, 'Il fragilise la paroi des bactéries, surtout Gram positif.', 2),
    ('337f92f1-1b3c-5cd2-b324-38a307dce86f'::uuid, '1d31faf8-49dc-5f42-96c1-799c87578cf1'::uuid, 'Les cellules sentinelles reconnaissent les bactéries grâce à…', 'mcq', '["Des anticorps spécifiques","Des motifs moléculaires communs à de nombreux pathogènes","Leur ADN uniquement","Leur taille"]'::jsonb, 1, 'LPS et peptidoglycane sont reconnus par des récepteurs membranaires de l’immunité innée.', 3),
    ('65625a4e-576e-5ad4-b4e5-d22a96677903'::uuid, '1d31faf8-49dc-5f42-96c1-799c87578cf1'::uuid, 'La diapédèse est…', 'mcq', '["La destruction d’une bactérie","La production de mucus","La traversée de la paroi des vaisseaux par les leucocytes","La libération d’anticorps"]'::jsonb, 2, 'Les phagocytes quittent le sang pour rejoindre le foyer infectieux.', 4),
    ('aef95305-dac4-517d-94e8-c0b9245e6120'::uuid, '1d31faf8-49dc-5f42-96c1-799c87578cf1'::uuid, 'La rougeur de l’inflammation est due à…', 'mcq', '["Le chimiotactisme","La phagocytose","L’exocytose","La vasodilatation"]'::jsonb, 3, 'L’afflux de sang dans les vaisseaux dilatés colore et réchauffe la zone.', 5),
    ('e35dbecb-1034-5e6a-8bf6-4200468f441a'::uuid, '1d31faf8-49dc-5f42-96c1-799c87578cf1'::uuid, 'Dans quel ordre se déroule la phagocytose ?', 'mcq', '["Adhésion, endocytose, digestion","Digestion, adhésion, endocytose","Endocytose, adhésion, digestion","Exocytose, adhésion, digestion"]'::jsonb, 0, 'Le phagocyte s’attache, englobe, puis digère grâce aux lysosomes.', 6),
    ('cd7ce7ad-23e1-5167-8280-6c5a6605ecce'::uuid, '1d31faf8-49dc-5f42-96c1-799c87578cf1'::uuid, 'Le chimiotactisme désigne…', 'mcq', '["La sécrétion d’anticorps","L’attraction des phagocytes par des signaux chimiques","La réplication virale","L’acidité gastrique"]'::jsonb, 1, 'Les phagocytes remontent le gradient de molécules signal jusqu’au foyer.', 7),
    ('b0d041b5-9394-5ac8-8f75-fe64d2801578'::uuid, '1d31faf8-49dc-5f42-96c1-799c87578cf1'::uuid, 'Un micro-organisme opportuniste…', 'mcq', '["Est toujours mortel","Ne peut pas se multiplier","Profite d’un affaiblissement des défenses ou d’un déséquilibre du microbiote","Est un anticorps"]'::jsonb, 2, 'Il reste inoffensif tant que l’équilibre est maintenu.', 8),
    ('1942687b-b229-5bc0-a568-9671985b35ea'::uuid, '1d31faf8-49dc-5f42-96c1-799c87578cf1'::uuid, 'L’immunité innée garde la mémoire des infections passées.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La mémoire est une propriété de l’immunité adaptative (lymphocytes mémoire).', 9),
    ('82df9fee-8bb1-5016-bab7-5df83c82609c'::uuid, '1d31faf8-49dc-5f42-96c1-799c87578cf1'::uuid, 'L’œdème inflammatoire provient de…', 'mcq', '["La fermentation","La multiplication des lymphocytes","La destruction des globules rouges","L’exsudation du plasma hors des vaisseaux"]'::jsonb, 3, 'Le liquide qui sort des vaisseaux gonfle les tissus.', 10),
    ('8c703f26-e1cf-52e9-a84a-68093359ecd9'::uuid, '1d31faf8-49dc-5f42-96c1-799c87578cf1'::uuid, 'Quelle molécule caractérise la membrane externe des bactéries Gram négatif ?', 'mcq', '["Le LPS","Le lysozyme","L’ATP","L’hémoglobine"]'::jsonb, 0, 'Le lipopolysaccharide est un motif reconnu par les cellules sentinelles.', 11),
    ('ce04b67e-92f9-5f9a-91f5-43867a3cb48e'::uuid, '1d31faf8-49dc-5f42-96c1-799c87578cf1'::uuid, 'Le microbiote protège l’organisme notamment en…', 'mcq', '["Détruisant les globules blancs","Occupant la place et les nutriments","Produisant des anticorps humains","Augmentant la température"]'::jsonb, 1, 'C’est un effet de barrière : un pathogène trouve la place déjà prise.', 12),
    ('d2e345e5-f290-5ab2-8b44-dd3883d8cf79'::uuid, 'db8ca6e9-3c94-5fca-a886-89d6f48fc6ae'::uuid, 'Quel lymphocyte porte le marqueur CD8 ?', 'mcq', '["Le lymphocyte B","Le lymphocyte T4","Le lymphocyte T8","Le plasmocyte"]'::jsonb, 2, 'Le T8 devient lymphocyte T cytotoxique.', 1),
    ('0c67ce42-7b23-5fa5-868c-d1c84bfc6890'::uuid, 'db8ca6e9-3c94-5fca-a886-89d6f48fc6ae'::uuid, 'Un lymphocyte T reconnaît un antigène…', 'mcq', '["Libre dans le plasma","Grâce à des anticorps solubles","Uniquement s’il est lipidique","Présenté sous forme de peptide par le CMH"]'::jsonb, 3, 'Le TCR reconnaît le couple peptide antigénique + CMH à la surface d’une cellule.', 2),
    ('4c527615-ff07-55e6-8339-19b210b6929e'::uuid, 'db8ca6e9-3c94-5fca-a886-89d6f48fc6ae'::uuid, 'Le rôle principal du lymphocyte T auxiliaire est de…', 'mcq', '["Stimuler par des messagers l’activation des B et des T8","Tuer les cellules infectées","Sécréter des anticorps","Phagocyter les bactéries"]'::jsonb, 0, 'C’est le chef d’orchestre de la coopération cellulaire.', 3),
    ('c6bbd575-5d6a-58d0-821b-fd9c9a9b8774'::uuid, 'db8ca6e9-3c94-5fca-a886-89d6f48fc6ae'::uuid, 'Le plasmocyte est riche en réticulum endoplasmique granuleux car…', 'mcq', '["Il stocke du glycogène","Il synthétise et sécrète des protéines en grande quantité","Il fait la photosynthèse","Il se divise sans cesse"]'::jsonb, 1, 'Les anticorps sont des protéines sécrétées, produites par le REG.', 4),
    ('f54a4677-5e32-5fae-83a5-1a1f402e4e7e'::uuid, 'db8ca6e9-3c94-5fca-a886-89d6f48fc6ae'::uuid, 'La partie de l’anticorps qui se lie à l’antigène est…', 'mcq', '["L’épitope","Le CMH","Le paratope","Le TCR"]'::jsonb, 2, 'Le paratope de l’anticorps se lie à l’épitope de l’antigène.', 5),
    ('606aeb35-78b0-5e41-b3da-fa1ec2f99db2'::uuid, 'db8ca6e9-3c94-5fca-a886-89d6f48fc6ae'::uuid, 'L’opsonisation…', 'mcq', '["Désigne la lyse par perforine","Détruit directement la bactérie par l’anticorps","Empêche la présentation antigénique","Facilite la phagocytose d’une bactérie couverte d’anticorps"]'::jsonb, 3, 'Les phagocytes ont des récepteurs pour les anticorps fixés sur l’antigène.', 6),
    ('df4a7bd0-369e-5cdf-8a5c-14229fb94669'::uuid, 'db8ca6e9-3c94-5fca-a886-89d6f48fc6ae'::uuid, 'Le système perforine-granzymes est utilisé par…', 'mcq', '["Le lymphocyte T cytotoxique","Le plasmocyte","Le mastocyte","Le globule rouge"]'::jsonb, 0, 'Il permet au T cytotoxique de tuer une cellule infectée.', 7),
    ('97c7d002-1c28-5240-9daf-caeb79dc29d9'::uuid, 'db8ca6e9-3c94-5fca-a886-89d6f48fc6ae'::uuid, 'Des IgM spécifiques élevées au sérodiagnostic indiquent plutôt…', 'mcq', '["Une infection ancienne","Une infection récente","Une vaccination d’il y a dix ans","Une absence de contact"]'::jsonb, 1, 'Les IgM dominent au début de la réponse primaire.', 8),
    ('29376502-96a2-5e9a-abd6-97fff8e976e0'::uuid, 'db8ca6e9-3c94-5fca-a886-89d6f48fc6ae'::uuid, 'La réponse secondaire est plus rapide grâce…', 'mcq', '["À l’inflammation","Au lysozyme","Aux lymphocytes mémoire","Au microbiote"]'::jsonb, 2, 'Ils sont plus nombreux et se réactivent plus vite que les lymphocytes naïfs.', 9),
    ('92109f45-b7d1-5728-93d1-04cbe63857e6'::uuid, 'db8ca6e9-3c94-5fca-a886-89d6f48fc6ae'::uuid, 'Un anticorps détruit lui-même la bactérie qu’il reconnaît.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il neutralise ou marque ; la destruction revient aux phagocytes et à d’autres effecteurs.', 10),
    ('ac92e049-83f6-57cc-b5ff-7efcfd30bd95'::uuid, 'db8ca6e9-3c94-5fca-a886-89d6f48fc6ae'::uuid, 'L’activation monoclonale signifie que…', 'mcq', '["Tous les lymphocytes se multiplient","Les anticorps se clonent","L’antigène se multiplie","Seul le lymphocyte qui reconnaît l’antigène se multiplie en un clone"]'::jsonb, 3, 'Sélection et expansion clonale : un clone de cellules identiques, spécifiques du même antigène.', 11),
    ('e0738c62-493f-530f-a9aa-797361fcdbee'::uuid, 'db8ca6e9-3c94-5fca-a886-89d6f48fc6ae'::uuid, 'La neutralisation d’une toxine par un anticorps consiste à…', 'mcq', '["L’empêcher de se fixer sur sa cible","La transformer en ATP","La faire phagocyter par un plasmocyte","L’intégrer au CMH"]'::jsonb, 0, 'L’anticorps couvre la toxine, qui ne peut plus se lier à ses récepteurs.', 12),
    ('259e2d4d-01d0-5f28-a81f-d815ce5d4b39'::uuid, '5d0d2edc-ff02-53bf-be05-4044ad862f72'::uuid, 'Une anatoxine est…', 'mcq', '["Un anticorps de cheval","Une toxine rendue inoffensive mais encore immunogène","Un antibiotique","Un virus vivant atténué"]'::jsonb, 1, 'Elle déclenche une réponse contre la toxine sans provoquer la maladie (tétanos, diphtérie).', 1),
    ('5d8e2eaf-1422-5a49-b7a9-946680129fdc'::uuid, '5d0d2edc-ff02-53bf-be05-4044ad862f72'::uuid, 'Le rôle d’un adjuvant est de…', 'mcq', '["Tuer le pathogène","Remplacer l’antigène","Renforcer la réponse immunitaire au vaccin","Conserver le vaccin au froid"]'::jsonb, 2, 'Il stimule l’immunité innée et rend l’antigène plus immunogène.', 2),
    ('94255e28-8ac2-5964-8133-a471f1c9b7b2'::uuid, '5d0d2edc-ff02-53bf-be05-4044ad862f72'::uuid, 'La sérothérapie apporte une immunité…', 'mcq', '["Active et durable","Innée et définitive","Active et immédiate","Passive et immédiate"]'::jsonb, 3, 'On injecte des anticorps tout faits : efficaces aussitôt, éliminés en quelques semaines.', 3),
    ('9131c550-d1db-55df-b0c1-15394ee37cb8'::uuid, '5d0d2edc-ff02-53bf-be05-4044ad862f72'::uuid, 'Pourquoi fait-on des rappels de vaccin ?', 'mcq', '["Pour relancer une réponse secondaire et entretenir la mémoire","Pour détruire les lymphocytes mémoire","Pour remplacer l’immunité innée","Pour produire des IgM seulement"]'::jsonb, 0, 'Chaque rappel déclenche une réponse secondaire plus forte et plus durable.', 4),
    ('5a99edf2-c0a0-53d6-a33d-97e704b01c44'::uuid, '5d0d2edc-ff02-53bf-be05-4044ad862f72'::uuid, 'Dans quelle situation la sérothérapie est-elle préférée ?', 'mcq', '["Prévention à long terme d’un nourrisson","Exposition récente nécessitant une protection immédiate","Voyage prévu dans un an","Protection collective d’une population"]'::jsonb, 1, 'Seule la sérothérapie agit tout de suite.', 5),
    ('633e07f4-b36f-5549-bd23-d0daadea0ebf'::uuid, '5d0d2edc-ff02-53bf-be05-4044ad862f72'::uuid, 'La protection collective permet de protéger…', 'mcq', '["Uniquement les personnes vaccinées","Seulement les adultes","Aussi les personnes qui ne peuvent pas être vaccinées","Personne"]'::jsonb, 2, 'Le pathogène circule mal dans une population largement immunisée.', 6),
    ('7e3304d3-ea58-5c28-baca-73f25ab2b512'::uuid, '5d0d2edc-ff02-53bf-be05-4044ad862f72'::uuid, 'Le vaccin contre la rougeole est de type…', 'mcq', '["Anatoxine","Antibiotique","Sérum","Vivant atténué"]'::jsonb, 3, 'Il contient le virus vivant rendu peu pathogène.', 7),
    ('9f51dead-34d7-5c2f-a4c2-b6fcf8be7987'::uuid, '5d0d2edc-ff02-53bf-be05-4044ad862f72'::uuid, 'Un sérum injecté laisse une mémoire immunitaire durable.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Aucun lymphocyte du receveur n’a été activé : aucune mémoire n’est formée.', 8),
    ('f14eb4f6-664b-5f20-b086-a8301789ceba'::uuid, '5d0d2edc-ff02-53bf-be05-4044ad862f72'::uuid, 'La résurgence d’une maladie est souvent liée à…', 'mcq', '["Une baisse de la couverture vaccinale","Trop de vaccins","La disparition du pathogène","Un excès d’adjuvant"]'::jsonb, 0, 'Quand trop de personnes ne sont plus protégées, le pathogène circule de nouveau.', 9),
    ('36fb05d0-7604-5fa2-8c21-c3aeedf0f000'::uuid, '5d0d2edc-ff02-53bf-be05-4044ad862f72'::uuid, 'Un vaccin à ARN messager apporte…', 'mcq', '["L’antigène lui-même, purifié","L’information qui fait produire l’antigène par nos cellules","Des anticorps","Un virus entier tué"]'::jsonb, 1, 'Nos cellules traduisent l’ARNm en protéine antigénique, présentée ensuite au système immunitaire.', 10),
    ('ddfb1e63-f32b-5259-9ec5-4534bb7e7619'::uuid, '5d0d2edc-ff02-53bf-be05-4044ad862f72'::uuid, 'L’immunogénicité d’un antigène désigne…', 'mcq', '["Sa toxicité","Sa masse","Sa capacité à déclencher une réponse immunitaire","Sa solubilité"]'::jsonb, 2, 'Un antigène peu immunogène a besoin d’un adjuvant ou de rappels.', 11),
    ('8f43e3ce-bcc8-5ccf-97f6-da0f2716e29f'::uuid, '5d0d2edc-ff02-53bf-be05-4044ad862f72'::uuid, 'Un blessé non vacciné contre le tétanos reçoit…', 'mcq', '["Des immunoglobulines seules","Un vaccin seul","Un antibiotique seul","Des immunoglobulines et une première dose de vaccin"]'::jsonb, 3, 'Protection immédiate par les anticorps, protection durable par le vaccin.', 12),
    ('05374d1f-9a6c-5a98-b6dc-827a1b676769'::uuid, 'a9c76b73-51ea-54e5-9ee9-730eaa933837'::uuid, 'À quelle longueur d’onde l’ADN absorbe-t-il le plus ?', 'mcq', '["260 nm","280 nm","540 nm","620 nm"]'::jsonb, 0, 'Les bases azotées absorbent au maximum vers 260 nm ; 280 nm est plutôt le pic des protéines.', 1),
    ('7326ede0-e169-5711-8906-635ffff8d6ef'::uuid, 'a9c76b73-51ea-54e5-9ee9-730eaa933837'::uuid, 'La dénaturation de l’ADN rompt…', 'mcq', '["Les liaisons phosphodiester","Les liaisons hydrogène entre bases","Les liaisons peptidiques","Les bases elles-mêmes"]'::jsonb, 1, 'Les deux brins se séparent, mais chaque brin reste intact.', 2),
    ('2194803e-3683-5770-a86a-662c66538284'::uuid, 'a9c76b73-51ea-54e5-9ee9-730eaa933837'::uuid, 'L’effet hyperchrome désigne…', 'mcq', '["La baisse d’absorbance à la dénaturation","La coloration de l’ADN","L’augmentation d’absorbance à 260 nm quand l’ADN passe en simple brin","La condensation en chromosome"]'::jsonb, 2, 'Les bases exposées absorbent davantage.', 3),
    ('7d6de851-15f2-51db-8232-308a1e2a63cc'::uuid, 'a9c76b73-51ea-54e5-9ee9-730eaa933837'::uuid, 'Quel ADN a la température de fusion la plus élevée ?', 'mcq', '["30 % de C+G","45 % de C+G","50 % de C+G","65 % de C+G"]'::jsonb, 3, 'Les paires C≡G, à trois liaisons hydrogène, stabilisent la double hélice.', 4),
    ('a1f3adba-ad60-5bda-9c15-dcdb8d7d395e'::uuid, 'a9c76b73-51ea-54e5-9ee9-730eaa933837'::uuid, 'Pourquoi l’ADN migre-t-il vers l’anode en électrophorèse ?', 'mcq', '["Ses phosphates le chargent négativement","Il est chargé positivement","Il est neutre","Il est hydrophobe"]'::jsonb, 0, 'L’ADN est un polyanion : il est attiré par le pôle positif.', 5),
    ('e26e1018-e96c-5871-b2f4-31f91ea20c8e'::uuid, 'a9c76b73-51ea-54e5-9ee9-730eaa933837'::uuid, 'La réplication est dite semi-conservative car…', 'mcq', '["Seule la moitié du génome est copiée","Chaque molécule fille garde un brin parental","Un brin sur deux est détruit","Elle ne se produit qu’une fois sur deux"]'::jsonb, 1, 'Chaque double hélice fille associe un brin ancien et un brin neuf.', 6),
    ('f69eeed8-6555-5197-90e4-8a4c38360a2b'::uuid, 'a9c76b73-51ea-54e5-9ee9-730eaa933837'::uuid, 'L’ADN polymérase allonge un brin…', 'mcq', '["Dans le sens 3’→5’","Dans les deux sens","Dans le sens 5’→3’","Sans amorce"]'::jsonb, 2, 'Elle ajoute les nucléotides à l’extrémité 3’ du brin en cours.', 7),
    ('de707df1-2701-51a7-8236-4e64b2f88820'::uuid, 'a9c76b73-51ea-54e5-9ee9-730eaa933837'::uuid, 'L’euchromatine correspond à de l’ADN…', 'mcq', '["Très condensé et silencieux","Dégradé","Mitochondrial","Peu condensé, dont les gènes sont accessibles"]'::jsonb, 3, 'Les gènes de l’euchromatine peuvent être transcrits.', 8),
    ('3509d90e-b2ab-5f6e-b052-328f2fa331b2'::uuid, 'a9c76b73-51ea-54e5-9ee9-730eaa933837'::uuid, 'Une cellule en G2 contient, par rapport à G1…', 'mcq', '["Deux fois plus d’ADN","Autant d’ADN","Deux fois moins d’ADN","Pas d’ADN"]'::jsonb, 0, 'L’ADN a été répliqué pendant la phase S.', 9),
    ('40d2a3ed-9981-5edb-a157-4bdb0303ab33'::uuid, 'a9c76b73-51ea-54e5-9ee9-730eaa933837'::uuid, 'La perte de l’inhibition de contact est caractéristique…', 'mcq', '["Des cellules souches","Des cellules cancéreuses","Des globules rouges","Des neurones"]'::jsonb, 1, 'Les cellules cancéreuses continuent à proliférer en s’empilant.', 10),
    ('7f4dd41b-0ff7-5f30-8220-8856ad887458'::uuid, 'a9c76b73-51ea-54e5-9ee9-730eaa933837'::uuid, 'Une cellule musculaire a perdu les gènes qu’elle n’exprime pas.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle garde tout le génome ; les gènes inutiles sont réprimés.', 11),
    ('464e9d95-f625-563f-92ea-9373a17f8241'::uuid, 'a9c76b73-51ea-54e5-9ee9-730eaa933837'::uuid, 'Une cellule souche pluripotente peut…', 'mcq', '["Seulement se diviser sans se différencier","Donner un seul type cellulaire","Donner presque tous les types cellulaires","Produire des anticorps"]'::jsonb, 2, 'C’est ce qui en fait un outil de la thérapie cellulaire et génique.', 12),
    ('418d78ce-e106-5bce-ae68-92e6de40682e'::uuid, '234f5595-ed7d-54bc-a2f2-0cc76eba9026'::uuid, 'Quelle structure est propre aux bactéries Gram négatif ?', 'mcq', '["Une épaisse couche de peptidoglycane","Des chloroplastes","Un noyau","Une membrane externe avec du LPS"]'::jsonb, 3, 'La membrane externe et son LPS caractérisent les Gram négatif.', 1),
    ('d2612c20-0fbd-52cb-9ff3-4b76cf9fd225'::uuid, '234f5595-ed7d-54bc-a2f2-0cc76eba9026'::uuid, 'Un plasmide est…', 'mcq', '["Une petite molécule d’ADN extrachromosomique","Un organite de levure","Une protéine de capside","Un type de spore"]'::jsonb, 0, 'Il porte souvent des gènes de résistance et sert de vecteur de clonage.', 2),
    ('4772b2eb-df85-51e5-ba88-0326e53347a6'::uuid, '234f5595-ed7d-54bc-a2f2-0cc76eba9026'::uuid, 'Les levures se multiplient le plus souvent par…', 'mcq', '["Méiose","Bourgeonnement","Scissiparité exclusivement","Libération de virions"]'::jsonb, 1, 'Un bourgeon se forme, grossit puis se détache de la cellule mère.', 3),
    ('db5b3392-24ef-521e-a6d0-8f23311485e1'::uuid, '234f5595-ed7d-54bc-a2f2-0cc76eba9026'::uuid, 'Les spores d’une moisissure servent à…', 'mcq', '["La photosynthèse","La fixation du CO₂","La propagation du champignon","La digestion"]'::jsonb, 2, 'Libérées par l’appareil sporifère, elles colonisent de nouveaux milieux.', 4),
    ('4af7fd5d-9316-515d-847f-0752f3c2f3aa'::uuid, '234f5595-ed7d-54bc-a2f2-0cc76eba9026'::uuid, 'La métagénomique permet…', 'mcq', '["De cultiver toutes les bactéries","De dénombrer les levures au microscope","De tuer les virus","D’identifier les espèces d’un échantillon par leur ADN, même non cultivables"]'::jsonb, 3, 'On séquence tout l’ADN présent, sans passer par la culture.', 5),
    ('93c07d8b-184c-5564-aeb8-84c60f00996a'::uuid, '234f5595-ed7d-54bc-a2f2-0cc76eba9026'::uuid, 'La présence d’E. coli dans une eau signale…', 'mcq', '["Une contamination fécale","Une eau parfaitement pure","Un excès de chlore","Une pollution par les métaux"]'::jsonb, 0, 'E. coli est une flore indicatrice de contamination fécale.', 6),
    ('e8dac371-e2cb-55c7-9337-fc0b92947858'::uuid, '234f5595-ed7d-54bc-a2f2-0cc76eba9026'::uuid, 'Un virus est un parasite obligatoire car…', 'mcq', '["Il se nourrit de sucre","Il ne peut se multiplier qu’à l’intérieur d’une cellule","Il possède une paroi","Il respire"]'::jsonb, 1, 'Il n’a ni ribosomes ni métabolisme : il détourne ceux de la cellule.', 7),
    ('cf2e5c80-5350-510f-8a23-4b39d0b57b71'::uuid, '234f5595-ed7d-54bc-a2f2-0cc76eba9026'::uuid, 'Dans le cycle lysogène, le génome du phage…', 'mcq', '["Détruit aussitôt la bactérie","Est dégradé","S’intègre au chromosome bactérien et reste latent","Se transforme en plasmide de résistance"]'::jsonb, 2, 'Le phage tempéré peut rester silencieux avant de passer au cycle lytique.', 8),
    ('a8a48f89-5cf7-5851-927c-8df9273d5317'::uuid, '234f5595-ed7d-54bc-a2f2-0cc76eba9026'::uuid, 'Le VIH infecte surtout…', 'mcq', '["Les globules rouges","Les cellules de la peau","Les plasmocytes","Les lymphocytes T4"]'::jsonb, 3, 'Il se fixe au récepteur CD4 des lymphocytes T auxiliaires.', 9),
    ('5b4664c0-0d88-5eae-86d6-a2c2216958be'::uuid, '234f5595-ed7d-54bc-a2f2-0cc76eba9026'::uuid, 'Les antirétroviraux…', 'mcq', '["Bloquent des enzymes du virus et contrôlent sa multiplication","Éliminent définitivement le VIH","Sont des antibiotiques","Sont des vaccins"]'::jsonb, 0, 'Ils visent la transcriptase inverse, l’intégrase ou la protéase.', 10),
    ('d9aae473-ef48-58e0-bcf8-dcfc60ccaca4'::uuid, '234f5595-ed7d-54bc-a2f2-0cc76eba9026'::uuid, 'Un antibiotique guérit une grippe.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La grippe est virale : l’antibiotique n’a pas de cible chez le virus.', 11),
    ('f0c2ec46-050d-5691-bf26-a490e790012c'::uuid, '234f5595-ed7d-54bc-a2f2-0cc76eba9026'::uuid, 'Une dysbiose est…', 'mcq', '["Une infection virale","Un déséquilibre du microbiote","Une coloration","Une méthode de dénombrement"]'::jsonb, 1, 'Elle est associée à plusieurs pathologies et favorise les opportunistes.', 12),
    ('5ff45d36-b815-5ff7-bba4-061d316fd560'::uuid, '6fd961ba-2abe-51ac-a6c7-e0b45bd10800'::uuid, 'Pendant quelle phase la vitesse de croissance est-elle maximale et constante ?', 'mcq', '["Latence","Stationnaire","Exponentielle","Déclin"]'::jsonb, 2, 'Les bactéries se divisent à rythme constant : ln N est une droite de pente maximale.', 1),
    ('e8e935e8-60ee-5f52-8c06-3f3651eb38c9'::uuid, '6fd961ba-2abe-51ac-a6c7-e0b45bd10800'::uuid, 'La phase de latence correspond à…', 'mcq', '["La mort des bactéries","La sporulation","L’épuisement du milieu","L’adaptation au milieu, sans division"]'::jsonb, 3, 'Les cellules synthétisent les enzymes adaptées avant de se diviser.', 2),
    ('e48b0a32-bb22-5075-afa7-f5626ff35bf6'::uuid, '6fd961ba-2abe-51ac-a6c7-e0b45bd10800'::uuid, 'En phase stationnaire…', 'mcq', '["Les divisions compensent les morts","Il n’y a plus aucune division","La population double sans cesse","Le milieu est renouvelé"]'::jsonb, 0, 'La population ne varie plus : autant de nouvelles cellules que de cellules mortes.', 3),
    ('deb35fdd-6995-5e51-9b02-78f26cc63fc7'::uuid, '6fd961ba-2abe-51ac-a6c7-e0b45bd10800'::uuid, 'Une population passe de 10⁴ à 8 × 10⁴ en 60 min. Temps de génération ?', 'mcq', '["60 min","20 min","30 min","8 min"]'::jsonb, 1, 'Facteur 8 = 2³ : trois générations en 60 min, soit 20 min chacune.', 4),
    ('aa9ec78b-1d34-58da-ab33-983ccec84fb1'::uuid, '6fd961ba-2abe-51ac-a6c7-e0b45bd10800'::uuid, 'Le taux de croissance µ vaut…', 'mcq', '["G × ln 2","G / ln 2","ln 2 / G","2 / G"]'::jsonb, 2, 'µ = ln 2 / G : plus le temps de génération est court, plus µ est grand.', 5),
    ('0c0957dc-dfa7-5f86-8ad4-82a7b5f056f6'::uuid, '6fd961ba-2abe-51ac-a6c7-e0b45bd10800'::uuid, 'Un antiseptique s’applique…', 'mcq', '["Dans un bioréacteur","Sur une paillasse","Uniquement par voie orale","Sur un tissu vivant"]'::jsonb, 3, 'Le désinfectant, lui, s’utilise sur les surfaces inertes.', 6),
    ('f9f7070a-ad46-5827-bcd1-cd7d4f39c1b0'::uuid, '6fd961ba-2abe-51ac-a6c7-e0b45bd10800'::uuid, 'Un agent bactériostatique…', 'mcq', '["Bloque la croissance sans forcément tuer","Tue toutes les bactéries","Détruit les virus","Stérilise le matériel"]'::jsonb, 0, 'Si on le retire, les bactéries peuvent reprendre leur croissance.', 7),
    ('ec3e9569-f956-5e02-8609-f6a8e1fe7972'::uuid, '6fd961ba-2abe-51ac-a6c7-e0b45bd10800'::uuid, 'Sur un antibiogramme, une grande zone d’inhibition indique plutôt une souche…', 'mcq', '["Résistante","Sensible","Contaminée","Morte avant l’essai"]'::jsonb, 1, 'L’antibiotique a empêché la croissance loin autour du disque.', 8),
    ('a841f230-5a6b-58e7-8f13-494e36da8515'::uuid, '6fd961ba-2abe-51ac-a6c7-e0b45bd10800'::uuid, 'La CMI est…', 'mcq', '["La concentration maximale tolérée","Le diamètre du disque","La plus petite concentration qui empêche toute croissance visible","Le temps de génération"]'::jsonb, 2, 'Plus la CMI est faible, plus l’antibiotique est actif sur la souche.', 9),
    ('b5feab99-5468-5e8d-bca5-72e4f5765911'::uuid, '6fd961ba-2abe-51ac-a6c7-e0b45bd10800'::uuid, 'Un milieu sélectif sert à…', 'mcq', '["Faire pousser toutes les espèces","Stériliser le produit","Dénombrer les virus","Inhiber la croissance des espèces non recherchées"]'::jsonb, 3, 'Il favorise l’isolement de l’espèce d’intérêt.', 10),
    ('39ad1d4f-44b4-5d0c-a4a3-7a044d1d0e1f'::uuid, '6fd961ba-2abe-51ac-a6c7-e0b45bd10800'::uuid, 'Une résistance portée par un plasmide reçu d’une autre bactérie est une résistance naturelle.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est une résistance acquise ; la résistance naturelle concerne toute l’espèce.', 11),
    ('0b7f1a00-7a5e-5aa0-bd91-ddf48d748f8d'::uuid, '6fd961ba-2abe-51ac-a6c7-e0b45bd10800'::uuid, 'Dans un bioréacteur, on régule notamment…', 'mcq', '["La température, le pH et l’oxygène dissous","Seulement la couleur","La pression atmosphérique extérieure","Le nombre de spores à la main"]'::jsonb, 0, 'Ces paramètres conditionnent la croissance et la production.', 12),
    ('b3472e4c-1f33-52dc-9be5-52094be28084'::uuid, '04408452-c28a-5f95-859c-ad0661d541ea'::uuid, 'Avant toute identification, il faut s’assurer…', 'mcq', '["Que le milieu est sélectif","Que la souche est pure","Que la bactérie est morte","Que la galerie est périmée"]'::jsonb, 1, 'Un mélange donnerait un profil incohérent.', 1),
    ('5f6f8c50-3c16-546a-8c29-c0d14409b64c'::uuid, '04408452-c28a-5f95-859c-ad0661d541ea'::uuid, 'La mobilité s’observe…', 'mcq', '["Après coloration de Gram","Sur un auxanogramme","À l’état frais","Par le test catalase"]'::jsonb, 2, 'Seules des cellules vivantes, non fixées, peuvent montrer leur mobilité.', 2),
    ('9f211c16-6d8b-5039-b8ef-bf2b9ec3bcff'::uuid, '04408452-c28a-5f95-859c-ad0661d541ea'::uuid, 'Une bactérie qui ne pousse qu’en surface d’une gélose profonde est…', 'mcq', '["Anaérobie stricte","Microaérophile","Aéro-anaérobie facultative","Aérobie stricte"]'::jsonb, 3, 'Elle a besoin de dioxygène, disponible seulement en haut du tube.', 3),
    ('878f2c1a-b003-5855-bdea-d4e81d6c4cb2'::uuid, '04408452-c28a-5f95-859c-ad0661d541ea'::uuid, 'Des bulles au contact de l’eau oxygénée révèlent…', 'mcq', '["Une catalase","Une oxydase","Une amylase","Une nitrate réductase"]'::jsonb, 0, 'La catalase décompose H₂O₂ en eau et dioxygène.', 4),
    ('4a569bc4-fba1-50e9-81fb-a06a99ebea1c'::uuid, '04408452-c28a-5f95-859c-ad0661d541ea'::uuid, 'Un halo clair autour des colonies sur gélose à l’amidon révélée au lugol indique…', 'mcq', '["Une résistance aux antibiotiques","Une amylase sécrétée","Une fermentation lactique","Une contamination"]'::jsonb, 1, 'L’amidon hydrolysé ne se colore plus en bleu-noir avec le lugol.', 5),
    ('b21d30e3-fb74-5dda-9bce-4a192f179512'::uuid, '04408452-c28a-5f95-859c-ad0661d541ea'::uuid, 'L’auxanogramme étudie…', 'mcq', '["La mobilité","La forme des colonies","L’utilisation de différentes sources de carbone","La réaction de Gram"]'::jsonb, 2, 'On observe la croissance sur milieu synthétique avec une seule source de carbone.', 6),
    ('76a0b314-5bc5-5ca5-95ed-ee5b9412a7cc'::uuid, '04408452-c28a-5f95-859c-ad0661d541ea'::uuid, 'La méthode probabiliste s’appuie sur…', 'mcq', '["Une clé à deux branches","Un seul test","L’observation seule au microscope","La comparaison d’un profil de galerie à une base de données"]'::jsonb, 3, 'Elle donne une identification avec un pourcentage de probabilité.', 7),
    ('f29536e9-09c1-5453-8234-3c39968738e9'::uuid, '04408452-c28a-5f95-859c-ad0661d541ea'::uuid, 'Dans une galerie miniaturisée, chaque groupe de trois tests positifs est codé par…', 'mcq', '["1, 2 et 4","1, 1 et 1","2, 4 et 8","10, 20 et 30"]'::jsonb, 0, 'La somme des valeurs des tests positifs forme un chiffre du profil.', 8),
    ('b7d2b6bf-b7e9-5e9f-866e-5186f618ad44'::uuid, '04408452-c28a-5f95-859c-ad0661d541ea'::uuid, 'Le virage d’un indicateur de pH vers l’acide après culture sur glucose indique…', 'mcq', '["Une alcalinisation","Une production de métabolites acides","L’absence de croissance","Une mobilité"]'::jsonb, 1, 'La dégradation du glucose produit des acides.', 9),
    ('6190c8d2-50f9-5e91-bb95-bb305db5c7ee'::uuid, '04408452-c28a-5f95-859c-ad0661d541ea'::uuid, 'Un test d’identification se lit sans témoin.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les témoins positif et négatif valident les réactifs et la lecture.', 10),
    ('1694e75f-8114-5c02-850c-e8d50770bb39'::uuid, '04408452-c28a-5f95-859c-ad0661d541ea'::uuid, 'La méthode dichotomique sert surtout à…', 'mcq', '["Nommer l’espèce avec certitude","Dénombrer les bactéries","Orienter vers la famille ou le genre","Stériliser"]'::jsonb, 2, 'Chaque question élimine des possibilités ; la galerie précise ensuite l’espèce.', 11),
    ('a56336c5-0b33-52b0-a241-98ba026ddd1d'::uuid, '04408452-c28a-5f95-859c-ad0661d541ea'::uuid, 'Le test oxydase recherche…', 'mcq', '["Un plasmide","Une enzyme de fermentation","Une exo-enzyme","Un cytochrome de la chaîne respiratoire"]'::jsonb, 3, 'Oxydase positive : la bactérie possède la cytochrome c oxydase.', 12),
    ('3147c81b-975f-5330-adf4-e4d6842de4f0'::uuid, '5ec14d0c-8100-5323-a3a2-458e79d85e0c'::uuid, 'L’agglutination suppose un antigène…', 'mcq', '["Particulaire","Soluble","Lipidique uniquement","Absent"]'::jsonb, 0, 'Les anticorps relient des particules (cellules, billes) en agglutinats visibles.', 1),
    ('aa6845bc-ea22-5017-862b-c9a89d1deafc'::uuid, '5ec14d0c-8100-5323-a3a2-458e79d85e0c'::uuid, 'Des globules rouges qui s’agglutinent avec un sérum anti-B appartiennent au groupe…', 'mcq', '["A","B ou AB","O","On ne peut rien dire"]'::jsonb, 1, 'Ils portent l’antigène B : groupe B ou AB, selon le résultat avec l’anti-A.', 2),
    ('4c7d3ed2-6eea-5f3a-9534-77b81ae31be4'::uuid, '5ec14d0c-8100-5323-a3a2-458e79d85e0c'::uuid, 'L’arc de précipitation se forme…', 'mcq', '["Là où l’antigène est en grand excès","Au fond du puits d’ELISA","À la zone d’équivalence entre antigène et anticorps","Seulement sans anticorps"]'::jsonb, 2, 'Le réseau insoluble exige des proportions équilibrées.', 3),
    ('e5ac3139-a361-57cf-907e-2af2865905f9'::uuid, '5ec14d0c-8100-5323-a3a2-458e79d85e0c'::uuid, 'En immunodiffusion radiale, le diamètre de l’anneau permet de…', 'mcq', '["Identifier un groupe sanguin","Compter les bactéries","Mesurer le pH","Doser l’antigène grâce à une courbe d’étalonnage"]'::jsonb, 3, 'Plus l’antigène est concentré, plus l’anneau est grand.', 4),
    ('2c3d89f4-060d-5ba0-ba36-559bdebf0ead'::uuid, '5ec14d0c-8100-5323-a3a2-458e79d85e0c'::uuid, 'Dans un ELISA, le conjugué est…', 'mcq', '["Un anticorps couplé à une enzyme","L’antigène fixé au puits","Le substrat coloré","Le tampon de lavage"]'::jsonb, 0, 'L’enzyme du conjugué transforme le substrat chromogène en produit coloré.', 5),
    ('5c0979b8-bd67-58ad-9853-31aa94413908'::uuid, '5ec14d0c-8100-5323-a3a2-458e79d85e0c'::uuid, 'Pourquoi les lavages sont-ils des points critiques de l’ELISA ?', 'mcq', '["Ils colorent le puits","Ils éliminent les molécules non fixées, qui donneraient un faux positif","Ils ajoutent l’antigène","Ils stérilisent la plaque"]'::jsonb, 1, 'Un conjugué resté libre colore même en l’absence d’antigène.', 6),
    ('60186a19-2e3b-51ef-bbe8-dbeeb219a9ea'::uuid, '5ec14d0c-8100-5323-a3a2-458e79d85e0c'::uuid, 'Le témoin positif sert à vérifier que…', 'mcq', '["Le patient est malade","Il n’y a pas de réaction parasite","Les réactifs fonctionnent","La plaque est propre"]'::jsonb, 2, 'S’il ne réagit pas, le test n’est pas interprétable.', 7),
    ('f5892a9b-2a8c-571d-86a1-adc010e9d60f'::uuid, '5ec14d0c-8100-5323-a3a2-458e79d85e0c'::uuid, 'Pour rechercher les anticorps d’un patient par ELISA, on révèle avec…', 'mcq', '["Un antibiotique","Du lugol","De l’eau oxygénée seule","Un anticorps anti-immunoglobuline humaine conjugué"]'::jsonb, 3, 'Le conjugué reconnaît les anticorps humains fixés sur l’antigène.', 8),
    ('85585f8c-81bf-5821-acf6-af2e27adfa11'::uuid, '5ec14d0c-8100-5323-a3a2-458e79d85e0c'::uuid, 'La double diffusion d’Ouchterlony permet de…', 'mcq', '["Comparer des antigènes selon l’allure des arcs","Dénombrer des levures","Doser le glucose","Amplifier de l’ADN"]'::jsonb, 0, 'Fusion ou croisement des arcs indiquent des antigènes identiques ou différents.', 9),
    ('97c2153e-a8f3-5062-ac9c-ae5fb1849d7f'::uuid, '5ec14d0c-8100-5323-a3a2-458e79d85e0c'::uuid, 'Si le témoin négatif d’un ELISA est coloré, le résultat des patients reste valable.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Une réaction parasite rend le test invalide : il faut le refaire.', 10),
    ('12460525-b487-54b1-91be-464955ae80c9'::uuid, '5ec14d0c-8100-5323-a3a2-458e79d85e0c'::uuid, 'Le substrat chromogène d’un ELISA…', 'mcq', '["Fixe l’antigène","Est transformé en produit coloré par l’enzyme du conjugué","Est un anticorps","Lave la plaque"]'::jsonb, 1, 'L’apparition de couleur révèle la présence du complexe.', 11),
    ('65f815a8-396c-547b-a9ea-72cd600aa340'::uuid, '5ec14d0c-8100-5323-a3a2-458e79d85e0c'::uuid, 'Un sérogroupage de salmonelles repose sur…', 'mcq', '["Une précipitation en gel","Une PCR","Une agglutination par des sérums spécifiques","Un antibiogramme"]'::jsonb, 2, 'Les bactéries agglutinent avec le sérum qui reconnaît leurs antigènes de surface.', 12),
    ('6eb93f4e-9222-5499-9f50-ea659a05c8b1'::uuid, '2ee74ee2-a9b0-5533-973b-43579c995359'::uuid, 'Dans un dosage de substrat en point final, les enzymes sont…', 'mcq', '["Limitantes","Dénaturées","Absentes","En excès"]'::jsonb, 3, 'Tout le substrat doit être transformé : c’est lui la molécule limitante.', 1),
    ('868eb439-e827-592c-b655-dba0b20ae1f3'::uuid, '2ee74ee2-a9b0-5533-973b-43579c995359'::uuid, 'Dans la méthode GOD-POD, la réaction indicatrice est catalysée par…', 'mcq', '["La peroxydase","La glucose oxydase","La catalase","L’amylase"]'::jsonb, 0, 'La peroxydase utilise H₂O₂ pour former le chromophore coloré.', 2),
    ('263768e1-fa0d-54cb-83dd-bd6189289575'::uuid, '2ee74ee2-a9b0-5533-973b-43579c995359'::uuid, 'Un chromogène est…', 'mcq', '["Le produit coloré mesuré","Le réactif incolore transformé en produit coloré","Une enzyme","Un anticorps"]'::jsonb, 1, 'Le chromogène devient chromophore au cours de la réaction indicatrice.', 3),
    ('655e9cf2-85a7-5e1b-816b-8d187e6f9421'::uuid, '2ee74ee2-a9b0-5533-973b-43579c995359'::uuid, 'Pour doser une activité enzymatique, le substrat doit être…', 'mcq', '["Limitant","Absent","En excès (saturant)","Dénaturé"]'::jsonb, 2, 'C’est l’enzyme qu’on mesure : elle seule doit limiter la vitesse.', 4),
    ('fec7483a-2f87-5198-8bcf-cc3c0c4eca99'::uuid, '2ee74ee2-a9b0-5533-973b-43579c995359'::uuid, '1 U correspond à…', 'mcq', '["1 mol·s⁻¹","1 g·L⁻¹","1 mmol·h⁻¹","1 µmol·min⁻¹"]'::jsonb, 3, 'Le katal (mol·s⁻¹) est l’unité du Système international ; 1 U ≈ 16,67 nkat.', 5),
    ('1f14294e-c716-5e57-ade6-7635bc224698'::uuid, '2ee74ee2-a9b0-5533-973b-43579c995359'::uuid, 'La concentration d’activité s’exprime en…', 'mcq', '["U·L⁻¹","mol","nm","min"]'::jsonb, 0, 'C’est une activité rapportée au volume d’échantillon.', 6),
    ('44f6dd92-69af-5f06-a7f3-aa55d6bfd81d'::uuid, '2ee74ee2-a9b0-5533-973b-43579c995359'::uuid, 'La méthode « deux points » n’est valable que si…', 'mcq', '["La réaction est terminée","Les deux mesures sont dans la période initiale","Le substrat est limitant","On travaille à 100 °C"]'::jsonb, 1, 'Sinon la vitesse moyenne calculée sous-estime la vitesse initiale.', 7),
    ('a1d6abdb-5f2a-5af5-987b-6358aa298473'::uuid, '2ee74ee2-a9b0-5533-973b-43579c995359'::uuid, 'Étalon à 5,0 mmol·L⁻¹ : A = 0,400. Essai : A = 0,320. Concentration de l’essai ?', 'mcq', '["3,2 mmol·L⁻¹","6,25 mmol·L⁻¹","4,0 mmol·L⁻¹","0,8 mmol·L⁻¹"]'::jsonb, 2, 'c = 5,0 × 0,320 / 0,400 = 4,0 mmol·L⁻¹.', 8),
    ('01223c44-157a-517a-b777-797637101dc8'::uuid, '2ee74ee2-a9b0-5533-973b-43579c995359'::uuid, 'Pourquoi thermostate-t-on une mesure d’activité enzymatique ?', 'mcq', '["Pour précipiter l’enzyme","Pour stériliser l’échantillon","Pour colorer le milieu","Parce que l’activité dépend de la température"]'::jsonb, 3, 'Un écart de quelques degrés modifie nettement la vitesse.', 9),
    ('757844a1-440b-520f-80e3-3c9ecf334141'::uuid, '2ee74ee2-a9b0-5533-973b-43579c995359'::uuid, 'Si on mesure la pente après la période initiale, l’activité est surestimée.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La vitesse diminue avec le temps : l’activité serait sous-estimée.', 10),
    ('d6d7d868-8a9d-5b35-b4a1-38a846c1f255'::uuid, '2ee74ee2-a9b0-5533-973b-43579c995359'::uuid, 'Dans une méthode à réactions couplées, la réaction principale…', 'mcq', '["Transforme le substrat à doser","Produit directement le chromophore","Sert de témoin","Dilue l’échantillon"]'::jsonb, 0, 'Les réactions auxiliaire et indicatrice suivent pour aboutir à la molécule mesurée.', 11),
    ('342f9baa-db8e-5244-aabc-01bc4a498193'::uuid, '2ee74ee2-a9b0-5533-973b-43579c995359'::uuid, 'Un blanc réactif sert à…', 'mcq', '["Augmenter la couleur","Régler le zéro d’absorbance sans substrat à doser","Remplacer l’étalon","Détruire les enzymes"]'::jsonb, 1, 'Il corrige l’absorbance propre des réactifs.', 12),
    ('2b3fe48d-173f-5ec1-8410-767b2c46dd28'::uuid, 'bc958157-5100-5f90-bb70-31df82222565'::uuid, 'Après centrifugation, les éléments les plus denses se trouvent dans…', 'mcq', '["Le surnageant","Le filtrat","Le culot","Le tampon"]'::jsonb, 2, 'Ils sédimentent au fond du tube.', 1),
    ('7ad737b8-7700-53d3-a04f-1aba406c1654'::uuid, 'bc958157-5100-5f90-bb70-31df82222565'::uuid, 'Ce qui est retenu par un filtre s’appelle…', 'mcq', '["Le filtrat","L’éluat","Le surnageant","Le rétentat"]'::jsonb, 3, 'Le filtrat est ce qui traverse le filtre.', 2),
    ('7a638c6f-30d3-5c12-abfa-da956b9c482b'::uuid, 'bc958157-5100-5f90-bb70-31df82222565'::uuid, 'Dans un tampon de pH supérieur à son pHi, une protéine migre…', 'mcq', '["Vers l’anode","Vers la cathode","Ne migre pas","Dans les deux sens"]'::jsonb, 0, 'Au-dessus de son pHi, elle porte une charge globale négative.', 3),
    ('e2786745-4390-5725-be28-03bf43d8dee5'::uuid, 'bc958157-5100-5f90-bb70-31df82222565'::uuid, 'En électrophorèse sur gel d’agarose, les fragments d’ADN se séparent selon…', 'mcq', '["Leur charge seule","Leur taille","Leur couleur","Leur température de fusion"]'::jsonb, 1, 'Tous chargés négativement, ils sont freinés par le gel selon leur taille : les petits vont plus loin.', 4),
    ('1df4a63e-34b3-5dc5-9ece-cfc6191e8348'::uuid, 'bc958157-5100-5f90-bb70-31df82222565'::uuid, 'En chromatographie d’exclusion, sortent en premier…', 'mcq', '["Les petites molécules","Les molécules chargées positivement","Les grosses molécules","Les molécules liées au ligand"]'::jsonb, 2, 'Trop grosses pour entrer dans les pores des billes, elles prennent le chemin le plus court.', 5),
    ('ea7be93f-c276-5ff6-b19b-ecf8c3edea11'::uuid, 'bc958157-5100-5f90-bb70-31df82222565'::uuid, 'La chromatographie d’affinité exploite…', 'mcq', '["La taille","La densité","La couleur","Une liaison spécifique à un ligand fixé"]'::jsonb, 3, 'Seule la molécule qui reconnaît le ligand est retenue.', 6),
    ('62a5c079-29d6-5227-8bcb-a443552854dc'::uuid, 'bc958157-5100-5f90-bb70-31df82222565'::uuid, 'L’activité spécifique se calcule par…', 'mcq', '["Activité totale / masse de protéines","Masse de protéines / volume","Activité / temps","Volume / activité"]'::jsonb, 0, 'Elle mesure la pureté de l’enzyme dans la fraction.', 7),
    ('f9b0ed11-cb2c-5e3f-81bd-2497eeb0e114'::uuid, 'bc958157-5100-5f90-bb70-31df82222565'::uuid, 'Départ : 100 U ; après une étape : 70 U. Rendement ?', 'mcq', '["30 %","70 %","143 %","7 %"]'::jsonb, 1, '70 / 100 × 100 = 70 % de l’activité est conservée.', 8),
    ('4b3561ef-53dd-5452-baef-8ad11e911362'::uuid, 'bc958157-5100-5f90-bb70-31df82222565'::uuid, 'Activité spécifique passant de 2 à 30 U·mg⁻¹. Facteur d’enrichissement ?', 'mcq', '["60","28","15","1,5"]'::jsonb, 2, '30 / 2 = 15 : l’enzyme est 15 fois plus pure.', 9),
    ('dea96f46-f771-5519-bb68-51e2450c6cce'::uuid, 'bc958157-5100-5f90-bb70-31df82222565'::uuid, 'Une chromatographie préparative sert à…', 'mcq', '["Mesurer un pH","Uniquement identifier une molécule","Colorer un gel","Récupérer une molécule en quantité"]'::jsonb, 3, 'L’analytique identifie ou contrôle ; la préparative produit.', 10),
    ('ce7a92c8-9438-5f63-9feb-23466791db48'::uuid, 'bc958157-5100-5f90-bb70-31df82222565'::uuid, 'Une étape de purification réussie diminue toujours l’activité spécifique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle l’augmente, en éliminant des protéines sans activité.', 11),
    ('69afa24b-d303-5f22-ac07-08e292bfdd99'::uuid, 'bc958157-5100-5f90-bb70-31df82222565'::uuid, 'Le marqueur de taille d’une électrophorèse d’ADN sert à…', 'mcq', '["Estimer la taille des fragments par comparaison","Colorer le gel","Tamponner le pH","Couper l’ADN"]'::jsonb, 0, 'On compare les distances de migration à celles de fragments de taille connue.', 12),
    ('da676416-3717-52ee-9fea-e761e873e680'::uuid, '701304b7-4fc7-5ccf-ab9f-fe3f4e6e7771'::uuid, 'Pendant l’extraction, la déprotéinisation sert notamment à…', 'mcq', '["Couper l’ADN","Éliminer les nucléases qui dégraderaient l’ADN","Colorer l’ADN","Amplifier l’ADN"]'::jsonb, 1, 'Protéases et sel éliminent les protéines, dont les nucléases.', 1),
    ('e65c8ceb-51d1-5418-8f65-dce3019ad363'::uuid, '701304b7-4fc7-5ccf-ab9f-fe3f4e6e7771'::uuid, 'Un rapport A260/A280 de 1,4 indique…', 'mcq', '["Un ADN très pur","Un ADN simple brin","Une contamination par des protéines","Un ARN pur"]'::jsonb, 2, 'Un ADN pur donne environ 1,8 ; les protéines absorbent à 280 nm.', 2),
    ('5ff249b2-4ce3-563b-9824-95ea9593393c'::uuid, '701304b7-4fc7-5ccf-ab9f-fe3f4e6e7771'::uuid, 'Pendant l’élongation de la PCR, la température est d’environ…', 'mcq', '["95 °C","4 °C","37 °C","72 °C"]'::jsonb, 3, 'C’est l’optimum de la Taq polymérase, enzyme thermostable.', 3),
    ('cf23661d-ab7d-54be-adb8-4b5b41f93430'::uuid, '701304b7-4fc7-5ccf-ab9f-fe3f4e6e7771'::uuid, 'Combien de copies maximum après 10 cycles à partir d’une molécule ?', 'mcq', '["1 024","100","20","10 000"]'::jsonb, 0, '2¹⁰ = 1 024 : le nombre double à chaque cycle.', 4),
    ('42036a78-ecd2-58dc-a02f-372f5eca3552'::uuid, '701304b7-4fc7-5ccf-ab9f-fe3f4e6e7771'::uuid, 'Qu’est-ce qui détermine la région copiée par la PCR ?', 'mcq', '["La polymérase","Les amorces","Les dNTP","La température d’élongation"]'::jsonb, 1, 'Les amorces s’hybrident de part et d’autre de la séquence cible.', 5),
    ('dc76022a-6d75-5d1c-9894-f0b8303f2a64'::uuid, '701304b7-4fc7-5ccf-ab9f-fe3f4e6e7771'::uuid, 'Le témoin négatif d’une PCR contient…', 'mcq', '["Un produit déjà amplifié","Uniquement de l’ADN","Tous les réactifs sauf l’ADN","Aucun réactif"]'::jsonb, 2, 'Une bande dans ce tube signalerait une contamination.', 6),
    ('ee095c82-cd28-5387-b945-c79416abfd30'::uuid, '701304b7-4fc7-5ccf-ab9f-fe3f4e6e7771'::uuid, 'Un plasmide circulaire coupé en 3 sites donne…', 'mcq', '["2 fragments","6 fragments","4 fragments","3 fragments"]'::jsonb, 3, 'Sur un ADN circulaire, n coupures donnent n fragments.', 7),
    ('b769a4cb-beef-575d-a594-2c605735f535'::uuid, '701304b7-4fc7-5ccf-ab9f-fe3f4e6e7771'::uuid, 'Les bouts collants résultent…', 'mcq', '["D’une coupure décalée sur les deux brins","D’une coupure droite","D’une ligation","D’une PCR"]'::jsonb, 0, 'Ils laissent des extrémités simple brin complémentaires.', 8),
    ('bfccc37b-6d6a-58a9-a2dc-36dd410a395e'::uuid, '701304b7-4fc7-5ccf-ab9f-fe3f4e6e7771'::uuid, 'L’enzyme qui soude le gène dans le vecteur est…', 'mcq', '["Une endonucléase","La ligase","La Taq polymérase","Une protéase"]'::jsonb, 1, 'Elle recrée les liaisons phosphodiester.', 9),
    ('0f22ced8-fdac-5d02-867d-c741c7495189'::uuid, '701304b7-4fc7-5ccf-ab9f-fe3f4e6e7771'::uuid, 'Le gène de résistance à un antibiotique du vecteur sert à…', 'mcq', '["Tuer les bactéries transformées","Couper l’ADN","Sélectionner les bactéries qui ont reçu le plasmide","Colorer les colonies"]'::jsonb, 2, 'Sur un milieu avec l’antibiotique, seules elles survivent.', 10),
    ('3bdf84cc-5199-5100-b720-af5c4d5765f1'::uuid, '701304b7-4fc7-5ccf-ab9f-fe3f4e6e7771'::uuid, 'La transformation bactérienne est…', 'mcq', '["La formation de spores","La mort de la bactérie","La coloration de Gram","L’entrée d’un plasmide dans une bactérie compétente"]'::jsonb, 3, 'La bactérie acquiert ainsi le gène porté par le plasmide.', 11),
    ('bce51de3-dfcf-5a07-8e7a-818c9900d3d6'::uuid, '701304b7-4fc7-5ccf-ab9f-fe3f4e6e7771'::uuid, 'Toute colonie qui pousse sur l’antibiotique porte forcément le plasmide recombinant.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle peut porter un plasmide vide, refermé sans le gène : on le vérifie ensuite.', 12),
    ('95169f31-ba4e-5327-8d32-dd7d955b3d76'::uuid, '5cd2ce1c-6667-5882-92bc-b6b254104673'::uuid, 'Quel est le coefficient de la partie pratique (ECE) de la spécialité ?', 'mcq', '["9","7","16","4"]'::jsonb, 0, 'Écrit coefficient 7, pratique coefficient 9 : 16 au total.', 1),
    ('9f34df9a-7983-59f8-ae9f-2bb95e831b12'::uuid, '5cd2ce1c-6667-5882-92bc-b6b254104673'::uuid, 'Combien de temps dure la partie écrite ?', 'mcq', '["2 h","3 h","4 h","1 h 30"]'::jsonb, 1, 'Trois heures, dont environ 2 h 30 de questionnements et 30 minutes de synthèse.', 2),
    ('7599c9c0-bc7b-5d10-af0c-20ae5eed3b5e'::uuid, '5cd2ce1c-6667-5882-92bc-b6b254104673'::uuid, 'Sur combien de documents s’appuie la première partie de l’écrit ?', 'mcq', '["1 ou 2","15 à 20","6 à 9","Aucun"]'::jsonb, 2, 'Six à neuf documents, d’une demi-page à une page chacun.', 3),
    ('0d5f3dca-d872-5b01-8e46-b7b79b043043'::uuid, '5cd2ce1c-6667-5882-92bc-b6b254104673'::uuid, 'La deuxième partie de l’écrit est…', 'mcq', '["Un oral","Un QCM","Une manipulation","Une question de synthèse d’environ 30 minutes"]'::jsonb, 3, 'Un paragraphe argumenté en lien avec la problématique de la première partie.', 4),
    ('a4fc579e-d02b-524e-b2da-dde63797d126'::uuid, '5cd2ce1c-6667-5882-92bc-b6b254104673'::uuid, 'Combien de points compte la maîtrise de la langue à l’écrit ?', 'mcq', '["2","1","0","5"]'::jsonb, 0, 'Deux points sur vingt : orthographe, syntaxe, vocabulaire précis.', 5),
    ('149003ec-3969-5740-9105-39d9d9093982'::uuid, '5cd2ce1c-6667-5882-92bc-b6b254104673'::uuid, 'Les notions de 1re peuvent être mobilisées dans l’épreuve.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’épreuve porte sur le programme de Tle, mais les notions de 1re restent mobilisables.', 6),
    ('e9ed70e7-3a04-51f2-9cc5-ba81d6a2793c'::uuid, '5cd2ce1c-6667-5882-92bc-b6b254104673'::uuid, 'Combien de sujets d’ECE sont retenus dans la banque nationale pour une session ?', 'mcq', '["4","16","10","50"]'::jsonb, 1, 'Seize sujets, parmi lesquels l’établissement choisit selon son équipement.', 7),
    ('c56e10f5-1ab7-50b0-86ce-b684416cd28b'::uuid, '5cd2ce1c-6667-5882-92bc-b6b254104673'::uuid, 'Pendant l’ECE, ton examinateur…', 'mcq', '["Est toujours ton professeur de l’année","N’observe pas les gestes","Ne peut pas être ton professeur de l’année","Corrige seulement un compte rendu écrit"]'::jsonb, 2, 'C’est une règle de l’épreuve ; il note tes gestes sur une grille d’observation.', 8),
    ('b478a813-3014-5126-bb7a-daded07e3358'::uuid, '5cd2ce1c-6667-5882-92bc-b6b254104673'::uuid, 'Dans une réponse de l’écrit, que faut-il faire après avoir cité un document ?', 'mcq', '["Recopier tout le document","Réciter le chapitre de cours","Passer à la question suivante","En tirer l’information utile et conclure"]'::jsonb, 3, 'Le correcteur attend une exploitation des documents, pas une récitation.', 9),
    ('7d622232-ef96-50bb-8d0a-d6d93cbfc58b'::uuid, '5cd2ce1c-6667-5882-92bc-b6b254104673'::uuid, 'Quelle compétence N’est PAS évaluée à l’ECE ?', 'mcq', '["Réciter une dissertation de philosophie","Réaliser en autonomie","Exprimer un résultat avec sa dimension métrologique","Identifier les dangers et choisir la prévention"]'::jsonb, 0, 'Les cinq autres compétences sont toutes des compétences de laboratoire.', 10),
    ('bbf7cff9-c4e6-561c-9963-401f220cc209'::uuid, '5cd2ce1c-6667-5882-92bc-b6b254104673'::uuid, 'Pendant l’ECE, que vaut-il mieux lancer en premier ?', 'mcq', '["Le rangement","Ce qui demande du temps (incubation, cinétique)","Le calcul final","La synthèse écrite"]'::jsonb, 1, 'Planifier évite de manquer de temps en fin d’épreuve.', 11),
    ('c5eca9c5-4bac-531f-885c-7f5e5eea3dcc'::uuid, '5cd2ce1c-6667-5882-92bc-b6b254104673'::uuid, 'L’oral de contrôle de la spécialité dure…', 'mcq', '["10 minutes sans préparation","1 heure","20 minutes, après 20 minutes de préparation","3 heures"]'::jsonb, 2, 'Il comporte une question scientifique et une question technologique.', 12),
    ('01e2517f-21bd-555a-b835-d87c7ba432f6'::uuid, '8e6e31b4-aee7-5ea1-9d32-e5e15694ea8e'::uuid, 'Les biotechnologies rouges concernent le domaine…', 'mcq', '["De l’environnement","De l’agriculture","De la santé","De la mer"]'::jsonb, 2, 'Médicaments, vaccins, diagnostic : c’est le domaine le plus développé.', 1),
    ('1f70a971-6db4-5e91-9732-299e54aa44f9'::uuid, '8e6e31b4-aee7-5ea1-9d32-e5e15694ea8e'::uuid, 'La production d’enzymes pour les lessives relève des biotechnologies…', 'mcq', '["Blanches","Rouges","Vertes","Bleues"]'::jsonb, 0, 'Les biotechnologies blanches concernent les procédés industriels.', 2),
    ('86a48e76-d665-5aa2-8cdb-154e5d364dfc'::uuid, '8e6e31b4-aee7-5ea1-9d32-e5e15694ea8e'::uuid, 'La dépollution d’un sol par des bactéries relève des biotechnologies…', 'mcq', '["Blanches","Rouges","Bleues","Jaunes"]'::jsonb, 3, 'Le jaune désigne la protection de l’environnement.', 3),
    ('f163c4ca-9f8a-5daa-9cdc-8cfdb0f388cd'::uuid, '8e6e31b4-aee7-5ea1-9d32-e5e15694ea8e'::uuid, 'À quoi sert un témoin dans une expérience ?', 'mcq', '["À gagner du temps","À prouver que le résultat est dû au facteur étudié","À remplacer l’hypothèse","À augmenter le rendement"]'::jsonb, 1, 'Il est réalisé dans les mêmes conditions, sauf pour le facteur testé.', 4),
    ('131acd29-cfda-500d-840b-052391044e6c'::uuid, '8e6e31b4-aee7-5ea1-9d32-e5e15694ea8e'::uuid, 'Un témoin négatif doit…', 'mcq', '["Contenir deux fois plus de réactif","Toujours réagir","Être omis si le résultat est clair","Ne pas réagir"]'::jsonb, 3, 'S’il réagit, le test n’est pas fiable (contamination, réactif défectueux).', 5),
    ('8ec7080a-401b-5afc-b75d-db7698d770ac'::uuid, '8e6e31b4-aee7-5ea1-9d32-e5e15694ea8e'::uuid, 'Une hypothèse scientifique doit être…', 'mcq', '["Une opinion personnelle","Déjà démontrée","Testable par une expérience","Formulée après la conclusion"]'::jsonb, 2, 'On conçoit l’expérience pour la valider ou l’invalider.', 6),
    ('52f71e1a-8fa6-5098-bd89-a35efae01e32'::uuid, '8e6e31b4-aee7-5ea1-9d32-e5e15694ea8e'::uuid, 'Quel outil utiliser pour tracer une courbe d’étalonnage ?', 'mcq', '["Un tableur-grapheur","Un logiciel de visualisation 3D","Un moteur de recherche","Un outil de dessin"]'::jsonb, 0, 'Il trace la courbe et calcule l’équation de la droite de tendance.', 7),
    ('7e96f67f-a09e-55fa-b0a4-0fe937723ed8'::uuid, '8e6e31b4-aee7-5ea1-9d32-e5e15694ea8e'::uuid, 'Une sitographie est…', 'mcq', '["Une technique de culture","La liste des sites internet consultés","Un type de microscope","Un logiciel 3D"]'::jsonb, 1, 'La bibliographie liste les documents imprimés, la sitographie les sites.', 8),
    ('d5414049-05ae-530c-b666-165c8f573443'::uuid, '8e6e31b4-aee7-5ea1-9d32-e5e15694ea8e'::uuid, 'Les molécules extraites d’éponges marines relèvent des biotechnologies bleues.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le bleu désigne l’exploitation de la biodiversité marine.', 9),
    ('92483cba-cc7a-57aa-91c7-38405066db72'::uuid, '8e6e31b4-aee7-5ea1-9d32-e5e15694ea8e'::uuid, 'Quelle est la première étape d’une démarche de projet ?', 'mcq', '["Rédiger la conclusion","Partir d’un besoin et formuler une question","Commander le matériel","Présenter à l’oral"]'::jsonb, 1, 'Tout le projet découle de la question posée.', 10),
    ('90c880ea-95c6-5128-bf11-75475e4a3982'::uuid, '8e6e31b4-aee7-5ea1-9d32-e5e15694ea8e'::uuid, 'Pour juger la fiabilité d’une source, on vérifie d’abord…', 'mcq', '["Sa présence sur un réseau social","Le nombre de couleurs de la page","Sa longueur","Son auteur, sa date et ses références"]'::jsonb, 3, 'Une source fiable est identifiée, datée, référencée et si possible relue par des pairs.', 11),
    ('fded032b-86b8-5914-a9bd-47d11f5a4587'::uuid, '8e6e31b4-aee7-5ea1-9d32-e5e15694ea8e'::uuid, 'Une opinion suffit à justifier une décision bioéthique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Un débat bioéthique s’appuie sur des arguments et des sources, pas sur une simple opinion.', 12),
    ('b3ec76ac-5ae1-531e-8db8-16ec7de27716'::uuid, 'c2b536b8-8945-5228-b747-d3d7587f3851'::uuid, 'Un danger est…', 'mcq', '["Une propriété capable de causer un dommage","La probabilité qu’un accident arrive","Une lésion déjà subie","Une mesure de prévention"]'::jsonb, 0, 'C’est une propriété intrinsèque du produit ou de l’agent, qu’on y soit exposé ou non.', 1),
    ('a401a7f0-7077-5271-a592-e52227b0d09f'::uuid, 'c2b536b8-8945-5228-b747-d3d7587f3851'::uuid, 'Le risque combine…', 'mcq', '["Le danger et le pictogramme","Le prix du produit et sa quantité","La probabilité du dommage et sa gravité","La température et le pH"]'::jsonb, 2, 'Un danger grave mais très improbable peut représenter un risque faible, et inversement.', 2),
    ('c3787462-b94f-5f3d-87cd-eb583a567874'::uuid, 'c2b536b8-8945-5228-b747-d3d7587f3851'::uuid, 'Un flacon de produit corrosif fermé dans une armoire présente un danger mais peu de risque.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Sans situation exposante, le dommage est très improbable.', 3),
    ('59705a65-4646-58c2-8ca3-d49dc4320182'::uuid, 'c2b536b8-8945-5228-b747-d3d7587f3851'::uuid, 'Le pipetage à la bouche expose surtout par…', 'mcq', '["Contact avec l’œil","Inhalation","Ingestion","Voie électrique"]'::jsonb, 2, 'Il est interdit : on utilise toujours une propipette ou une pipette automatique.', 4),
    ('49758b14-cbcb-596e-ac20-2d838d9c45dd'::uuid, 'c2b536b8-8945-5228-b747-d3d7587f3851'::uuid, 'Lors d’un ensemencement, la formation d’aérosols expose surtout par…', 'mcq', '["Inhalation","Ingestion","Contact cutané","Voie sanguine"]'::jsonb, 0, 'De fines gouttelettes contenant des micro-organismes peuvent être respirées.', 5),
    ('f5926f75-a62e-5105-8dfc-14bb33c3960d'::uuid, 'c2b536b8-8945-5228-b747-d3d7587f3851'::uuid, 'Au lycée, on manipule principalement des micro-organismes du groupe de risque…', 'mcq', '["Tous les groupes","3","4","1"]'::jsonb, 3, 'Le groupe 1 réunit les micro-organismes peu susceptibles de provoquer une maladie.', 6),
    ('a1e97427-f7e3-5935-8e0b-a698aaf95123'::uuid, 'c2b536b8-8945-5228-b747-d3d7587f3851'::uuid, 'Quelle mention d’avertissement signale les dangers les plus graves ?', 'mcq', '["Attention","Danger","Prudence","Avertissement"]'::jsonb, 1, 'Le règlement CLP n’emploie que deux mentions : « Danger » et « Attention ».', 7),
    ('1a6e1707-ba05-59c3-a4fc-871a07ea3454'::uuid, 'c2b536b8-8945-5228-b747-d3d7587f3851'::uuid, 'Une situation exposante est…', 'mcq', '["Un pictogramme","Un produit dangereux","Une blessure","Une situation où une personne est en contact avec le danger"]'::jsonb, 3, 'Sans elle, le danger ne peut pas produire de dommage.', 8),
    ('a3868faf-eaf1-5966-95dc-0aa4a8f7a667'::uuid, 'c2b536b8-8945-5228-b747-d3d7587f3851'::uuid, 'Une culture contaminée par le manipulateur illustre…', 'mcq', '["Le risque d’ingestion","Le risque électrique","Le risque pour le produit","Un danger chimique"]'::jsonb, 2, 'L’asepsie protège à la fois l’opérateur et l’échantillon.', 9),
    ('62ec2dfa-c06b-56ff-86dd-4d459f1e5843'::uuid, 'c2b536b8-8945-5228-b747-d3d7587f3851'::uuid, 'Un échantillon de sang humain doit être considéré comme…', 'mcq', '["Potentiellement infectieux","Sans danger s’il vient d’un proche","Un danger chimique seulement","Un déchet ménager"]'::jsonb, 0, 'On ne connaît jamais avec certitude le statut infectieux d’un produit biologique humain.', 10),
    ('19ea6c5b-7915-5b52-ba22-13c7fdd0ffd2'::uuid, 'c2b536b8-8945-5228-b747-d3d7587f3851'::uuid, 'Pour prévenir une contamination, il suffit de rompre un seul maillon de la chaîne de transmission.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Par exemple, les gants coupent la voie d’entrée par contact.', 11),
    ('9a7719f8-5c86-5593-897e-232c6225c978'::uuid, 'c2b536b8-8945-5228-b747-d3d7587f3851'::uuid, 'Quelle est la dernière étape de l’analyse des risques ?', 'mcq', '["Lire la procédure","Relier les mesures de prévention aux risques identifiés","Repérer les pictogrammes","Commander les produits"]'::jsonb, 1, 'Chaque mesure doit répondre à un risque identifié.', 12),
    ('4d9f7ef4-9a95-570e-b54a-2561bc38f7f9'::uuid, '9daec196-fa5a-5330-a178-d9d5bb22b061'::uuid, 'Quel équipement est une protection collective ?', 'mcq', '["Les gants","La hotte chimique","Les lunettes","La blouse"]'::jsonb, 1, 'Elle protège toutes les personnes présentes, pas seulement le manipulateur.', 1),
    ('db0f5efa-73b2-578f-aa78-0df0eaa2ce87'::uuid, '9daec196-fa5a-5330-a178-d9d5bb22b061'::uuid, 'Une blouse de laboratoire doit être…', 'mcq', '["Portée hors du laboratoire","Ouverte pour être plus confortable","En matière synthétique","En coton, fermée, à manches longues"]'::jsonb, 3, 'Le coton brûle moins dangereusement que le synthétique ; fermée, elle protège les vêtements.', 2),
    ('57145b11-91c2-5cc8-9a21-1cd13090905c'::uuid, '9daec196-fa5a-5330-a178-d9d5bb22b061'::uuid, 'Quand faut-il se laver les mains ?', 'mcq', '["Avant et après chaque manipulation","Seulement à la fin de la séance","Uniquement si elles sont sales","Seulement avant de manger"]'::jsonb, 0, 'Avant pour protéger le produit, après pour se protéger et protéger les autres.', 3),
    ('d280d9c3-2be1-5946-971c-74b0d8f319cc'::uuid, '9daec196-fa5a-5330-a178-d9d5bb22b061'::uuid, 'La stérilisation détruit…', 'mcq', '["Uniquement les virus","La majorité des micro-organismes d’une surface","Tous les micro-organismes, spores comprises","Uniquement les bactéries pathogènes"]'::jsonb, 2, 'La désinfection, elle, réduit fortement la charge microbienne sans garantir l’absence totale de germes.', 4),
    ('832bbac5-2dd6-54d6-b083-40bfabb7f469'::uuid, '9daec196-fa5a-5330-a178-d9d5bb22b061'::uuid, 'Pourquoi désinfecter la paillasse avant la manipulation ?', 'mcq', '["Parce que c’est plus rapide","Pour la faire briller","Pour protéger le produit d’une contamination","Pour chauffer la surface"]'::jsonb, 2, 'On la désinfecte aussi après, pour protéger les utilisateurs suivants.', 5),
    ('42c8cfa5-f6ac-5aa9-8e19-c857c20085e3'::uuid, '9daec196-fa5a-5330-a178-d9d5bb22b061'::uuid, 'Une boîte de Petri contenant une culture bactérienne se jette…', 'mcq', '["Dans un conteneur DASRI","À la poubelle ordinaire","À l’évier","Dans le bidon de solvants"]'::jsonb, 0, 'Elle sera autoclavée ou incinérée.', 6),
    ('7eaceb48-8d57-5a03-bd4b-ef9abca76ce0'::uuid, '9daec196-fa5a-5330-a178-d9d5bb22b061'::uuid, 'Une solution de solvant usagée peut être jetée à l’évier si on la dilue.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les déchets chimiques sont collectés dans des bidons triés, jamais à l’évier.', 7),
    ('648c0658-f63c-51bf-9312-60b067e7fd65'::uuid, '9daec196-fa5a-5330-a178-d9d5bb22b061'::uuid, 'Que signifie DASRI ?', 'mcq', '["Dossier d’analyse des risques","Désinfection automatique des surfaces","Dispositif anti-souillure","Déchets d’activités de soins à risques infectieux"]'::jsonb, 3, 'Ces déchets suivent une filière d’élimination spécifique.', 8),
    ('eba4a948-bdbf-515d-8865-0ba4ca2e31b9'::uuid, '9daec196-fa5a-5330-a178-d9d5bb22b061'::uuid, 'Le poste de sécurité microbiologique protège notamment…', 'mcq', '["Uniquement la culture","Le manipulateur et l’environnement","Uniquement contre les vapeurs d’acide","Contre le risque électrique"]'::jsonb, 1, 'Il filtre l’air aspiré et rejeté ; certaines classes protègent aussi le produit.', 9),
    ('c672fd10-a8da-55fd-bd90-f3a84eb7159d'::uuid, '9daec196-fa5a-5330-a178-d9d5bb22b061'::uuid, 'Pourquoi respecter le temps de contact d’un désinfectant ?', 'mcq', '["Parce qu’il est toxique","Pour qu’il sèche joliment","Pour éviter de l’acheter à nouveau","Il n’agit que s’il reste assez longtemps sur la surface"]'::jsonb, 3, 'L’inactivation des micro-organismes demande un certain temps.', 10),
    ('5d2d9775-e545-59ad-8ac2-5542ef2b1864'::uuid, '9daec196-fa5a-5330-a178-d9d5bb22b061'::uuid, 'Un laboratoire de lycée est en général de niveau de confinement…', 'mcq', '["L4","L3","L1, parfois L2","Aucun niveau"]'::jsonb, 2, 'Les niveaux L3 et L4 sont réservés aux agents pathogènes graves.', 11),
    ('161e611c-e54a-51fd-9e20-da6c1cc0e939'::uuid, '9daec196-fa5a-5330-a178-d9d5bb22b061'::uuid, 'Dans la prévention, on privilégie d’abord…', 'mcq', '["La protection collective","Les gants","Les lunettes","La chance"]'::jsonb, 0, 'Les EPI ne viennent qu’en complément des protections collectives.', 12),
    ('ecbdfe13-582b-5963-b1da-9eac94e7fa42'::uuid, '03ef3a8d-c6ce-54e0-99d2-892356a70549'::uuid, 'Le mesurande est…', 'mcq', '["L’appareil de mesure","La grandeur qu’on veut mesurer","Le nombre affiché par l’appareil","L’unité utilisée"]'::jsonb, 1, 'Par exemple, la concentration en glucose d’un sérum.', 1),
    ('a834c11d-f8cc-5b09-87d5-9a3cebc5204e'::uuid, '03ef3a8d-c6ce-54e0-99d2-892356a70549'::uuid, 'Quelle est l’unité usuelle d’une concentration en masse ?', 'mcq', '["mol·L⁻¹","g·L⁻¹","g·mol⁻¹","L·g⁻¹"]'::jsonb, 1, 'Concentration en masse = masse de soluté / volume de solution.', 2),
    ('a8ebd6de-d456-5686-9ef2-d9b09a1a3154'::uuid, '03ef3a8d-c6ce-54e0-99d2-892356a70549'::uuid, 'La concentration en quantité de matière s’exprime par…', 'mcq', '["C = m / n","C = m × V","C = V / n","C = n / V"]'::jsonb, 3, 'Elle s’exprime en mol·L⁻¹.', 3),
    ('1e6eebc9-333e-5900-993f-3901febcf89a'::uuid, '03ef3a8d-c6ce-54e0-99d2-892356a70549'::uuid, 'Une fiole jaugée est une verrerie…', 'mcq', '["« In » : elle contient exactement son volume","« Ex » : elle délivre son volume","Sans précision","Utilisée pour chauffer"]'::jsonb, 0, 'On l’utilise pour préparer une solution de volume exact.', 4),
    ('2551507e-32f3-5722-b038-53de52a4193e'::uuid, '03ef3a8d-c6ce-54e0-99d2-892356a70549'::uuid, 'Pour prélever un volume exact de 10,0 mL, on choisit…', 'mcq', '["Une éprouvette de 100 mL","Un bécher","Une pipette jaugée","Un erlenmeyer"]'::jsonb, 2, 'C’est la verrerie la plus exacte pour délivrer un volume fixe.', 5),
    ('d9c8374c-4179-5487-b32a-46f1af630a0d'::uuid, '03ef3a8d-c6ce-54e0-99d2-892356a70549'::uuid, 'Pourquoi préciser des indices comme ρ(glucose, sérum) ?', 'mcq', '["Pour arrondir le résultat","Pour changer l’unité","Pour indiquer l’entité et la matrice","Par pure décoration"]'::jsonb, 2, 'Sans indices, on ne sait pas de quoi et dans quoi on parle.', 6),
    ('e5ab755d-9826-58ad-9482-e9bcc04666b6'::uuid, '03ef3a8d-c6ce-54e0-99d2-892356a70549'::uuid, 'La graduation d’un bécher permet une mesure de volume précise.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ses graduations sont indicatives : il sert à contenir, pas à mesurer.', 7),
    ('9857b82d-235f-50df-9b5a-2b93937472cb'::uuid, '03ef3a8d-c6ce-54e0-99d2-892356a70549'::uuid, 'La masse est une grandeur…', 'mcq', '["De base","Dérivée","Sans unité","Calculée à partir du volume"]'::jsonb, 0, 'Son unité SI est le kilogramme.', 8),
    ('edcdd836-c354-5c7f-a030-f87defe31d19'::uuid, '03ef3a8d-c6ce-54e0-99d2-892356a70549'::uuid, 'Où trouve-t-on la tolérance d’un instrument ?', 'mcq', '["Sur l’étiquette du produit à doser","Dans le compte rendu de l’élève","Nulle part","Sur l’instrument ou dans sa fiche technique"]'::jsonb, 3, 'Elle indique l’intervalle de confiance des indications.', 9),
    ('1b5221d2-bb6f-5584-8317-74e5048f46db'::uuid, '03ef3a8d-c6ce-54e0-99d2-892356a70549'::uuid, 'L’indication d’un instrument est…', 'mcq', '["Le résultat final corrigé","Ce qu’il affiche","La tolérance","Le mesurande"]'::jsonb, 1, 'Elle devient une valeur mesurée après traitement par le modèle de mesure.', 10),
    ('2018f535-383a-51fb-a418-19fa760e9710'::uuid, '03ef3a8d-c6ce-54e0-99d2-892356a70549'::uuid, 'Pour une pipette jaugée « ex » à un trait, on…', 'mcq', '["Utilise la bouche","Souffle toujours la dernière goutte","Remplit au-delà du trait","Ne souffle pas la dernière goutte"]'::jsonb, 3, 'Elle est étalonnée en tenant compte du liquide qui reste dans la pointe.', 11),
    ('1c600909-8033-5fa5-823c-915823cdbfd4'::uuid, '03ef3a8d-c6ce-54e0-99d2-892356a70549'::uuid, 'Un résultat de concentration en g·mL au lieu de g·mL⁻¹ révèle…', 'mcq', '["Un instrument « in »","Une mesure très exacte","Une erreur dans le calcul","Une grandeur de base"]'::jsonb, 2, 'L’analyse de l’unité permet de vérifier la formule employée.', 12),
    ('99bbf6cc-f2a2-51b5-81a0-161764d2d338'::uuid, '3a14c7bd-85d9-5498-84cd-8490abb25955'::uuid, 'Un étalon est une solution…', 'mcq', '["De valeur connue avec exactitude","De concentration inconnue","Toujours colorée","Préparée par l’élève sans contrôle"]'::jsonb, 0, 'C’est la référence qui permet de relier l’indication à la valeur.', 1),
    ('cf405fca-46cc-53e5-8406-4d173f2f77bd'::uuid, '3a14c7bd-85d9-5498-84cd-8490abb25955'::uuid, 'Avec un étalon unique, la concentration de l’essai vaut…', 'mcq', '["C(étalon) × A(étalon) / A(essai)","C(étalon) × A(essai) / A(étalon)","A(essai) − A(étalon)","C(étalon) + A(essai)"]'::jsonb, 1, 'On suppose la proportionnalité entre absorbance et concentration.', 2),
    ('0e6c1dd0-19a7-5cc2-8d59-5183b58ea8c9'::uuid, '3a14c7bd-85d9-5498-84cd-8490abb25955'::uuid, 'Étalon à 2,0 g·L⁻¹ d’absorbance 0,50 ; essai d’absorbance 0,75. Concentration de l’essai ?', 'mcq', '["1,3 g·L⁻¹","3,0 g·L⁻¹","2,5 g·L⁻¹","0,75 g·L⁻¹"]'::jsonb, 1, '2,0 × 0,75 / 0,50 = 3,0 g·L⁻¹.', 3),
    ('5f66b3f0-7187-5e9c-b50c-04de6985cf89'::uuid, '3a14c7bd-85d9-5498-84cd-8490abb25955'::uuid, 'L’équation aux unités sert à…', 'mcq', '["Trouver l’incertitude","Calculer la valeur numérique","Choisir le spectrophotomètre","Vérifier l’homogénéité de la formule"]'::jsonb, 3, 'Si les unités ne concordent pas, la formule est fausse.', 4),
    ('c35463ed-04a1-559a-93f8-11a5270fd0aa'::uuid, '3a14c7bd-85d9-5498-84cd-8490abb25955'::uuid, 'Une erreur systématique…', 'mcq', '["Décale les résultats toujours dans le même sens","Varie au hasard d’une mesure à l’autre","N’arrive qu’une fois","N’existe pas avec un bon appareil"]'::jsonb, 0, 'Un étalon mal préparé fausse toute la série de la même façon.', 5),
    ('068cd10c-0fab-5263-a4ed-7d20e131f0f4'::uuid, '3a14c7bd-85d9-5498-84cd-8490abb25955'::uuid, 'À quoi sert l’étalon de contrôle ?', 'mcq', '["À faire le zéro de l’appareil","À calculer la concentration des essais","À vérifier l’exactitude de la série","À diluer les échantillons"]'::jsonb, 2, 'Il doit être indépendant de l’étalon de dosage.', 6),
    ('e8d32240-288c-5a55-adf5-67d878ad5649'::uuid, '3a14c7bd-85d9-5498-84cd-8490abb25955'::uuid, 'Valeur cible 10,0 ; EMT 0,5 ; contrôle mesuré 10,7. La série est…', 'mcq', '["À moitié validée","Validée","Refusée","Impossible à juger"]'::jsonb, 2, 'L’intervalle d’acceptabilité est [9,5 ; 10,5] : 10,7 en sort.', 7),
    ('6e6d5d4f-b233-5f1e-8cb7-83ebb84e361f'::uuid, '3a14c7bd-85d9-5498-84cd-8490abb25955'::uuid, 'Inverser deux cuves lors de la lecture est une erreur…', 'mcq', '["Grossière","Aléatoire","Systématique permanente","Inévitable"]'::jsonb, 0, 'C’est une faute ponctuelle qui produit une valeur aberrante.', 8),
    ('e17203e7-8e52-53af-a512-72aee276aa95'::uuid, '3a14c7bd-85d9-5498-84cd-8490abb25955'::uuid, 'On peut lire un essai en dehors de l’intervalle couvert par la gamme d’étalonnage.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Hors de la gamme, rien ne garantit que la relation reste linéaire : on dilue l’essai.', 9),
    ('347c1927-faff-50e0-b8f0-dd4ea8533600'::uuid, '3a14c7bd-85d9-5498-84cd-8490abb25955'::uuid, 'Quel résultat est correctement écrit ?', 'mcq', '["C = ± 0,3 mmol·L⁻¹","C = 5,2437 ± 0,3","C = 5,2 mmol","C = (5,2 ± 0,3) mmol·L⁻¹"]'::jsonb, 3, 'Valeur, incertitude et unité, avec un nombre de chiffres cohérent.', 10),
    ('ed140001-0548-5801-80e8-8ba7cb5e55bd'::uuid, '3a14c7bd-85d9-5498-84cd-8490abb25955'::uuid, 'La dispersion de mesures répétées révèle surtout…', 'mcq', '["L’erreur systématique","L’erreur aléatoire","L’erreur grossière seulement","L’exactitude"]'::jsonb, 1, 'Une erreur systématique ne se voit pas en répétant la même procédure.', 11),
    ('b62c38f0-84c6-5f42-9496-6ae9bbf18624'::uuid, '3a14c7bd-85d9-5498-84cd-8490abb25955'::uuid, 'Pourquoi préférer une gamme d’étalonnage à un étalon unique ?', 'mcq', '["Elle supprime toutes les erreurs","Elle est plus rapide","Elle ne demande aucun calcul","Elle vérifie la linéarité sur l’intervalle de mesure"]'::jsonb, 3, 'Plusieurs points confirment que la relation est bien proportionnelle.', 12),
    ('e16c977b-ccb9-5f7a-9089-784a2fdbcad4'::uuid, '7fe07217-8149-572a-8537-c74d5ce854a4'::uuid, 'Oculaire × 10 et objectif × 40 : quel grossissement total ?', 'mcq', '["× 4","× 50","× 400","× 4 000"]'::jsonb, 2, 'On multiplie les deux grossissements.', 1),
    ('91d8c4df-2d2c-59c0-89d8-574791b93101'::uuid, '7fe07217-8149-572a-8537-c74d5ce854a4'::uuid, 'L’huile à immersion s’utilise avec l’objectif…', 'mcq', '["× 100","× 10","× 40","× 4"]'::jsonb, 0, 'Elle limite la déviation de la lumière et améliore la netteté aux forts grossissements.', 2),
    ('9f6d135b-e9db-597a-ba8a-16cdbebde59e'::uuid, '7fe07217-8149-572a-8537-c74d5ce854a4'::uuid, 'Un état frais permet surtout d’observer…', 'mcq', '["Le type de paroi","La mobilité des bactéries vivantes","L’ADN","Les ribosomes"]'::jsonb, 1, 'Sans coloration ni fixation, les cellules sont vivantes.', 3),
    ('4e656f6d-effa-5904-975f-09eb0d8c0906'::uuid, '7fe07217-8149-572a-8537-c74d5ce854a4'::uuid, 'Après une coloration de Gram, une bactérie Gram positif apparaît…', 'mcq', '["Rose","Violette","Verte","Incolore"]'::jsonb, 1, 'Sa paroi épaisse de peptidoglycane retient le violet malgré l’alcool.', 4),
    ('1c9a0d86-8431-556c-817f-fc1a036f0e0a'::uuid, '7fe07217-8149-572a-8537-c74d5ce854a4'::uuid, 'Quelle étape de la coloration de Gram est la plus critique ?', 'mcq', '["L’observation","La fixation","Le séchage","La décoloration à l’alcool"]'::jsonb, 3, 'Sa durée conditionne directement le résultat.', 5),
    ('8d2169ba-6527-50e7-9e19-7d290c740bec'::uuid, '7fe07217-8149-572a-8537-c74d5ce854a4'::uuid, 'Quel réactif sert de mordant dans la coloration de Gram ?', 'mcq', '["Le Lugol","La fuchsine","L’alcool","L’huile à immersion"]'::jsonb, 0, 'Il forme avec le violet un complexe qui se fixe dans la paroi.', 6),
    ('d1442fc2-0f2a-5bb8-ba21-a8cb9d6534a2'::uuid, '7fe07217-8149-572a-8537-c74d5ce854a4'::uuid, 'Une bactérie qui tremble sur place sans se déplacer est mobile.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ce tremblement est le mouvement brownien ; une bactérie mobile traverse le champ.', 7),
    ('c7402f79-2aa0-560e-a5d4-2516e1896790'::uuid, '7fe07217-8149-572a-8537-c74d5ce854a4'::uuid, 'Quand on augmente le grossissement, le champ microscopique…', 'mcq', '["Reste le même","Augmente","Diminue","Disparaît"]'::jsonb, 2, 'On voit plus gros mais une zone plus petite.', 8),
    ('3d205561-02f9-5a09-aa48-90e5e201f295'::uuid, '7fe07217-8149-572a-8537-c74d5ce854a4'::uuid, 'En changeant d’objectif, on règle la mise au point avec…', 'mcq', '["Le diaphragme","La vis macrométrique en grand","La vis micrométrique seulement","La lampe"]'::jsonb, 2, 'La vis macrométrique risquerait d’écraser la lame contre l’objectif.', 9),
    ('001b9261-73c6-54fc-9dbe-5c5e76184e25'::uuid, '7fe07217-8149-572a-8537-c74d5ce854a4'::uuid, 'Un dessin d’observation doit être…', 'mcq', '["Fidèle, titré, légendé, avec une échelle","Colorié au feutre","Complété de ce qu’on sait du cours","Sans légende"]'::jsonb, 0, 'On dessine ce qu’on voit réellement.', 10),
    ('1987aed8-894c-50e8-98df-36ed9bee8dda'::uuid, '7fe07217-8149-572a-8537-c74d5ce854a4'::uuid, 'Une graduation vaut 2 µm ; une cellule en couvre 5. Sa taille est…', 'mcq', '["0,4 µm","2,5 µm","7 µm","10 µm"]'::jsonb, 3, '5 × 2 µm = 10 µm.', 11),
    ('7fa19cd1-198a-567b-b3c8-0f7507075de2'::uuid, '7fe07217-8149-572a-8537-c74d5ce854a4'::uuid, 'Une bactérie Gram négatif possède…', 'mcq', '["Une paroi très épaisse","Un peptidoglycane fin et une membrane externe","Un noyau","Aucune paroi"]'::jsonb, 1, 'L’alcool traverse la membrane externe et décolore le peptidoglycane fin.', 12),
    ('0061fa41-2bc5-5a57-93b3-2381cd888dda'::uuid, '8326a045-4771-5dea-9fe3-3b97b47f199f'::uuid, 'Qu’est-ce qui distingue d’abord une cellule procaryote ?', 'mcq', '["L’absence de ribosomes","La présence de chloroplastes","Sa grande taille","L’absence de noyau"]'::jsonb, 3, 'Son ADN est libre dans le cytoplasme.', 1),
    ('a55f3f32-9015-5f98-9276-e809fe5b07ed'::uuid, '8326a045-4771-5dea-9fe3-3b97b47f199f'::uuid, 'Une levure est…', 'mcq', '["Une algue","Une bactérie","Un champignon unicellulaire eucaryote","Un virus"]'::jsonb, 2, 'Elle possède un noyau et des organites.', 2),
    ('f07cbcfc-768d-5fcf-a2c9-f290b2a34679'::uuid, '8326a045-4771-5dea-9fe3-3b97b47f199f'::uuid, 'Quel signe permet de reconnaître une levure au microscope ?', 'mcq', '["Le bourgeonnement","Les chloroplastes","La coloration rose au Gram","Le flagelle"]'::jsonb, 0, 'Une cellule fille pousse sur la cellule mère.', 3),
    ('90745c70-f390-5341-8406-ec658f005e5d'::uuid, '8326a045-4771-5dea-9fe3-3b97b47f199f'::uuid, 'Une micro-algue se reconnaît à…', 'mcq', '["Son absence de noyau","Ses chloroplastes","Sa paroi de peptidoglycane","Sa taille de 0,1 µm"]'::jsonb, 1, 'Elle réalise la photosynthèse.', 4),
    ('f598c80e-0dbf-52f5-87b1-67523d09ddc7'::uuid, '8326a045-4771-5dea-9fe3-3b97b47f199f'::uuid, 'Quelle taille a typiquement une bactérie ?', 'mcq', '["Environ 1 mm","Environ 1 µm","Environ 10 nm","Environ 100 µm"]'::jsonb, 1, 'C’est à la limite de ce que distingue le microscope optique.', 5),
    ('229d9aa0-05d5-5737-85ce-f1cee3991e87'::uuid, '8326a045-4771-5dea-9fe3-3b97b47f199f'::uuid, 'Pour observer les ribosomes, il faut un microscope…', 'mcq', '["Une simple loupe","Optique × 400","Optique × 100","Électronique"]'::jsonb, 3, 'Les ribosomes mesurent environ 20 à 30 nm.', 6),
    ('6f39b565-982a-50b6-9f96-93651acc0fe9'::uuid, '8326a045-4771-5dea-9fe3-3b97b47f199f'::uuid, 'Les Archées sont des eucaryotes.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ce sont des procaryotes, formant un domaine distinct des Bactéries.', 7),
    ('695c4797-104b-5774-9ee3-614d1630f2f6'::uuid, '8326a045-4771-5dea-9fe3-3b97b47f199f'::uuid, 'Quels sont les trois domaines du vivant ?', 'mcq', '["Bactéries, Archées, Eucaryotes","Animaux, Végétaux, Champignons","Virus, Bactéries, Levures","Procaryotes, Virus, Algues"]'::jsonb, 0, 'Les virus ne font pas partie de cette classification du vivant cellulaire.', 8),
    ('4914d88f-f8e5-5f4d-aeb7-5054c6bbb02e'::uuid, '8326a045-4771-5dea-9fe3-3b97b47f199f'::uuid, 'La paroi des bactéries contient en général…', 'mcq', '["De la chitine","De la cellulose","Du peptidoglycane","Du cholestérol"]'::jsonb, 2, 'C’est elle que révèle la coloration de Gram.', 9),
    ('72ab5790-8158-5878-a392-10c3b32bd7f0'::uuid, '8326a045-4771-5dea-9fe3-3b97b47f199f'::uuid, 'Un cliché en noir et blanc montrant la double membrane d’une mitochondrie provient…', 'mcq', '["D’une loupe binoculaire","D’un microscope optique","D’un microscope électronique","D’une échographie"]'::jsonb, 2, 'Ces détails sont bien en dessous de la limite du microscope optique.', 10),
    ('40adf825-d7b1-5c76-b20c-ab54be41d3ec'::uuid, '8326a045-4771-5dea-9fe3-3b97b47f199f'::uuid, 'Une levure est plus proche parente de l’être humain que d’une bactérie.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Levures et humains sont tous deux eucaryotes.', 11),
    ('f1ae007c-fe29-5e6f-b9c1-b860e6c58814'::uuid, '8326a045-4771-5dea-9fe3-3b97b47f199f'::uuid, 'Chez une moisissure, on observe au microscope…', 'mcq', '["Des filaments et un appareil sporifère","Des bourgeons isolés seulement","Des chloroplastes","Des coques en chaînettes"]'::jsonb, 0, 'Les moisissures sont des champignons filamenteux.', 12),
    ('5ccb57b1-afaf-5234-a1b7-be2597a3cd33'::uuid, '447aa861-2249-55a5-865e-0e5ac2effe98'::uuid, 'Stérile signifie…', 'mcq', '["Désinfecté en surface","Nettoyé à l’eau","Pauvre en micro-organismes","Exempt de tout micro-organisme vivant"]'::jsonb, 3, 'Aucun micro-organisme vivant, pas même une spore.', 1),
    ('69e7ea15-6088-5c02-89e7-97cedf6c88b0'::uuid, '447aa861-2249-55a5-865e-0e5ac2effe98'::uuid, 'La zone d’asepsie autour d’un bec Bunsen s’étend sur environ…', 'mcq', '["1 m","15 à 20 cm","2 mm","Toute la pièce"]'::jsonb, 1, 'Les courants d’air chaud y éloignent les particules en suspension.', 2),
    ('1e156a27-3a39-5051-b7e6-f088051539ea'::uuid, '447aa861-2249-55a5-865e-0e5ac2effe98'::uuid, 'Quel est le barème usuel de l’autoclave ?', 'mcq', '["60 °C pendant 10 min","100 °C pendant 1 min","37 °C pendant 24 h","121 °C pendant environ 20 min"]'::jsonb, 3, 'La vapeur sous pression atteint 121 °C et détruit même les spores.', 3),
    ('64ef0299-d5e5-5684-9924-7a751adef3d4'::uuid, '447aa861-2249-55a5-865e-0e5ac2effe98'::uuid, 'Comment stériliser une solution de vitamines sensible à la chaleur ?', 'mcq', '["Au four Pasteur","À l’autoclave","Par filtration sur membrane de 0,22 µm","Par flambage"]'::jsonb, 2, 'Les pores retiennent les bactéries sans chauffer la solution.', 4),
    ('9a7fa2cd-5459-5dd3-ad01-ac5c1ea6de4d'::uuid, '447aa861-2249-55a5-865e-0e5ac2effe98'::uuid, 'On flambe l’anse métallique…', 'mcq', '["Avant et après usage","Seulement avant","Seulement après","Jamais"]'::jsonb, 0, 'Avant pour ne pas contaminer la culture, après pour ne pas contaminer la paillasse.', 5),
    ('9f97a3a4-4482-583e-8f7a-32dc89697c8c'::uuid, '447aa861-2249-55a5-865e-0e5ac2effe98'::uuid, 'On peut poser le bouchon d’un tube stérile sur la paillasse pendant l’ensemencement.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On le garde dans la main : la paillasse n’est pas stérile.', 6),
    ('b90b2e4d-eba2-5df3-85a2-7e31eebc29fc'::uuid, '447aa861-2249-55a5-865e-0e5ac2effe98'::uuid, 'Pourquoi l’autoclave atteint-il 121 °C avec de l’eau ?', 'mcq', '["Il utilise de l’huile","La vapeur est sous pression, l’eau bout au-dessus de 100 °C","Il fonctionne sous vide","Grâce à un rayonnement"]'::jsonb, 1, 'L’augmentation de pression élève la température d’ébullition.', 7),
    ('7e2a5b73-70a4-5e34-83d5-c124f1405c92'::uuid, '447aa861-2249-55a5-865e-0e5ac2effe98'::uuid, 'Une gélose touchée avec un doigt puis incubée montre…', 'mcq', '["Aucune croissance","Des colonies de micro-organismes environnementaux","Des cristaux","Des cellules humaines en culture"]'::jsonb, 1, 'La peau porte de nombreux micro-organismes.', 8),
    ('972f08ec-5f5e-57fb-b2ab-7a82e14b17ab'::uuid, '447aa861-2249-55a5-865e-0e5ac2effe98'::uuid, 'Le four Pasteur stérilise par…', 'mcq', '["Rayons UV","Chaleur humide sous pression","Filtration","Chaleur sèche"]'::jsonb, 3, 'Il faut une température plus élevée et plus longue qu’avec la chaleur humide.', 9),
    ('1e6ba1bd-2878-5be4-bc88-287085923f30'::uuid, '447aa861-2249-55a5-865e-0e5ac2effe98'::uuid, 'Le travail aseptique protège…', 'mcq', '["La culture et le manipulateur","Uniquement le manipulateur","Uniquement la culture","Uniquement la paillasse"]'::jsonb, 0, 'Il empêche les échanges de micro-organismes dans les deux sens.', 10),
    ('91eb032c-a8d6-5242-85aa-1fea808a1a88'::uuid, '447aa861-2249-55a5-865e-0e5ac2effe98'::uuid, 'Sur un autoclave, le manomètre indique…', 'mcq', '["La durée","La température","La pression","Le volume"]'::jsonb, 2, 'Il permet de vérifier que les conditions du barème sont atteintes.', 11),
    ('fdd889d7-1118-5d06-9697-c64190dff2c0'::uuid, '447aa861-2249-55a5-865e-0e5ac2effe98'::uuid, 'Les boîtes de Petri en plastique à usage unique sont en général stérilisées par…', 'mcq', '["Flambage","Autoclave au lycée","Irradiation","Four Pasteur"]'::jsonb, 2, 'Le plastique ne supporte pas la chaleur : l’industrie utilise les rayons gamma.', 12),
    ('15114b30-22a5-5073-ae68-fdb1128eedb3'::uuid, 'a55a9a3f-e969-5569-87fb-16c62bc527fe'::uuid, 'Une micro-algue qui utilise la lumière et le CO₂ est…', 'mcq', '["Photolithotrophe","Chimio-organotrophe","Parasite","Hétérotrophe exigeante"]'::jsonb, 0, 'Énergie lumineuse, carbone minéral.', 1),
    ('f021bc99-835e-58a5-8967-6d6ec1776c0f'::uuid, 'a55a9a3f-e969-5569-87fb-16c62bc527fe'::uuid, 'Un milieu sélectif contient…', 'mcq', '["Des antibiotiques pour tuer toutes les bactéries","Uniquement de l’eau","Un indicateur de pH seulement","Des agents inhibiteurs"]'::jsonb, 3, 'Ils empêchent certains micro-organismes de pousser pour favoriser les autres.', 2),
    ('c34d77ac-82fb-51a2-856f-205152e797d9'::uuid, 'a55a9a3f-e969-5569-87fb-16c62bc527fe'::uuid, 'Sur un milieu lactosé avec indicateur de pH, le virage de couleur autour d’une colonie signifie…', 'mcq', '["Qu’elle est morte","Qu’elle fermente le lactose et acidifie le milieu","Qu’elle est Gram positif","Qu’elle est contaminée"]'::jsonb, 1, 'C’est le principe d’un milieu d’orientation.', 3),
    ('d58b8f09-d8b5-5c04-865a-d4856d941858'::uuid, 'a55a9a3f-e969-5569-87fb-16c62bc527fe'::uuid, 'Une colonie est…', 'mcq', '["Un contaminant","Une seule bactérie","Un milieu de culture","Un amas visible issu d’une cellule ou d’un petit groupe"]'::jsonb, 3, 'Des millions de cellules issues de la multiplication d’une seule.', 4),
    ('5de4a926-b808-5097-bab4-2994d3d58ab0'::uuid, 'a55a9a3f-e969-5569-87fb-16c62bc527fe'::uuid, 'À quoi sert l’isolement par stries en quadrants ?', 'mcq', '["À stériliser la gélose","À compter précisément les bactéries","À obtenir des colonies bien séparées","À colorer les bactéries"]'::jsonb, 2, 'L’inoculum est dilué de quadrant en quadrant.', 5),
    ('a7bab870-1935-5b19-a7a1-3f96182d6c3b'::uuid, 'a55a9a3f-e969-5569-87fb-16c62bc527fe'::uuid, 'Pourquoi incube-t-on les boîtes retournées ?', 'mcq', '["Pour éviter que la condensation tombe sur la gélose","Pour gagner de la place","Pour que les bactéries respirent","Pour faciliter la lecture"]'::jsonb, 0, 'Des gouttes sur la gélose étaleraient les colonies.', 6),
    ('39bd79d6-b4f9-580e-a2f4-81b554cda204'::uuid, 'a55a9a3f-e969-5569-87fb-16c62bc527fe'::uuid, 'Une culture pure présente des colonies toutes identiques.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Une colonie d’aspect différent signale un contaminant.', 7),
    ('b57c6012-3603-5bdf-905f-2334cff7895e'::uuid, 'a55a9a3f-e969-5569-87fb-16c62bc527fe'::uuid, 'L’étalon de Mac Farland sert à…', 'mcq', '["Mesurer le pH","Ajuster la densité d’un inoculum par comparaison de turbidité","Stériliser un milieu","Colorer un frottis"]'::jsonb, 1, 'On compare visuellement ou au densitomètre le trouble de la suspension.', 8),
    ('96a5b830-ca36-56cf-a65e-147f180c3f85'::uuid, 'a55a9a3f-e969-5569-87fb-16c62bc527fe'::uuid, 'Où écrit-on les indications sur une boîte de Petri ?', 'mcq', '["Sur le couvercle","Sur le fond","Sur la gélose","Nulle part"]'::jsonb, 1, 'Le couvercle peut être échangé ; le fond reste avec la culture.', 9),
    ('0c803b61-5b43-5c93-b3aa-4ef62eb4ff1a'::uuid, 'a55a9a3f-e969-5569-87fb-16c62bc527fe'::uuid, 'Une bactérie qui ne pousse qu’en absence de dioxygène est…', 'mcq', '["Photolithotrophe","Aérobie stricte","Aéro-anaérobie facultative","Anaérobie stricte"]'::jsonb, 3, 'Le dioxygène lui est toxique.', 10),
    ('2e11f8bc-d4ec-551c-8475-dfe8cc612b25'::uuid, 'a55a9a3f-e969-5569-87fb-16c62bc527fe'::uuid, 'Un milieu d’orientation contient notamment…', 'mcq', '["Un substrat fermentescible et un indicateur de pH","Uniquement des sels biliaires","De l’huile à immersion","Des globules rouges seulement"]'::jsonb, 0, 'Il révèle un caractère métabolique par un changement de couleur.', 11),
    ('7988d414-313c-50b4-9213-2d6609884f5c'::uuid, 'a55a9a3f-e969-5569-87fb-16c62bc527fe'::uuid, 'Les levures sont en général incubées vers…', 'mcq', '["60 °C","4 °C","25 à 30 °C","121 °C"]'::jsonb, 2, 'Elles préfèrent des températures plus basses que les bactéries pathogènes de l’humain.', 12),
    ('eee6aca1-3fcd-5de4-a2e9-64dab94aa5ff'::uuid, '1d793294-f0ca-5d9e-a4bb-31f45a344f43'::uuid, 'Comment écrit-on correctement le nom de la bactérie du côlon ?', 'mcq', '["ESCHERICHIA COLI","Escherichia Coli","Escherichia coli, en italique","escherichia coli"]'::jsonb, 2, 'Genre avec majuscule, espèce en minuscule, le tout en italique.', 1),
    ('21c6094b-6cbb-5f3a-8cde-b7edb04b9dda'::uuid, '1d793294-f0ca-5d9e-a4bb-31f45a344f43'::uuid, 'Dans le nom Staphylococcus aureus, « Staphylococcus » est…', 'mcq', '["Le genre","L’espèce","La famille","Le domaine"]'::jsonb, 0, 'Le premier mot du nom binomial est le genre.', 2),
    ('2ce27861-4331-5d5b-905e-095e6baf4f8f'::uuid, '1d793294-f0ca-5d9e-a4bb-31f45a344f43'::uuid, 'Les noms de familles bactériennes se terminent par…', 'mcq', '["-ales","-coccus","-us","-aceae"]'::jsonb, 3, 'Exemple : Enterobacteriaceae.', 3),
    ('bb644f21-ea56-5f06-8bc2-9c5690c770a3'::uuid, '1d793294-f0ca-5d9e-a4bb-31f45a344f43'::uuid, 'Des coques en grappe évoquent le genre…', 'mcq', '["Streptococcus","Staphylococcus","Escherichia","Saccharomyces"]'::jsonb, 1, 'Du grec staphylê, la grappe de raisin.', 4),
    ('3564a878-3a8b-5add-b88c-28b3a424145b'::uuid, '1d793294-f0ca-5d9e-a4bb-31f45a344f43'::uuid, 'Des coques en chaînettes évoquent le genre…', 'mcq', '["Vibrio","Staphylococcus","Bacillus","Streptococcus"]'::jsonb, 3, 'Du grec streptos, la chaîne tressée.', 5),
    ('ea19dc02-5088-598e-9786-37c1fb021f3a'::uuid, '1d793294-f0ca-5d9e-a4bb-31f45a344f43'::uuid, '« Bacillus sp. » signifie…', 'mcq', '["Une souche spéciale","Toutes les espèces de Bacillus","Une espèce non déterminée du genre Bacillus","Un bacille sporulé"]'::jsonb, 2, 'On connaît le genre mais pas encore l’espèce.', 6),
    ('035a32b0-8b0f-5f3d-b335-a4bf0ea2c336'::uuid, '1d793294-f0ca-5d9e-a4bb-31f45a344f43'::uuid, 'Un bacille est une bactérie…', 'mcq', '["En forme de bâtonnet","Sphérique","En spirale","En virgule"]'::jsonb, 0, 'Les formes sphériques sont les coques.', 7),
    ('92173cb6-50ae-50b4-86f9-872f9baa03fd'::uuid, '1d793294-f0ca-5d9e-a4bb-31f45a344f43'::uuid, 'La présence d’un bourgeon distingue une levure d’une bactérie.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Les bactéries se divisent en deux ; les levures bourgeonnent.', 8),
    ('563727a0-45b8-57f7-a1e8-fbcd038ed192'::uuid, '1d793294-f0ca-5d9e-a4bb-31f45a344f43'::uuid, 'Quel est le taxon le plus précis de la liste ?', 'mcq', '["Le genre","L’espèce","La famille","L’ordre"]'::jsonb, 1, 'C’est le dernier niveau de la hiérarchie.', 9),
    ('9f9d7463-8c01-5beb-930a-f687234dd2df'::uuid, '1d793294-f0ca-5d9e-a4bb-31f45a344f43'::uuid, 'Un dendrogramme permet de lire…', 'mcq', '["La taille des colonies","La proximité génétique entre souches","Le pH d’un milieu","La concentration en glucose"]'::jsonb, 1, 'Il indique les pourcentages de similitude entre taxons.', 10),
    ('0a66f39d-0035-55f8-8918-9d4422719ace'::uuid, '1d793294-f0ca-5d9e-a4bb-31f45a344f43'::uuid, 'Les caractères morphologiques suffisent toujours à identifier l’espèce.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils orientent ; les caractères culturaux et métaboliques confirment.', 11),
    ('a94fbc66-0182-5a48-b22d-7cca29085bfc'::uuid, '1d793294-f0ca-5d9e-a4bb-31f45a344f43'::uuid, 'À la main, le nom d’une espèce se…', 'mcq', '["Écrit sans distinction","Met entre guillemets","Écrit en majuscules","Souligne"]'::jsonb, 3, 'Le soulignement remplace l’italique à l’écrit manuscrit.', 12),
    ('326cf098-f836-5310-b12c-39b84fa3e856'::uuid, 'f044b7fa-a1e9-50ec-ab79-761c6d582b74'::uuid, 'La numération à l’hématimètre compte…', 'mcq', '["Toutes les cellules, vivantes et mortes","Seulement les cellules revivifiables","Les colonies","Les spores seulement"]'::jsonb, 0, 'Au microscope, on ne distingue pas une cellule viable d’une cellule morte.', 1),
    ('89dcd8dc-bfe1-5dcf-bdf3-f7aeb3bda608'::uuid, 'f044b7fa-a1e9-50ec-ab79-761c6d582b74'::uuid, 'Que signifie UFC ?', 'mcq', '["Unité de filtration contrôlée","Unité de fermentation cellulaire","Unité formant colonie","Unité fongique cultivée"]'::jsonb, 2, 'Une colonie peut provenir d’une cellule ou d’un petit amas.', 2),
    ('df08f866-000b-510b-9b62-f6868ae0ff98'::uuid, 'f044b7fa-a1e9-50ec-ab79-761c6d582b74'::uuid, '1 mL de suspension + 9 mL de diluant donne une dilution au…', 'mcq', '["1/100","1/9","1/10","1/1"]'::jsonb, 2, 'Volume final 10 mL, dont 1 mL de suspension.', 3),
    ('5c25e7d9-4e93-5698-8383-d9f7044330ce'::uuid, 'f044b7fa-a1e9-50ec-ab79-761c6d582b74'::uuid, 'On ensemence 1 mL de la dilution 10⁻² et on compte 80 colonies. La concentration est…', 'mcq', '["8,0 × 10³ UFC par mL","80 UFC par mL","8,0 × 10⁻¹ UFC par mL","8,0 × 10⁵ UFC par mL"]'::jsonb, 0, 'N = 80 / (1 × 10⁻²) = 8 000 UFC par mL.', 4),
    ('097a1e57-94de-53f9-9e14-526edf1b7d1e'::uuid, 'f044b7fa-a1e9-50ec-ab79-761c6d582b74'::uuid, 'On ensemence 0,1 mL de la dilution 10⁻³ et on compte 50 colonies. La concentration est…', 'mcq', '["5,0 × 10⁶ UFC par mL","5,0 × 10⁴ UFC par mL","5,0 × 10³ UFC par mL","5,0 × 10⁵ UFC par mL"]'::jsonb, 3, 'N = 50 / (0,1 × 10⁻³) = 500 000 UFC par mL.', 5),
    ('d8d01107-a95a-5d3f-a096-f2046eabbdb2'::uuid, 'f044b7fa-a1e9-50ec-ab79-761c6d582b74'::uuid, 'Quelles boîtes retient-on pour le calcul ?', 'mcq', '["Celles qui ont le plus de colonies","Celles ayant un nombre de colonies exploitable, environ 15 à 300","Celles qui n’ont aucune colonie","Toutes, sans exception"]'::jsonb, 1, 'Trop de colonies se chevauchent ; trop peu ne sont pas représentatives.', 6),
    ('7392c602-4c6f-5950-9648-7670e17e4148'::uuid, 'f044b7fa-a1e9-50ec-ab79-761c6d582b74'::uuid, 'Pourquoi change-t-on de pipette entre chaque dilution ?', 'mcq', '["Pour stériliser le diluant","Pour gagner du temps","Par économie","Pour ne pas transporter de cellules en excès"]'::jsonb, 3, 'Une pipette déjà utilisée garde des cellules sur ses parois.', 7),
    ('53b95dc5-14ed-5251-bf65-823ebbbaa2f7'::uuid, 'f044b7fa-a1e9-50ec-ab79-761c6d582b74'::uuid, 'Un critère microbiologique est…', 'mcq', '["Un milieu de culture","Une espèce bactérienne","Une valeur de référence réglementaire","Un type de microscope"]'::jsonb, 2, 'On y compare le résultat pour juger la conformité du produit.', 8),
    ('dce62b0d-656f-5f7b-9fd3-52ab61e8340f'::uuid, 'f044b7fa-a1e9-50ec-ab79-761c6d582b74'::uuid, 'Le dénombrement après culture ne compte que les cellules capables de se multiplier.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'On parle de cellules revivifiables.', 9),
    ('eb1dab44-0a34-55e1-b7bf-31f5b0cf5cb5'::uuid, 'f044b7fa-a1e9-50ec-ab79-761c6d582b74'::uuid, 'Pourquoi les méthodes de dénombrement sont-elles normalisées ?', 'mcq', '["Pour que les résultats de laboratoires différents soient comparables","Pour aller plus vite","Pour éviter de diluer","Pour se passer de témoins"]'::jsonb, 0, 'Même milieu, même incubation, même calcul.', 10),
    ('1fc4de47-8d1d-5807-8c61-ba36ce26b2de'::uuid, 'f044b7fa-a1e9-50ec-ab79-761c6d582b74'::uuid, 'Un rectangle de cellule de Malassez vaut 10⁻⁵ mL ; on y compte 20 cellules en moyenne, sans dilution. Concentration ?', 'mcq', '["2 × 10⁵ cellules par mL","2 × 10⁶ cellules par mL","2 × 10⁻⁴ cellules par mL","20 cellules par mL"]'::jsonb, 1, '20 / 10⁻⁵ = 2 × 10⁶ cellules par mL.', 11),
    ('fc17e2ca-95b8-50ae-b875-6e0c4e62f8d2'::uuid, 'f044b7fa-a1e9-50ec-ab79-761c6d582b74'::uuid, '10 g d’aliment dans 90 mL de diluant donne…', 'mcq', '["Une suspension au 1/9","Une suspension mère au 1/10","Une suspension au 1/100","Une solution non diluée"]'::jsonb, 1, '10 g dans un total d’environ 100 : dilution 10⁻¹.', 12),
    ('b2c0deaf-dd95-5ea3-a203-12db70d5c83f'::uuid, '2802e33c-2594-5ae8-8eb0-2db5530cbf4e'::uuid, 'Quelle masse de glucose faut-il pour 250,0 mL à 4,0 g·L⁻¹ ?', 'mcq', '["4,0 g","16 g","0,10 g","1,0 g"]'::jsonb, 3, 'm = ρ × V = 4,0 × 0,2500 = 1,0 g.', 1),
    ('bbb36e98-99cf-5429-8469-bc91c6065c35'::uuid, '2802e33c-2594-5ae8-8eb0-2db5530cbf4e'::uuid, 'La relation de la dilution est…', 'mcq', '["Ci × Vi = Cf × Vf","Ci + Vi = Cf + Vf","Ci / Vi = Cf / Vf","Ci × Vf = Cf × Vi"]'::jsonb, 0, 'Elle traduit la conservation de la quantité de soluté.', 2),
    ('4c4bc631-bb46-594b-ac49-2710dd004c67'::uuid, '2802e33c-2594-5ae8-8eb0-2db5530cbf4e'::uuid, 'On veut diluer 10 fois pour obtenir 100,0 mL. Quel volume de solution mère prélever ?', 'mcq', '["90,0 mL","1,0 mL","10,0 mL","100,0 mL"]'::jsonb, 2, 'Vi = Vf / F = 100,0 / 10 = 10,0 mL.', 3),
    ('d6fa1c7c-e7c0-57e5-9d1a-baff0deb49b1'::uuid, '2802e33c-2594-5ae8-8eb0-2db5530cbf4e'::uuid, 'Dans quel récipient prépare-t-on une solution de volume exact ?', 'mcq', '["Une éprouvette","Un bécher","Une fiole jaugée","Un erlenmeyer"]'::jsonb, 2, 'Elle est étalonnée pour contenir exactement son volume.', 4),
    ('1fd03687-6d8f-5824-a248-71c81174cf5e'::uuid, '2802e33c-2594-5ae8-8eb0-2db5530cbf4e'::uuid, 'Pourquoi rince-t-on la coupelle de pesée dans la fiole ?', 'mcq', '["Pour ne perdre aucune partie du soluté","Pour refroidir la solution","Pour nettoyer la balance","Pour diluer deux fois"]'::jsonb, 0, 'Sinon, la concentration obtenue est trop faible.', 5),
    ('639258c0-96d4-5edc-9566-b93381d4f366'::uuid, '2802e33c-2594-5ae8-8eb0-2db5530cbf4e'::uuid, 'Le facteur de dilution F vaut…', 'mcq', '["Vi / Vf","Cf / Ci","Ci × Cf","Ci / Cf"]'::jsonb, 3, 'Il vaut aussi Vf / Vi ; il est toujours supérieur à 1.', 6),
    ('14ebcd67-7eeb-5889-9698-c15bf4408842'::uuid, '2802e33c-2594-5ae8-8eb0-2db5530cbf4e'::uuid, 'Si l’on dépasse le trait de jauge, on peut retirer le surplus à la pipette.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Du soluté partirait avec : la solution est à refaire.', 7),
    ('3963940a-368c-5ab5-80f0-9405964b7fa9'::uuid, '2802e33c-2594-5ae8-8eb0-2db5530cbf4e'::uuid, 'Solution mère à 2,0 mol·L⁻¹ ; on prélève 5,0 mL qu’on complète à 50,0 mL. Concentration fille ?', 'mcq', '["20 mol·L⁻¹","0,20 mol·L⁻¹","0,50 mol·L⁻¹","2,0 mol·L⁻¹"]'::jsonb, 1, 'Cf = 2,0 × 5,0 / 50,0 = 0,20 mol·L⁻¹.', 8),
    ('1c049d92-9a75-553e-bb98-9f41762fb018'::uuid, '2802e33c-2594-5ae8-8eb0-2db5530cbf4e'::uuid, 'Dans une préparation par dilution, la grandeur d’entrée est…', 'mcq', '["Le pH","La masse de solide","La température","Le volume prélevé de solution mère"]'::jsonb, 3, 'La grandeur de sortie est la concentration de la solution fille.', 9),
    ('45968079-7c7b-5eee-9f73-61787f364432'::uuid, '2802e33c-2594-5ae8-8eb0-2db5530cbf4e'::uuid, 'Pour lire le trait de jauge, l’œil doit être…', 'mcq', '["En dessous du trait","Au-dessus de la fiole","À la hauteur du trait, bas du ménisque sur le trait","N’importe où"]'::jsonb, 2, 'Sinon, une erreur de parallaxe fausse le volume.', 10),
    ('f5d88867-2966-51d3-b61c-3f824a385f77'::uuid, '2802e33c-2594-5ae8-8eb0-2db5530cbf4e'::uuid, 'Pourquoi homogénéiser la solution après avoir complété au trait ?', 'mcq', '["Pour que la concentration soit la même partout","Pour la stériliser","Pour la chauffer","Pour changer sa couleur"]'::jsonb, 0, 'Le solvant ajouté en dernier reste sinon en surface.', 11),
    ('b2f289f6-1198-5683-96d0-e19589a1768b'::uuid, '2802e33c-2594-5ae8-8eb0-2db5530cbf4e'::uuid, 'On prélève la solution mère…', 'mcq', '["Directement dans le flacon","Dans un bécher, jamais directement dans le flacon","Avec une éprouvette pour être exact","À la bouche"]'::jsonb, 1, 'On évite ainsi de contaminer le flacon d’origine.', 12),
    ('062a2ecc-75d7-509d-ba97-ac2817029243'::uuid, 'c2e71c13-c962-566b-a62e-6487ebeda8af'::uuid, 'L’eau iodée révèle la présence…', 'mcq', '["De glucose","D’amidon","De protéines","De lipides"]'::jsonb, 1, 'L’amidon donne une coloration bleu-noir.', 1),
    ('bda0be92-6b25-5776-ac91-a10376ece2a5'::uuid, 'c2e71c13-c962-566b-a62e-6487ebeda8af'::uuid, 'Le réactif du biuret détecte…', 'mcq', '["L’ADN","Le glucose","L’amidon","Les liaisons peptidiques des protéines"]'::jsonb, 3, 'La coloration violette apparaît avec au moins deux liaisons peptidiques.', 2),
    ('f36fb22d-97b5-5a93-9c7b-020000347eef'::uuid, 'c2e71c13-c962-566b-a62e-6487ebeda8af'::uuid, 'La liqueur de Fehling à chaud donne un précipité rouge brique avec…', 'mcq', '["Un sucre réducteur comme le glucose","L’amidon","Les protéines","L’eau pure"]'::jsonb, 0, 'Le glucose réduit les ions cuivre(II) en oxyde de cuivre(I) rouge.', 3),
    ('7152baa2-5de4-5b5e-a7a3-350e120c0a39'::uuid, 'c2e71c13-c962-566b-a62e-6487ebeda8af'::uuid, 'Le témoin positif sert à prouver…', 'mcq', '["Que le résultat est négatif","Que l’échantillon est pur","Que le réactif fonctionne","Que la manipulation est terminée"]'::jsonb, 2, 'S’il ne réagit pas, le réactif est défectueux.', 4),
    ('bebe31bd-8831-5e88-8b49-aeda6471adc3'::uuid, 'c2e71c13-c962-566b-a62e-6487ebeda8af'::uuid, 'Pour faire le zéro du spectrophotomètre, on utilise…', 'mcq', '["Une cuve vide","La solution la plus concentrée","Une cuve contenant le solvant seul","De l’eau iodée"]'::jsonb, 2, 'On élimine ainsi l’absorbance du solvant et de la cuve.', 5),
    ('b1f84a91-ee0b-5cf8-9752-4792b74a284b'::uuid, 'c2e71c13-c962-566b-a62e-6487ebeda8af'::uuid, 'Pour mesurer l’absorbance de l’ADN à 260 nm, il faut une cuve…', 'mcq', '["En quartz","En plastique","En verre ordinaire","En métal"]'::jsonb, 0, 'Le plastique et le verre absorbent les ultraviolets.', 6),
    ('4dd4b69c-b704-56c7-8a55-d92c5145a0cb'::uuid, 'c2e71c13-c962-566b-a62e-6487ebeda8af'::uuid, 'Une solution qui absorbe surtout l’orange paraît…', 'mcq', '["Jaune","Orange","Rouge","Bleue"]'::jsonb, 3, 'On voit la couleur complémentaire de celle absorbée.', 7),
    ('8bd8295e-b737-569b-88f6-cc6a1890b10e'::uuid, 'c2e71c13-c962-566b-a62e-6487ebeda8af'::uuid, 'Un lait pasteurisé donne un test phosphatase alcaline positif. Cela signifie…', 'mcq', '["Que le lait est bien pasteurisé","Que la pasteurisation a été insuffisante","Que le lait est stérile","Que le test est inutile"]'::jsonb, 1, 'La PAL doit être détruite par une pasteurisation correcte.', 8),
    ('d67d70ca-bce8-5f28-9b10-90f27141c271'::uuid, 'c2e71c13-c962-566b-a62e-6487ebeda8af'::uuid, 'Un résultat qualitatif est interprétable même si le témoin négatif réagit.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Un témoin négatif positif signale une contamination ou un réactif non spécifique.', 9),
    ('98c6be52-9afe-5e29-91c5-702516765a0b'::uuid, 'c2e71c13-c962-566b-a62e-6487ebeda8af'::uuid, 'La longueur d’onde optimale correspond…', 'mcq', '["À 500 nm pour toutes les molécules","Au minimum d’absorbance","À la couleur de la solution","Au maximum d’absorbance du spectre"]'::jsonb, 3, 'On y mesure pour avoir la meilleure sensibilité.', 10),
    ('5619ad54-bb25-531e-90a7-152ffbfae39b'::uuid, 'c2e71c13-c962-566b-a62e-6487ebeda8af'::uuid, 'On détecte une enzyme en lui fournissant…', 'mcq', '["Un antibiotique","Un colorant","Son substrat spécifique","De l’huile à immersion"]'::jsonb, 2, 'Si le produit apparaît, l’enzyme est présente et active.', 11),
    ('6bca35b8-f595-58ec-a0f4-d65f36cd80a2'::uuid, 'c2e71c13-c962-566b-a62e-6487ebeda8af'::uuid, 'La ninhydrine à chaud révèle…', 'mcq', '["Les acides aminés","L’amidon","Les lipides","Le glucose"]'::jsonb, 0, 'Elle sert aussi à révéler les taches d’acides aminés sur une CCM.', 12),
    ('f124df94-13ff-5f85-a400-40e96320d1d4'::uuid, '82c738a6-aef4-5c53-9c17-ecc26bc44dfe'::uuid, 'Dans une chromatographie, la phase mobile…', 'mcq', '["Retient les molécules","Entraîne les molécules","Révèle les taches","Est toujours solide"]'::jsonb, 1, 'La phase fixe, elle, les retient.', 1),
    ('356bdab8-0499-5364-b96c-b13c0acd225d'::uuid, '82c738a6-aef4-5c53-9c17-ecc26bc44dfe'::uuid, 'Front de l’éluant à 10,0 cm, tache à 6,0 cm. Rf ?', 'mcq', '["1,67","0,60","6,0","0,40"]'::jsonb, 1, 'Rf = 6,0 / 10,0 = 0,60.', 2),
    ('b153bffc-5b00-52ec-b78c-4e193e3533ea'::uuid, '82c738a6-aef4-5c53-9c17-ecc26bc44dfe'::uuid, 'On identifie une tache du mélange quand elle a…', 'mcq', '["Un Rf égal à 1","La même couleur que l’éluant","Une taille plus grande","Le même Rf qu’un étalon"]'::jsonb, 3, 'Dans les mêmes conditions, une même molécule migre à la même hauteur.', 3),
    ('b07c6cb3-7cdd-5b28-b7b5-ff7face3ce0b'::uuid, '82c738a6-aef4-5c53-9c17-ecc26bc44dfe'::uuid, 'La ligne de dépôt d’une CCM se trace…', 'mcq', '["Au crayon","Au feutre","Au stylo à bille","À l’encre de Chine"]'::jsonb, 0, 'L’encre migrerait avec l’éluant et fausserait le chromatogramme.', 4),
    ('b64e46d7-5f75-5509-a7cb-df420090d9bc'::uuid, '82c738a6-aef4-5c53-9c17-ecc26bc44dfe'::uuid, 'Pourquoi la ligne de dépôt doit-elle être au-dessus du niveau de l’éluant ?', 'mcq', '["Pour mieux voir les taches","Pour aller plus vite","Pour que les dépôts ne se dissolvent pas dans la cuve","Pour saturer la cuve"]'::jsonb, 2, 'Les dépôts doivent migrer le long de la plaque, pas se diluer dans l’éluant.', 5),
    ('2099d9a1-7721-531d-bc7a-b031d24802b5'::uuid, '82c738a6-aef4-5c53-9c17-ecc26bc44dfe'::uuid, 'La CCM est une chromatographie…', 'mcq', '["Immunologique","Préparative","Analytique","Électrophorétique"]'::jsonb, 2, 'Elle sert à identifier, pas à récupérer des quantités.', 6),
    ('af15313b-a8ea-5532-af74-571bb85ce53d'::uuid, '82c738a6-aef4-5c53-9c17-ecc26bc44dfe'::uuid, 'Une molécule très retenue par la phase fixe a un Rf…', 'mcq', '["Faible","Élevé","Égal à 1","Supérieur à 1"]'::jsonb, 0, 'Elle avance peu par rapport au front de l’éluant.', 7),
    ('b3e4a39b-ff4e-5ae6-ba62-060c2353d5d0'::uuid, '82c738a6-aef4-5c53-9c17-ecc26bc44dfe'::uuid, 'Dans une chromatographie d’échange d’ions, les molécules se fixent à la résine par…', 'mcq', '["Des liaisons covalentes","Des liaisons peptidiques","Des ponts disulfure","Des liaisons ioniques"]'::jsonb, 3, 'Charges opposées de la molécule et de la phase fixe.', 8),
    ('49c1ca72-db56-5a98-9082-1181377da2e6'::uuid, '82c738a6-aef4-5c53-9c17-ecc26bc44dfe'::uuid, 'L’étape qui détache les molécules fixées s’appelle…', 'mcq', '["Le lavage","L’élution","La fixation","La révélation"]'::jsonb, 1, 'On modifie le pH ou la force ionique de la phase mobile.', 9),
    ('b86c6623-99c1-539f-8cce-1d337ad2fcab'::uuid, '82c738a6-aef4-5c53-9c17-ecc26bc44dfe'::uuid, 'Sur une résine chargée négativement à pH 7, quel acide aminé est retenu ?', 'mcq', '["Les deux","L’acide glutamique","Aucun","La lysine"]'::jsonb, 3, 'La lysine est chargée positivement à pH 7.', 10),
    ('993464d0-8205-5b43-bde7-edd1adb02b8b'::uuid, '82c738a6-aef4-5c53-9c17-ecc26bc44dfe'::uuid, 'L’absence de tache sur une CCM prouve l’absence de la molécule.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La molécule peut être présente sous la limite de détection.', 11),
    ('a5503d13-db37-5fac-a82a-12ccdd4b124a'::uuid, '82c738a6-aef4-5c53-9c17-ecc26bc44dfe'::uuid, 'Des dépôts trop gros sur une CCM donnent…', 'mcq', '["Un Rf plus grand","Une meilleure séparation","Des taches étalées qui se chevauchent","Une migration plus rapide"]'::jsonb, 2, 'Il faut des dépôts petits et concentrés.', 12),
    ('81bdc01d-b4e1-5922-87c3-4137247cd9f6'::uuid, '07824b0e-36c1-50b1-a0dd-82083f5443fb'::uuid, 'Dans la loi de Beer-Lambert A = ε × ℓ × c, ℓ désigne…', 'mcq', '["La longueur de cuve traversée par la lumière","La longueur d’onde","Le volume de la solution","Le coefficient d’absorption"]'::jsonb, 0, 'Elle vaut généralement 1 cm.', 1),
    ('bc4eca23-e83a-5c6e-88d7-faeb5e2db3f1'::uuid, '07824b0e-36c1-50b1-a0dd-82083f5443fb'::uuid, 'À ℓ et λ fixés, l’absorbance est…', 'mcq', '["Inversement proportionnelle à la concentration","Proportionnelle à la concentration","Indépendante de la concentration","Égale à la concentration"]'::jsonb, 1, 'Tant que la solution est assez diluée.', 2),
    ('8a270abc-e6e2-5286-bf3f-b3bef7e5fee2'::uuid, '07824b0e-36c1-50b1-a0dd-82083f5443fb'::uuid, 'Un chromogène est…', 'mcq', '["Une molécule naturellement colorée","Un produit coloré formé par réaction avec la molécule à doser","Un spectrophotomètre","Un solvant"]'::jsonb, 1, 'Il permet de doser une molécule incolore.', 3),
    ('b6e70fb9-0a51-5f32-84c7-1f9cd8f9193b'::uuid, '07824b0e-36c1-50b1-a0dd-82083f5443fb'::uuid, 'ε = 1,0 × 10⁴ L·mol⁻¹·cm⁻¹, ℓ = 1 cm, A = 0,50. Concentration ?', 'mcq', '["0,50 mol·L⁻¹","5,0 × 10³ mol·L⁻¹","2,0 × 10⁻⁴ mol·L⁻¹","5,0 × 10⁻⁵ mol·L⁻¹"]'::jsonb, 3, 'c = A / (ε × ℓ) = 0,50 / 10 000 = 5,0 × 10⁻⁵ mol·L⁻¹.', 4),
    ('23dab0e9-b036-51f9-9f29-889a879efcdd'::uuid, '07824b0e-36c1-50b1-a0dd-82083f5443fb'::uuid, 'Dans une gamme d’étalonnage, le tube 0 sert…', 'mcq', '["À faire le zéro de l’appareil","À contenir l’échantillon","À contrôler la température","À diluer l’essai"]'::jsonb, 0, 'Il contient tout sauf la molécule dosée.', 5),
    ('f6528203-b9d4-5e14-b4ad-eb529fa09587'::uuid, '07824b0e-36c1-50b1-a0dd-82083f5443fb'::uuid, 'Le dosage du glucose par la glucose oxydase est un dosage…', 'mcq', '["Immunologique","Chimique","Enzymatique","Volumétrique"]'::jsonb, 2, 'Le réactif est une enzyme spécifique du glucose.', 6),
    ('297e49a7-6ce0-5e48-b42c-0eaed0f5f5e9'::uuid, '07824b0e-36c1-50b1-a0dd-82083f5443fb'::uuid, 'Un essai d’absorbance supérieure à celle du tube le plus concentré de la gamme doit être…', 'mcq', '["Ignoré","Lu par extrapolation","Dilué puis dosé à nouveau","Mesuré dans une cuve plus longue sans calcul"]'::jsonb, 2, 'On ne lit un essai qu’à l’intérieur de la gamme.', 7),
    ('181a71e2-b735-5fe3-bfb0-52a0dadfab3f'::uuid, '07824b0e-36c1-50b1-a0dd-82083f5443fb'::uuid, 'Tous les tubes de la gamme ont le même volume total.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ainsi, seule la quantité de soluté varie d’un tube à l’autre.', 8),
    ('2deabd85-b5a1-5d72-a373-fe685e815ee2'::uuid, '07824b0e-36c1-50b1-a0dd-82083f5443fb'::uuid, 'La droite A = 0,40 × m (m en mg) ; l’essai lit A = 0,20. Masse dans le tube ?', 'mcq', '["0,50 mg","0,08 mg","2,0 mg","0,20 mg"]'::jsonb, 0, 'm = 0,20 / 0,40 = 0,50 mg.', 9),
    ('c8d29c4b-62c9-5999-b381-cd7900c87c85'::uuid, '07824b0e-36c1-50b1-a0dd-82083f5443fb'::uuid, 'On dose directement l’ADN en mesurant l’absorbance à…', 'mcq', '["800 nm","600 nm","340 nm","260 nm"]'::jsonb, 3, 'Les bases azotées absorbent dans l’ultraviolet vers 260 nm.', 10),
    ('b9807962-b51c-5f8b-bf1b-e3b53a5fc489'::uuid, '07824b0e-36c1-50b1-a0dd-82083f5443fb'::uuid, 'Pourquoi mesure-t-on à la longueur d’onde optimale ?', 'mcq', '["Parce que c’est plus rapide","Pour une sensibilité maximale","Pour éviter le zéro","Pour changer la couleur"]'::jsonb, 1, 'L’absorbance y varie le plus pour une même variation de concentration.', 11),
    ('ed0d45bb-49cf-5a2e-9eac-ebf181e7eaf2'::uuid, '07824b0e-36c1-50b1-a0dd-82083f5443fb'::uuid, 'Un dosage en point final se lit…', 'mcq', '["Avant d’ajouter le réactif","Au tout début de la réaction","Pendant l’ajout du réactif","Une fois la réaction terminée"]'::jsonb, 3, 'La coloration est alors stable et proportionnelle à la quantité de molécule.', 12),
    ('a8d82316-dd74-5fca-9cd1-a2d89ad11a0e'::uuid, '1aefef13-8a98-5fab-9984-8b8552174221'::uuid, 'Dans un titrage, la solution titrante est placée…', 'mcq', '["Dans une fiole jaugée","Dans le bécher","Dans la burette","Dans le spectrophotomètre"]'::jsonb, 2, 'On la verse progressivement sur la solution à doser.', 1),
    ('01b80656-97ba-5b31-b6af-255d681b8f5e'::uuid, '1aefef13-8a98-5fab-9984-8b8552174221'::uuid, 'À l’équivalence…', 'mcq', '["Les réactifs ont été introduits dans les proportions de l’équation","La solution titrante est épuisée","L’indicateur est détruit","Le pH vaut toujours 7"]'::jsonb, 0, 'Le réactif titré est alors entièrement consommé.', 2),
    ('77a1f17e-8b4d-5f8e-8d97-ddfea693588a'::uuid, '1aefef13-8a98-5fab-9984-8b8552174221'::uuid, 'Pour une réaction mole à mole, la relation à l’équivalence est…', 'mcq', '["C1 + V1 = C2 + VE","C1 × V1 = C2 × VE","C1 / V1 = C2 / VE","C1 × VE = C2 × V1"]'::jsonb, 1, 'Les quantités de matière des deux réactifs sont égales.', 3),
    ('3727e4c1-3897-5f4b-8e9a-f7b422422bc5'::uuid, '1aefef13-8a98-5fab-9984-8b8552174221'::uuid, '10,0 mL d’acide titrés par la soude à 0,20 mol·L⁻¹, VE = 15,0 mL. Concentration de l’acide ?', 'mcq', '["0,13 mol·L⁻¹","0,30 mol·L⁻¹","3,0 mol·L⁻¹","0,030 mol·L⁻¹"]'::jsonb, 1, 'C1 = 0,20 × 15,0 / 10,0 = 0,30 mol·L⁻¹.', 4),
    ('3ecee9ca-be45-5543-800c-37f20d40e99a'::uuid, '1aefef13-8a98-5fab-9984-8b8552174221'::uuid, 'Le dosage du vinaigre par la soude repose sur une réaction…', 'mcq', '["Enzymatique","D’oxydo-réduction","De précipitation","Acido-basique"]'::jsonb, 3, 'L’acide éthanoïque cède un ion H⁺ à l’ion hydroxyde.', 5),
    ('0a19ec7f-37d2-5603-b571-6f556124ecab'::uuid, '1aefef13-8a98-5fab-9984-8b8552174221'::uuid, 'Le dosage de la vitamine C par le DCPIP repose sur une réaction…', 'mcq', '["D’oxydo-réduction","Acido-basique","Enzymatique","Antigène-anticorps"]'::jsonb, 0, 'Le DCPIP oxyde la vitamine C et se décolore en étant réduit.', 6),
    ('59a1abc4-4681-5757-83d6-2c9f9ccdeb92'::uuid, '1aefef13-8a98-5fab-9984-8b8552174221'::uuid, 'La phénolphtaléine est incolore en milieu acide et rose en milieu basique.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Son virage signale le passage à un milieu basique, juste après l’équivalence.', 7),
    ('219cefca-5547-5fb7-b9b6-869a5e8abd5c'::uuid, '1aefef13-8a98-5fab-9984-8b8552174221'::uuid, 'Avant de remplir la burette, on la rince…', 'mcq', '["Avec la solution à doser","Avec de l’eau du robinet seulement","Avec la solution titrante","Avec de l’éthanol"]'::jsonb, 2, 'On évite ainsi de diluer la solution titrante.', 8),
    ('6b140d7b-076f-5d01-b6d6-77b3bb2e1352'::uuid, '1aefef13-8a98-5fab-9984-8b8552174221'::uuid, 'Une solution étalon est une solution…', 'mcq', '["Toujours basique","De concentration inconnue","De concentration connue avec exactitude","Préparée approximativement"]'::jsonb, 2, 'Elle sert de référence au dosage.', 9),
    ('9fdf98fc-17c2-5a1c-b272-479a078b7cbf'::uuid, '1aefef13-8a98-5fab-9984-8b8552174221'::uuid, 'Pourquoi fait-on d’abord un titrage rapide ?', 'mcq', '["Pour encadrer le volume équivalent","Pour obtenir le résultat final","Pour étalonner la burette","Pour chauffer la solution"]'::jsonb, 0, 'Le titrage précis se fait ensuite goutte à goutte près de l’équivalence.', 10),
    ('86b39004-4d1e-5f91-8ae8-ed93e221b8e3'::uuid, '1aefef13-8a98-5fab-9984-8b8552174221'::uuid, 'Le vinaigre a été dilué 10 fois et le titrage donne 0,090 mol·L⁻¹. Concentration du vinaigre pur ?', 'mcq', '["9,0 mol·L⁻¹","0,0090 mol·L⁻¹","0,090 mol·L⁻¹","0,90 mol·L⁻¹"]'::jsonb, 3, 'On multiplie par le facteur de dilution : 0,090 × 10.', 11),
    ('573a5ebb-241b-572f-94b8-3558dc14291b'::uuid, '1aefef13-8a98-5fab-9984-8b8552174221'::uuid, 'Dans le titrage par le DCPIP, l’équivalence est repérée…', 'mcq', '["Quand la solution devient rose","Quand la coloration du DCPIP persiste","Par un précipité rouge","Quand la solution bout"]'::jsonb, 1, 'Le réactif titrant sert lui-même d’indicateur.', 12),
    ('ca79408b-f6e3-5066-a4f5-1344d9b2b28b'::uuid, '05357e7a-d210-5659-9681-226b1d787429'::uuid, 'Des mesures très proches les unes des autres sont…', 'mcq', '["Fidèles","Justes","Exactes","Fausses"]'::jsonb, 0, 'La fidélité décrit la faible dispersion ; la justesse, la proximité avec la référence.', 1),
    ('e9d57930-d564-5e3f-85a9-ab8f9599ca92'::uuid, '05357e7a-d210-5659-9681-226b1d787429'::uuid, 'Une erreur systématique dégrade surtout…', 'mcq', '["La justesse","La fidélité","Le nombre de mesures","L’écart-type"]'::jsonb, 0, 'Elle décale toutes les mesures dans le même sens.', 2),
    ('1c97b6a3-2ab3-534f-a857-6358d4ff1f5f'::uuid, '05357e7a-d210-5659-9681-226b1d787429'::uuid, 'L’incertitude-type sur la moyenne de n mesures vaut…', 'mcq', '["s / √n","s × n","s / n²","√s / n"]'::jsonb, 0, 'Répéter les mesures réduit l’incertitude sur la moyenne.', 3),
    ('bf55c091-33d2-5094-a751-5020707687bb'::uuid, '05357e7a-d210-5659-9681-226b1d787429'::uuid, 'Pour une mesure unique avec une tolérance ± Δ, on prend souvent…', 'mcq', '["u = Δ / √3","u = Δ × 3","u = Δ²","u = 0"]'::jsonb, 0, 'C’est une évaluation de type B.', 4),
    ('bcdf9fa5-f685-5da7-82ed-e2ee0e758db6'::uuid, '05357e7a-d210-5659-9681-226b1d787429'::uuid, 'Quatre mesures ont un écart-type de 0,40. Incertitude-type sur la moyenne ?', 'mcq', '["0,20","0,10","1,6","0,40"]'::jsonb, 0, '0,40 / √4 = 0,20.', 5),
    ('e95a0f5c-ca51-5b42-bd1d-2c0ce8b0b205'::uuid, '05357e7a-d210-5659-9681-226b1d787429'::uuid, 'Le z-score vaut 1,5. Le résultat est…', 'mcq', '["Compatible avec la référence","Incompatible","Faux par définition","Impossible à juger"]'::jsonb, 0, 'Un écart inférieur ou égal à deux incertitudes-types est considéré comme compatible.', 6),
    ('8447e398-fc2c-5ec0-bfae-d52c66432f4f'::uuid, '05357e7a-d210-5659-9681-226b1d787429'::uuid, 'Répéter une mesure permet de détecter une erreur systématique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Toutes les mesures sont décalées de la même façon : seule une comparaison à une référence la révèle.', 7),
    ('1d4db9f5-c10b-5309-a83f-75ee5b89262b'::uuid, '05357e7a-d210-5659-9681-226b1d787429'::uuid, 'Combien de chiffres significatifs garde-t-on pour une incertitude-type ?', 'mcq', '["Un ou deux","Au moins cinq","Aucun","Autant que la calculatrice affiche"]'::jsonb, 0, 'On arrondit ensuite la valeur au même rang décimal.', 8),
    ('40486920-216e-5809-903b-791e2c547a65'::uuid, '05357e7a-d210-5659-9681-226b1d787429'::uuid, 'La lecture d’un ménisque est une source d’erreur liée…', 'mcq', '["À l’opérateur","À la méthode","À la température","Au modèle"]'::jsonb, 0, 'Une parallaxe d’observation déplace la lecture.', 9),
    ('3116e65d-2e29-5d8d-bfec-f9027516ef4c'::uuid, '05357e7a-d210-5659-9681-226b1d787429'::uuid, 'x = 12,6 ; x_réf = 12,0 ; u = 0,2. z vaut…', 'mcq', '["3","0,6","1,2","0,3"]'::jsonb, 0, 'z = 0,6 / 0,2 = 3 : le résultat n’est pas compatible, il faut chercher une erreur systématique.', 10),
    ('fb24386f-ad6f-51e9-b14e-9e8b442ebbe4'::uuid, '05357e7a-d210-5659-9681-226b1d787429'::uuid, 'L’évaluation de type A repose sur…', 'mcq', '["L’analyse statistique d’une série de mesures","La notice du constructeur","Une seule mesure","La valeur de référence"]'::jsonb, 0, 'Moyenne et écart-type en sont les outils.', 11),
    ('2983937f-012c-5047-9f2e-d75bcb889966'::uuid, '05357e7a-d210-5659-9681-226b1d787429'::uuid, 'Des impacts groupés mais loin du centre de la cible illustrent des mesures…', 'mcq', '["Fidèles mais pas justes","Justes mais pas fidèles","Justes et fidèles","Ni justes ni fidèles"]'::jsonb, 0, 'Faible dispersion, mais un décalage systématique.', 12),
    ('5cf4cb73-8188-534c-8f66-ddfe51fbdd39'::uuid, 'ff8a4cd8-ba6e-5d33-9d5c-8cbfdeda826f'::uuid, 'Que signifie le sigle CLP ?', 'mcq', '["Classification, labelling and packaging","Chimie, laboratoire, prévention","Contrôle des liquides polluants","Code de lecture des pictogrammes"]'::jsonb, 0, 'C’est le règlement européen d’étiquetage des produits chimiques.', 1),
    ('ba5261ce-3c83-5655-9e94-643dd72ff4e7'::uuid, 'ff8a4cd8-ba6e-5d33-9d5c-8cbfdeda826f'::uuid, 'Les phrases H décrivent…', 'mcq', '["La nature du danger","Les conseils de prudence","Le prix du produit","La formule chimique"]'::jsonb, 0, 'H comme hazard ; les phrases P donnent les précautions.', 2),
    ('29b6a6f5-0831-5c78-b34e-63508c9edc37'::uuid, 'ff8a4cd8-ba6e-5d33-9d5c-8cbfdeda826f'::uuid, 'Le pictogramme flamme sur un cercle signale un produit…', 'mcq', '["Comburant","Inflammable","Explosif","Toxique"]'::jsonb, 0, 'Un comburant entretient la combustion d’un autre produit.', 3),
    ('2691f29e-6098-5786-ad76-dd6a05fcc796'::uuid, 'ff8a4cd8-ba6e-5d33-9d5c-8cbfdeda826f'::uuid, 'Quelle mention d’avertissement signale les dangers les plus graves ?', 'mcq', '["Danger","Attention","Prudence","Toxique"]'::jsonb, 0, 'Le CLP n’en connaît que deux : « Danger » et « Attention ».', 4),
    ('39b371ed-4ca5-5504-8be4-adaa591bafd2'::uuid, 'ff8a4cd8-ba6e-5d33-9d5c-8cbfdeda826f'::uuid, 'La silhouette avec une étoile sur la poitrine indique…', 'mcq', '["Un danger grave pour la santé (cancérogène, mutagène…)","Un produit inflammable","Un gaz sous pression","Un produit irritant léger"]'::jsonb, 0, 'Ces effets peuvent apparaître à long terme.', 5),
    ('effaf49f-9252-57cb-b373-427868e1ac34'::uuid, 'ff8a4cd8-ba6e-5d33-9d5c-8cbfdeda826f'::uuid, 'Où trouve-t-on les mesures de premiers secours pour un produit ?', 'mcq', '["Dans sa fiche de données de sécurité","Uniquement sur le pictogramme","Dans le cahier de laboratoire","Nulle part"]'::jsonb, 0, 'La FDS compte 16 rubriques, dont les premiers secours.', 6),
    ('39976cad-9370-5e33-969a-006a221b188a'::uuid, 'ff8a4cd8-ba6e-5d33-9d5c-8cbfdeda826f'::uuid, 'On peut stocker un acide concentré à côté d’une base concentrée.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On stocke par familles compatibles pour éviter toute réaction en cas de fuite.', 7),
    ('7299fe4d-c4b3-5e7b-beca-487873579e11'::uuid, 'ff8a4cd8-ba6e-5d33-9d5c-8cbfdeda826f'::uuid, 'Un produit volatil et toxique se manipule…', 'mcq', '["Sous la hotte","Sur la paillasse, fenêtre ouverte","Près du bec Bunsen","Dans le couloir"]'::jsonb, 0, 'La hotte aspire et évacue les vapeurs.', 8),
    ('32a089a4-ba16-5ead-a5a7-c3c63d40ca0f'::uuid, 'ff8a4cd8-ba6e-5d33-9d5c-8cbfdeda826f'::uuid, 'P280 demande de…', 'mcq', '["Porter des gants et une protection des yeux","Tenir loin des flammes","Stocker au froid","Jeter à l’évier"]'::jsonb, 0, 'C’est l’un des conseils de prudence les plus courants.', 9),
    ('cabc4abc-2cc4-5b7e-ac65-bfdbc5976b98'::uuid, 'ff8a4cd8-ba6e-5d33-9d5c-8cbfdeda826f'::uuid, 'Pourquoi ne jamais mélanger acide chlorhydrique et eau de Javel ?', 'mcq', '["Il se dégage du dichlore toxique","Le mélange devient neutre","Il se forme du sel inoffensif","La solution gèle"]'::jsonb, 0, 'Le dichlore est un gaz très toxique pour les voies respiratoires.', 10),
    ('3cd10819-b230-56b3-a70e-f4256de6a911'::uuid, 'ff8a4cd8-ba6e-5d33-9d5c-8cbfdeda826f'::uuid, 'Le pictogramme arbre et poisson signale…', 'mcq', '["Un danger pour le milieu aquatique","Un produit naturel","Un produit biodégradable","Un gaz sous pression"]'::jsonb, 0, 'Ces produits ne doivent jamais être jetés à l’évier.', 11),
    ('111c9e4f-7aba-59b4-9c52-5936b68d01d1'::uuid, 'ff8a4cd8-ba6e-5d33-9d5c-8cbfdeda826f'::uuid, 'Quand faut-il lire la FDS ?', 'mcq', '["Avant la manipulation","Après un accident seulement","À la fin de l’année","Jamais au lycée"]'::jsonb, 0, 'Elle sert à prévoir les protections et la conduite à tenir.', 12),
    ('98642337-e2de-5a62-a97e-13e089146696'::uuid, '4ded8770-cc86-5558-ab76-0c57737c9867'::uuid, 'Le premier principe de la chimie verte est…', 'mcq', '["Prévenir les déchets plutôt que les traiter","Maximiser le rendement à tout prix","Travailler à haute température","Utiliser le plus de solvant possible"]'::jsonb, 0, 'Le déchet le moins polluant est celui qu’on ne produit pas.', 1),
    ('2c8014e6-aa51-5cb2-80aa-95a7f8f49422'::uuid, '4ded8770-cc86-5558-ab76-0c57737c9867'::uuid, 'Une économie d’atomes de 100 % signifie…', 'mcq', '["Que tous les atomes des réactifs se retrouvent dans le produit","Que le rendement est de 100 %","Que la réaction est rapide","Qu’il n’y a pas de catalyseur"]'::jsonb, 0, 'C’est le cas des réactions d’addition.', 2),
    ('57755cb4-178e-5dc4-b504-7d262e55e390'::uuid, '4ded8770-cc86-5558-ab76-0c57737c9867'::uuid, 'Quel solvant est le plus conforme à la chimie verte ?', 'mcq', '["L’eau","Le dichlorométhane","Le benzène","Le tétrachlorométhane"]'::jsonb, 0, 'Elle n’est ni toxique ni inflammable.', 3),
    ('35727276-19b7-52de-9b3c-a0cf927ef8b3'::uuid, '4ded8770-cc86-5558-ab76-0c57737c9867'::uuid, 'Pourquoi préfère-t-on un catalyseur à un réactif en excès ?', 'mcq', '["Il n’est pas consommé et réduit les déchets","Il augmente la masse de produit","Il est toujours gratuit","Il supprime tous les dangers"]'::jsonb, 0, 'Utilisé en petite quantité, il est régénéré en fin de réaction.', 4),
    ('8fce947e-7c63-539b-9102-7870ac3a9e21'::uuid, '4ded8770-cc86-5558-ab76-0c57737c9867'::uuid, 'Un rendement élevé suffit à qualifier un procédé de « vert ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il faut aussi regarder l’économie d’atomes, les solvants, l’énergie et la toxicité.', 5),
    ('f8c7caf4-b133-5187-9994-ec4ee3b36de9'::uuid, '4ded8770-cc86-5558-ab76-0c57737c9867'::uuid, 'Comment récupère-t-on un solvant usagé ?', 'mcq', '["Par distillation","Par filtration simple","En le jetant à l’évier","Par chromatographie"]'::jsonb, 0, 'On sépare le solvant, plus volatil, de ce qui y est dissous.', 6),
    ('65f60389-deb1-521f-8ba0-b4d4abbb0f3e'::uuid, '4ded8770-cc86-5558-ab76-0c57737c9867'::uuid, 'Utiliser la biomasse plutôt que le pétrole correspond au principe…', 'mcq', '["Des matières premières renouvelables","De l’économie d’atomes","De la catalyse","De l’analyse en temps réel"]'::jsonb, 0, 'Le pétrole est une ressource épuisable.', 7),
    ('64e41509-0d36-5997-b96a-6fd0061c822c'::uuid, '4ded8770-cc86-5558-ab76-0c57737c9867'::uuid, 'Travailler à température et pression ambiantes permet surtout…', 'mcq', '["D’économiser de l’énergie","D’augmenter les déchets","De ralentir la réaction","D’éviter la catalyse"]'::jsonb, 0, 'Chauffer et comprimer coûtent de l’énergie.', 8),
    ('0440ef41-4ed4-5193-b040-c70dd61bd762'::uuid, '4ded8770-cc86-5558-ab76-0c57737c9867'::uuid, 'Les trois plans d’évaluation d’un procédé sont…', 'mcq', '["Environnemental, économique et social","Chimique, physique et biologique","Rapide, lent et moyen","Solide, liquide et gazeux"]'::jsonb, 0, 'Ce sont les trois piliers du développement durable.', 9),
    ('28cdc57e-3e38-5a04-96f3-d0329cbe0584'::uuid, '4ded8770-cc86-5558-ab76-0c57737c9867'::uuid, 'Pourquoi la nouvelle synthèse de l’ibuprofène est-elle plus verte ?', 'mcq', '["Moins d’étapes, catalytiques, avec une meilleure économie d’atomes","Elle utilise plus de solvants","Elle produit plus de sous-produits","Elle se fait à plus haute température"]'::jsonb, 0, 'Trois étapes au lieu de six et beaucoup moins de déchets.', 10),
    ('3e3b1a43-2680-5ef4-972c-c22d31aff50b'::uuid, '4ded8770-cc86-5558-ab76-0c57737c9867'::uuid, 'Un produit conçu pour se dégrader sans persister dans l’environnement répond au principe…', 'mcq', '["De dégradabilité","D’économie d’atomes","De catalyse","De prévention des accidents"]'::jsonb, 0, 'Il ne s’accumule pas dans les milieux naturels.', 11),
    ('a9793b01-6689-5288-934f-4838b0d79077'::uuid, '4ded8770-cc86-5558-ab76-0c57737c9867'::uuid, 'Les déchets chimiques du laboratoire sont…', 'mcq', '["Triés par familles dans des bidons étiquetés","Jetés ensemble à l’évier","Mélangés dans un seul bidon","Brûlés sur place"]'::jsonb, 0, 'Ils sont ensuite confiés à une entreprise spécialisée.', 12),
    ('24cc0360-2872-5e8c-87fb-eca62f3adfeb'::uuid, 'dc921008-eb18-555a-b7dc-e20a515e1d7c'::uuid, 'À quoi sert le réfrigérant d’un montage à reflux ?', 'mcq', '["À condenser les vapeurs qui retombent dans le ballon","À refroidir le ballon","À peser les réactifs","À filtrer le mélange"]'::jsonb, 0, 'On chauffe longtemps sans perdre de matière.', 1),
    ('411f593c-3d4e-5c31-b2f5-e39821b6f321'::uuid, 'dc921008-eb18-555a-b7dc-e20a515e1d7c'::uuid, 'Dans un réfrigérant, l’eau entre…', 'mcq', '["Par le bas","Par le haut","Par le côté du ballon","N’importe où"]'::jsonb, 0, 'Le réfrigérant reste ainsi entièrement rempli d’eau froide.', 2),
    ('70af5d55-216a-55ab-92d8-f9203d655189'::uuid, 'dc921008-eb18-555a-b7dc-e20a515e1d7c'::uuid, 'Un solvant extracteur doit être…', 'mcq', '["Non miscible avec l’eau et bon solvant du produit","Miscible avec l’eau","Le plus dense possible","Le plus toxique possible"]'::jsonb, 0, 'Deux phases doivent se former et le produit doit passer dans la phase organique.', 3),
    ('85dff975-de79-5ba9-a349-2f00be79a6a1'::uuid, 'dc921008-eb18-555a-b7dc-e20a515e1d7c'::uuid, 'Dans une ampoule à décanter, la phase inférieure est…', 'mcq', '["La plus dense","La moins dense","Toujours l’eau","Toujours la phase organique"]'::jsonb, 0, 'Il faut comparer les densités, qui changent d’un solvant à l’autre.', 4),
    ('0879a899-0732-5f08-8a7c-0487eaaaaca4'::uuid, 'dc921008-eb18-555a-b7dc-e20a515e1d7c'::uuid, 'La recristallisation sert à purifier…', 'mcq', '["Un solide","Un gaz","Un liquide volatil","Une solution aqueuse diluée"]'::jsonb, 0, 'Les impuretés restent dissoutes dans le solvant froid.', 5),
    ('ba3979dc-f7c8-5343-bb5c-d6530dda3de1'::uuid, 'dc921008-eb18-555a-b7dc-e20a515e1d7c'::uuid, 'Le solvant de recristallisation dissout le produit…', 'mcq', '["Beaucoup à chaud, peu à froid","Peu à chaud, beaucoup à froid","Autant à chaud qu’à froid","Pas du tout"]'::jsonb, 0, 'C’est ce qui permet au produit de cristalliser en refroidissant.', 6),
    ('0f3f7495-cd65-5356-a4a7-7ab257858c35'::uuid, 'dc921008-eb18-555a-b7dc-e20a515e1d7c'::uuid, 'La distillation simple sépare des liquides de températures d’ébullition très différentes.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le plus volatil passe en premier dans le réfrigérant.', 7),
    ('3f18574a-d3f2-5b91-816d-7da9716af105'::uuid, 'dc921008-eb18-555a-b7dc-e20a515e1d7c'::uuid, 'Pourquoi ajoute-t-on des grains de pierre ponce dans le ballon ?', 'mcq', '["Pour régulariser l’ébullition","Pour catalyser la réaction","Pour colorer le mélange","Pour sécher le produit"]'::jsonb, 0, 'Ils évitent les ébullitions brutales (soubresauts).', 8),
    ('dc75cac3-51f4-5530-bb2c-303cb8b223a5'::uuid, 'dc921008-eb18-555a-b7dc-e20a515e1d7c'::uuid, 'L’ajout d’eau salée pour séparer un ester s’appelle…', 'mcq', '["Le relargage","La recristallisation","Le reflux","La distillation"]'::jsonb, 0, 'Le sel diminue la solubilité de l’ester dans la phase aqueuse.', 9),
    ('6ee572dd-8765-56f4-9303-49af157e4320'::uuid, 'dc921008-eb18-555a-b7dc-e20a515e1d7c'::uuid, 'Pourquoi dégaze-t-on l’ampoule pendant l’agitation ?', 'mcq', '["Pour évacuer la surpression des vapeurs ou d’un gaz formé","Pour ajouter de l’air","Pour refroidir","Pour changer de phase"]'::jsonb, 0, 'Sinon, le bouchon peut sauter et projeter le contenu.', 10),
    ('117615a9-6b13-5d9c-8f55-1b6d8b42f562'::uuid, 'dc921008-eb18-555a-b7dc-e20a515e1d7c'::uuid, 'Le sulfate de magnésium anhydre sert à…', 'mcq', '["Sécher une phase organique","Catalyser la réaction","Neutraliser un acide","Colorer une tache"]'::jsonb, 0, 'Il capte les traces d’eau restées dans la phase organique.', 11),
    ('fdc58b52-c347-52d1-afff-9c9b2191491d'::uuid, 'dc921008-eb18-555a-b7dc-e20a515e1d7c'::uuid, 'Pourquoi le chauffe-ballon est-il posé sur un support élévateur ?', 'mcq', '["Pour pouvoir le retirer rapidement","Pour chauffer plus fort","Pour éviter de peser","Pour agiter le mélange"]'::jsonb, 0, 'En cas d’emballement, on arrête le chauffage en l’abaissant.', 12),
    ('ec190d7e-f099-5ebf-ae3a-19772ec67722'::uuid, 'd522ed4c-0aaa-5ee8-babf-16ce111c9d24'::uuid, 'Un solide impur fond…', 'mcq', '["À une température plus basse et sur un intervalle","À une température plus haute","Exactement à la température tabulée","Jamais"]'::jsonb, 0, 'Les impuretés abaissent la température de fusion.', 1),
    ('48a87104-f852-5b95-a145-a20a8fafe56a'::uuid, 'd522ed4c-0aaa-5ee8-babf-16ce111c9d24'::uuid, 'Sur une CCM, un produit pur donne…', 'mcq', '["Une seule tache au niveau de la référence","Plusieurs taches","Aucune tache","Une tache au niveau du réactif"]'::jsonb, 0, 'Une deuxième tache révèle une impureté ou un réactif restant.', 2),
    ('11283271-a5e1-5199-bbf9-a6299788519c'::uuid, 'd522ed4c-0aaa-5ee8-babf-16ce111c9d24'::uuid, 'Le réactif limitant est…', 'mcq', '["Celui qui est entièrement consommé en premier","Celui en plus grande quantité","Le catalyseur","Le solvant"]'::jsonb, 0, 'Il fixe l’avancement maximal.', 3),
    ('8924f46b-d419-5617-b6f0-4c8e30c24a92'::uuid, 'd522ed4c-0aaa-5ee8-babf-16ce111c9d24'::uuid, 'Quantité de matière d’un liquide de masse volumique ρ, volume V, masse molaire M ?', 'mcq', '["n = ρ × V / M","n = M / (ρ × V)","n = ρ × M / V","n = V / (ρ × M)"]'::jsonb, 0, 'ρ × V donne la masse, qu’on divise par M.', 4),
    ('37a87748-54f2-5ad5-85e0-df7f73be75ba'::uuid, 'd522ed4c-0aaa-5ee8-babf-16ce111c9d24'::uuid, '0,10 mol de A réagit avec 0,30 mol de B (A + B → C). Quantité maximale de C ?', 'mcq', '["0,10 mol","0,30 mol","0,40 mol","0,20 mol"]'::jsonb, 0, 'A est limitant : x_max = 0,10 mol.', 5),
    ('10eef8b0-e9f0-5e35-8d19-c9d084c6c303'::uuid, 'd522ed4c-0aaa-5ee8-babf-16ce111c9d24'::uuid, 'On attend 20 g de produit et on en obtient 15 g. Rendement ?', 'mcq', '["75 %","133 %","25 %","15 %"]'::jsonb, 0, 'η = 15 / 20 = 0,75.', 6),
    ('049fe8e5-7715-5270-ad2d-79ae569e5ebb'::uuid, 'd522ed4c-0aaa-5ee8-babf-16ce111c9d24'::uuid, 'Un rendement peut dépasser 100 % si le produit est très pur.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Un rendement supérieur à 100 % trahit un produit humide ou impur.', 7),
    ('7f6915b9-d321-5ea9-843e-907498e76179'::uuid, 'd522ed4c-0aaa-5ee8-babf-16ce111c9d24'::uuid, 'Quel appareil mesure la température de fusion d’un solide ?', 'mcq', '["Le banc Kofler","La burette","Le spectrophotomètre","Le pH-mètre"]'::jsonb, 0, 'On y dépose le solide le long d’un gradient de température.', 8),
    ('84245a4e-d076-5245-b67a-553e02ee9762'::uuid, 'd522ed4c-0aaa-5ee8-babf-16ce111c9d24'::uuid, 'Pourquoi utilise-t-on souvent un réactif en excès ?', 'mcq', '["Pour consommer totalement l’autre réactif et améliorer le rendement","Pour ralentir la réaction","Pour diminuer la masse de produit","Pour éviter de purifier"]'::jsonb, 0, 'On choisit en excès le réactif le moins cher ou le plus facile à éliminer.', 9),
    ('a5b6e10c-c692-572b-a8de-12cad1520384'::uuid, 'd522ed4c-0aaa-5ee8-babf-16ce111c9d24'::uuid, 'Pourquoi le rendement est-il toujours inférieur à 100 % en pratique ?', 'mcq', '["Pertes lors des transferts et purifications, réaction parfois limitée","Parce que la masse ne se conserve pas","À cause de la pierre ponce","Parce que le catalyseur est consommé"]'::jsonb, 0, 'Chaque étape fait perdre un peu de produit.', 10),
    ('6dfabc48-f4e0-592d-a2d7-f5973b855e77'::uuid, 'd522ed4c-0aaa-5ee8-babf-16ce111c9d24'::uuid, 'Sur une CCM, une tache du produit au niveau du réactif de départ indique…', 'mcq', '["Qu’il reste du réactif non transformé","Que la synthèse est parfaite","Que le produit est un autre isomère","Que l’éluant est mauvais"]'::jsonb, 0, 'La transformation n’est pas complète ou la purification insuffisante.', 11),
    ('0a032657-a13e-5548-aa29-d889f4f6000c'::uuid, 'd522ed4c-0aaa-5ee8-babf-16ce111c9d24'::uuid, 'm_max = 26 g et m obtenu = 13 g : le rendement vaut…', 'mcq', '["50 %","200 %","13 %","26 %"]'::jsonb, 0, '13 / 26 = 0,50.', 12),
    ('68a96fcc-497b-5a99-80ed-bede7ec89a4c'::uuid, 'd2feee86-27d3-5090-af4f-9a912fe433e3'::uuid, 'CH₂=CH₂ + H₂ → CH₃–CH₃ est une réaction…', 'mcq', '["D’addition","De substitution","D’élimination","Acide-base"]'::jsonb, 0, 'La double liaison disparaît, deux molécules s’unissent.', 1),
    ('1a950c0d-e3b2-5097-baee-9dd52be4b43f'::uuid, 'd2feee86-27d3-5090-af4f-9a912fe433e3'::uuid, 'La déshydratation d’un alcool en alcène est une…', 'mcq', '["Élimination","Addition","Substitution","Réaction acide-base"]'::jsonb, 0, 'Une molécule d’eau est perdue et une double liaison se forme.', 2),
    ('121bd81b-4e40-5479-81fd-5e2d9dcc5c23'::uuid, 'd2feee86-27d3-5090-af4f-9a912fe433e3'::uuid, 'Un site nucléophile est…', 'mcq', '["Riche en électrons","Pauvre en électrons","Toujours un atome d’hydrogène","Toujours chargé positivement"]'::jsonb, 0, 'Il possède un doublet disponible ou une charge négative.', 3),
    ('c277a7ff-73c7-55ce-8ebc-99225a7400f1'::uuid, 'd2feee86-27d3-5090-af4f-9a912fe433e3'::uuid, 'Dans R–Cl, le carbone lié au chlore est…', 'mcq', '["Un site électrophile (δ+)","Un site nucléophile (δ−)","Neutre","Un hydrogène labile"]'::jsonb, 0, 'Le chlore, plus électronégatif, attire les électrons de la liaison.', 4),
    ('a96ec401-c049-58ee-a3a4-938fd4919888'::uuid, 'd2feee86-27d3-5090-af4f-9a912fe433e3'::uuid, 'Une flèche courbe part toujours…', 'mcq', '["D’un doublet d’électrons","D’un atome d’hydrogène","D’une charge positive","Du produit"]'::jsonb, 0, 'Elle représente le déplacement d’un doublet vers un site électrophile.', 5),
    ('1845b56a-3216-54cb-8f82-a22d72bfc8d5'::uuid, 'd2feee86-27d3-5090-af4f-9a912fe433e3'::uuid, 'Quel hydrogène d’un alcool est labile ?', 'mcq', '["Celui lié à l’oxygène","Ceux liés au carbone","Tous","Aucun"]'::jsonb, 0, 'La liaison O–H est polarisée : une base forte peut arracher H⁺.', 6),
    ('4c420179-a33b-5e6f-b830-d1b9ff682af0'::uuid, 'd2feee86-27d3-5090-af4f-9a912fe433e3'::uuid, 'L’hydrogénation d’une cétone donne…', 'mcq', '["Un alcool secondaire","Un alcool primaire","Un acide carboxylique","Un alcène"]'::jsonb, 0, 'La propanone donne le propan-2-ol.', 7),
    ('b2129627-6d99-5574-80c7-c9cccc5c2969'::uuid, 'd2feee86-27d3-5090-af4f-9a912fe433e3'::uuid, 'L’hydrogénation du propanal donne…', 'mcq', '["Le propan-1-ol","Le propan-2-ol","La propanone","L’acide propanoïque"]'::jsonb, 0, 'Un aldéhyde donne un alcool primaire.', 8),
    ('f31cfe4f-c14b-5bb6-ab8f-2cd6345b6b7b'::uuid, 'd2feee86-27d3-5090-af4f-9a912fe433e3'::uuid, 'R–OH + HO⁻ → R–O⁻ + H₂O est une réaction…', 'mcq', '["Acide-base","D’addition","D’élimination","De substitution"]'::jsonb, 0, 'Un ion H⁺ est transféré de l’alcool à l’ion hydroxyde.', 9),
    ('1e3114b4-05b2-5209-9e87-5689b635d750'::uuid, 'd2feee86-27d3-5090-af4f-9a912fe433e3'::uuid, 'L’oxygène est plus électronégatif que le carbone.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Dans C–O ou C=O, l’oxygène porte donc une charge partielle δ−.', 10),
    ('712e7d2c-c892-5ee6-921c-0a69254f1653'::uuid, 'd2feee86-27d3-5090-af4f-9a912fe433e3'::uuid, 'Remplacer Cl par OH sur une chaîne carbonée est une réaction…', 'mcq', '["De substitution","D’addition","D’élimination","D’hydrogénation"]'::jsonb, 0, 'Un groupe en remplace un autre.', 11),
    ('fcbc4b6b-1dc0-5d7b-89f8-fdb12bf1ed18'::uuid, 'd2feee86-27d3-5090-af4f-9a912fe433e3'::uuid, 'Pour hydrogéner un alcène, on utilise souvent un catalyseur…', 'mcq', '["Métallique, comme le nickel ou le palladium","Enzymatique","Acide fort","Aucun"]'::jsonb, 0, 'Sans catalyseur, la réaction serait extrêmement lente.', 12),
    ('40862edf-ee75-59a1-b00a-b90f61182e00'::uuid, '362be49a-19a7-5c6e-bc9f-b7e032742681'::uuid, 'Le nitrate d’argent révèle les ions chlorure par…', 'mcq', '["Un précipité blanc qui noircit à la lumière","Un précipité bleu","Une coloration rose","Un dégagement gazeux"]'::jsonb, 0, 'Il se forme du chlorure d’argent.', 1),
    ('2b043b16-1b60-5b46-9d81-2a6c36d8f219'::uuid, '362be49a-19a7-5c6e-bc9f-b7e032742681'::uuid, 'Avec la soude, les ions Cu²⁺ donnent un précipité…', 'mcq', '["Bleu","Vert","Rouille","Blanc"]'::jsonb, 0, 'C’est l’hydroxyde de cuivre(II).', 2),
    ('6c33ce22-6583-5d7d-9d06-01a12f67e2f2'::uuid, '362be49a-19a7-5c6e-bc9f-b7e032742681'::uuid, 'La spectroscopie infrarouge renseigne sur…', 'mcq', '["Les liaisons et groupes caractéristiques","La masse de la molécule","La couleur uniquement","La température de fusion"]'::jsonb, 0, 'Chaque type de liaison vibre à des nombres d’onde caractéristiques.', 3),
    ('e3bfc64f-516b-558f-a56a-2bc5b21bdef8'::uuid, '362be49a-19a7-5c6e-bc9f-b7e032742681'::uuid, 'Une bande intense et fine vers 1 700 cm⁻¹ signale…', 'mcq', '["Une liaison C=O","Une liaison O–H","Une liaison C–H","Une liaison N–H"]'::jsonb, 0, 'C’est la bande la plus facile à repérer sur un spectre IR.', 4),
    ('90c6700f-866e-57f9-bf4f-4451618dde40'::uuid, '362be49a-19a7-5c6e-bc9f-b7e032742681'::uuid, 'Une bande large vers 3 300 cm⁻¹ évoque…', 'mcq', '["Le O–H d’un alcool","Une liaison C=O","Une liaison C=C","Aucune liaison"]'::jsonb, 0, 'Les liaisons hydrogène élargissent la bande.', 5),
    ('e5f03a22-e30e-5163-8805-75a631fa2025'::uuid, '362be49a-19a7-5c6e-bc9f-b7e032742681'::uuid, 'Une molécule qui absorbe le rouge paraît…', 'mcq', '["Bleu-vert","Rouge","Jaune","Blanche"]'::jsonb, 0, 'On perçoit la couleur complémentaire de celle absorbée.', 6),
    ('bc8d6a8c-ea50-519d-8a41-38050446dd66'::uuid, '362be49a-19a7-5c6e-bc9f-b7e032742681'::uuid, 'Le nombre d’onde σ est égal à…', 'mcq', '["1 / λ","λ × c","c / λ","λ²"]'::jsonb, 0, 'Il s’exprime usuellement en cm⁻¹.', 7),
    ('253de667-fffb-527c-a8de-8dbcedd3513c'::uuid, '362be49a-19a7-5c6e-bc9f-b7e032742681'::uuid, 'Plus une molécule a de doubles liaisons conjuguées, plus elle absorbe à grande longueur d’onde.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est pourquoi les pigments très conjugués comme le carotène sont colorés.', 8),
    ('dfb20400-00a9-565e-9935-09a3b79c3458'::uuid, '362be49a-19a7-5c6e-bc9f-b7e032742681'::uuid, 'Une bande à 1 740 cm⁻¹ sans bande O–H évoque…', 'mcq', '["Un ester","Un alcool","Un acide carboxylique","Une amine"]'::jsonb, 0, 'C=O présent, mais pas de O–H.', 9),
    ('12a5932c-66de-5ce0-aaa3-34d28657ea30'::uuid, '362be49a-19a7-5c6e-bc9f-b7e032742681'::uuid, 'La spectroscopie UV-visible excite surtout…', 'mcq', '["Les électrons des molécules","Les noyaux atomiques","Les vibrations des liaisons","Les molécules d’air"]'::jsonb, 0, 'L’infrarouge, lui, excite les vibrations.', 10),
    ('a39986bb-3c96-5ced-a367-9e151989f6f2'::uuid, '362be49a-19a7-5c6e-bc9f-b7e032742681'::uuid, 'Avec la soude, les ions Fe³⁺ donnent un précipité…', 'mcq', '["Rouille","Vert","Bleu","Blanc"]'::jsonb, 0, 'C’est l’hydroxyde de fer(III).', 11),
    ('023ddf00-0eea-57a3-a15b-34f4bba9ee36'::uuid, '362be49a-19a7-5c6e-bc9f-b7e032742681'::uuid, 'Dans un test d’identification, le témoin sert à…', 'mcq', '["Comparer le résultat à une référence connue","Accélérer la réaction","Colorer la solution","Remplacer l’échantillon"]'::jsonb, 0, 'Il montre ce qu’on observe avec et sans l’espèce recherchée.', 12),
    ('a1dd720a-57b9-554d-b198-14a7f5d1a90c'::uuid, 'e7dc8410-761a-59d8-a095-ec3aaa224d53'::uuid, 'Dans un dosage par étalonnage, l’espèce dosée est…', 'mcq', '["Non consommée","Entièrement consommée","Transformée en précipité","Chauffée"]'::jsonb, 0, 'On compare une propriété (absorbance, conductivité) à celles d’étalons.', 1),
    ('ec6c8ff7-a96f-5035-8857-61accd7d4f5b'::uuid, 'e7dc8410-761a-59d8-a095-ec3aaa224d53'::uuid, 'A = 0,60 et k = 1 500 L·mol⁻¹. Concentration ?', 'mcq', '["4,0 × 10⁻⁴ mol·L⁻¹","9,0 × 10² mol·L⁻¹","2,5 × 10³ mol·L⁻¹","0,60 mol·L⁻¹"]'::jsonb, 0, 'c = A / k = 0,60 / 1 500.', 2),
    ('ba033c7d-d714-55f0-a2a8-03cec760719d'::uuid, 'e7dc8410-761a-59d8-a095-ec3aaa224d53'::uuid, 'La réaction support d’un titrage doit être…', 'mcq', '["Totale, rapide et unique","Lente et partielle","Réversible et lente","Toujours acido-basique"]'::jsonb, 0, 'Sinon, le volume équivalent ne correspondrait pas à la quantité réelle.', 3),
    ('6145148c-0d8f-5c03-b110-c5d5e80aefc8'::uuid, 'e7dc8410-761a-59d8-a095-ec3aaa224d53'::uuid, 'À l’équivalence…', 'mcq', '["Les réactifs sont dans les proportions stœchiométriques","La burette est vide","Le pH vaut 7 dans tous les cas","L’espèce titrée est en excès"]'::jsonb, 0, 'Il y a changement de réactif limitant.', 4),
    ('4957e2c0-51df-51e7-8531-9f23427f9c69'::uuid, 'e7dc8410-761a-59d8-a095-ec3aaa224d53'::uuid, 'Pour A + B → produits, C_A = 0,10 mol·L⁻¹, V_A = 10,0 mL, C_B = 0,050 mol·L⁻¹. V_E ?', 'mcq', '["20,0 mL","5,0 mL","10,0 mL","50,0 mL"]'::jsonb, 0, 'C_A × V_A = C_B × V_E, donc V_E = 0,10 × 10,0 / 0,050.', 5),
    ('2b22e5cc-b3b2-58e5-a99b-9a7028d2b7c5'::uuid, 'e7dc8410-761a-59d8-a095-ec3aaa224d53'::uuid, 'Sur une courbe de titrage pH-métrique, l’équivalence se repère…', 'mcq', '["Au saut de pH, par la méthode des tangentes ou la dérivée","Au début de la courbe","Quand le pH vaut 0","Au minimum de la dérivée"]'::jsonb, 0, 'Le maximum de dpH/dV donne V_E.', 6),
    ('bb247ea2-de6d-5b8c-a7ad-5e088bca7834'::uuid, 'e7dc8410-761a-59d8-a095-ec3aaa224d53'::uuid, 'Avant l’équivalence, le réactif limitant est…', 'mcq', '["Le réactif titrant versé","L’espèce titrée","Le solvant","L’indicateur"]'::jsonb, 0, 'Il est consommé dès qu’il est versé.', 7),
    ('99cb6429-eb6a-55c8-90cf-fa70928ad2e6'::uuid, 'e7dc8410-761a-59d8-a095-ec3aaa224d53'::uuid, 'Le permanganate peut servir d’indicateur de fin de titrage à lui seul.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Sa couleur violette persiste dès qu’il est en excès.', 8),
    ('d32ab389-a9fd-56d7-85f9-f9b5a05ecc4b'::uuid, 'e7dc8410-761a-59d8-a095-ec3aaa224d53'::uuid, 'MnO₄⁻ + 5 Fe²⁺ → … : à l’équivalence, n(Fe²⁺) vaut…', 'mcq', '["5 × n(MnO₄⁻ versé)","n(MnO₄⁻ versé) / 5","n(MnO₄⁻ versé)","8 × n(MnO₄⁻ versé)"]'::jsonb, 0, 'On respecte les coefficients stœchiométriques.', 9),
    ('dffa2da5-39f5-5a28-bcc6-52bed74b5ba7'::uuid, 'e7dc8410-761a-59d8-a095-ec3aaa224d53'::uuid, 'La loi de Beer-Lambert n’est valable que…', 'mcq', '["Pour des solutions assez diluées","Pour des solutions très concentrées","Pour les solides","En l’absence de lumière"]'::jsonb, 0, 'Aux fortes absorbances, la proportionnalité se perd.', 10),
    ('f7ae198e-63b2-5697-9fbc-08e398bb72be'::uuid, 'e7dc8410-761a-59d8-a095-ec3aaa224d53'::uuid, 'Un indicateur coloré de fin de titrage est bien choisi si…', 'mcq', '["Son changement de couleur se produit dans la zone de l’équivalence","Il est rouge","Il est ajouté en grande quantité","Il réagit avec le titrant avant l’équivalence"]'::jsonb, 0, 'Sa zone de virage doit contenir le pH à l’équivalence.', 11),
    ('34a6cf71-cc40-5ffd-96ed-0ddd1c8f0c5d'::uuid, 'e7dc8410-761a-59d8-a095-ec3aaa224d53'::uuid, 'Quel avantage principal a l’étalonnage spectrophotométrique ?', 'mcq', '["Il convient aux faibles concentrations et n’utilise pas l’espèce","Il ne demande aucun étalon","Il ne nécessite aucune mesure","Il fonctionne sans lumière"]'::jsonb, 0, 'Il suffit que l’espèce absorbe à une longueur d’onde donnée.', 12),
    ('c9729038-f8a2-5a98-8bc5-617f483e7864'::uuid, '7f8b729c-3f36-5b0d-9fc2-5d0f9d7e58be'::uuid, 'Qui fixe la première image photographique durable, en 1826 ?', 'mcq', '["Nicéphore Niépce","Louis Daguerre","Les frères Lumière","Isaac Newton"]'::jsonb, 0, 'Daguerre, son associé, rendra public le daguerréotype en 1839.', 1),
    ('14cab1d2-3de1-592b-9289-99709d7b07c6'::uuid, '7f8b729c-3f36-5b0d-9fc2-5d0f9d7e58be'::uuid, 'Le droit à l’image protège…', 'mcq', '["La personne photographiée","Le photographe seulement","L’appareil photo","Le réseau social"]'::jsonb, 0, 'Le droit d’auteur, lui, protège le créateur de la photo.', 2),
    ('50f9c60d-8289-5982-a36a-efd3c355d311'::uuid, '7f8b729c-3f36-5b0d-9fc2-5d0f9d7e58be'::uuid, 'Dans le modèle de l’œil, le cristallin joue le rôle…', 'mcq', '["D’une lentille convergente","D’un diaphragme","D’un écran","D’un capteur CCD"]'::jsonb, 0, 'L’iris est le diaphragme, la rétine l’écran.', 3),
    ('7bcd4c31-cef4-5d28-a891-8750e1f40228'::uuid, '7f8b729c-3f36-5b0d-9fc2-5d0f9d7e58be'::uuid, 'Chez un myope, l’image se forme…', 'mcq', '["Avant la rétine","Après la rétine","Sur la rétine","Sur l’iris"]'::jsonb, 0, 'L’œil est trop convergent ; on corrige avec une lentille divergente.', 4),
    ('8555fc32-ed18-52c3-9bf7-84bbe96add39'::uuid, '7f8b729c-3f36-5b0d-9fc2-5d0f9d7e58be'::uuid, 'Quelles cellules de la rétine permettent la vision des couleurs ?', 'mcq', '["Les cônes","Les bâtonnets","Les neurones moteurs","Les cellules de l’iris"]'::jsonb, 0, 'Il en existe trois types, sensibles au bleu, au vert et au rouge.', 5),
    ('c67e7b9c-85a3-52c0-bfb5-dff692e4457d'::uuid, '7f8b729c-3f36-5b0d-9fc2-5d0f9d7e58be'::uuid, 'En synthèse additive, rouge + vert donne…', 'mcq', '["Jaune","Magenta","Cyan","Blanc"]'::jsonb, 0, 'L’écran d’un téléphone produit ainsi le jaune.', 6),
    ('d175b109-7152-5dee-812b-0d984300db27'::uuid, '7f8b729c-3f36-5b0d-9fc2-5d0f9d7e58be'::uuid, 'Les couleurs primaires de la synthèse soustractive sont…', 'mcq', '["Cyan, magenta, jaune","Rouge, vert, bleu","Rouge, jaune, bleu","Noir et blanc"]'::jsonb, 0, 'Ce sont les encres des imprimantes.', 7),
    ('22cbe71d-294c-5aa6-93ec-ff2978ec5ca1'::uuid, '7f8b729c-3f36-5b0d-9fc2-5d0f9d7e58be'::uuid, 'Superposer les trois lumières primaires rouge, verte et bleue donne du noir.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On obtient du blanc en synthèse additive ; le noir s’obtient en synthèse soustractive.', 8),
    ('9de8334a-20a6-5947-a78f-ef52b42a982d'::uuid, '7f8b729c-3f36-5b0d-9fc2-5d0f9d7e58be'::uuid, 'Un filtre jaune absorbe…', 'mcq', '["Le bleu","Le rouge","Le vert","Le jaune"]'::jsonb, 0, 'Jaune = rouge + vert : il transmet ces deux couleurs et absorbe le bleu.', 9),
    ('129e2cab-9e93-5313-9b2c-f27cda52f78f'::uuid, '7f8b729c-3f36-5b0d-9fc2-5d0f9d7e58be'::uuid, 'Une tomate rouge éclairée en lumière bleue paraît…', 'mcq', '["Noire","Rouge","Bleue","Blanche"]'::jsonb, 0, 'Elle ne peut diffuser que du rouge, absent de la lumière reçue.', 10),
    ('834767b0-5a95-5738-9d86-022fb1d51c90'::uuid, '7f8b729c-3f36-5b0d-9fc2-5d0f9d7e58be'::uuid, 'Les bâtonnets sont surtout utiles…', 'mcq', '["En faible lumière","Pour voir les couleurs","Pour voir de près","En plein soleil uniquement"]'::jsonb, 0, 'Très sensibles, ils ne distinguent pas les couleurs.', 11),
    ('6d572a08-fc49-5c0c-99c4-103c2d612ae8'::uuid, '7f8b729c-3f36-5b0d-9fc2-5d0f9d7e58be'::uuid, 'On corrige l’hypermétropie avec…', 'mcq', '["Une lentille convergente","Une lentille divergente","Un filtre coloré","Un diaphragme"]'::jsonb, 0, 'L’œil hypermétrope n’est pas assez convergent.', 12),
    ('77ed2189-4b91-5cfe-86b4-29f5c0019237'::uuid, '8c247ffe-a336-591d-bae2-58764bd185a5'::uuid, 'Un rayon parallèle à l’axe optique ressort d’une lentille convergente en passant par…', 'mcq', '["Le foyer image F′","Le centre optique O","Le foyer objet F","L’objet"]'::jsonb, 0, 'C’est la définition du foyer image.', 1),
    ('97684867-878f-53fa-9b0c-0a2c7f146fee'::uuid, '8c247ffe-a336-591d-bae2-58764bd185a5'::uuid, 'Un rayon passant par le centre optique…', 'mcq', '["N’est pas dévié","Ressort parallèle à l’axe","Passe par F′","Est réfléchi"]'::jsonb, 0, 'C’est le rayon le plus simple à tracer.', 2),
    ('4f4e1f29-b790-5737-9f64-303f6583158f'::uuid, '8c247ffe-a336-591d-bae2-58764bd185a5'::uuid, 'Une lentille de distance focale 0,25 m a une vergence de…', 'mcq', '["4 δ","0,25 δ","25 δ","40 δ"]'::jsonb, 0, 'V = 1 / f′ = 1 / 0,25 = 4 dioptries.', 3),
    ('061308e0-699e-5946-a027-dc04988751d5'::uuid, '8c247ffe-a336-591d-bae2-58764bd185a5'::uuid, 'La relation de conjugaison s’écrit…', 'mcq', '["1/OA′ − 1/OA = 1/f′","1/OA′ + 1/OA = f′","OA′ − OA = f′","OA × OA′ = f′"]'::jsonb, 0, 'Avec des mesures algébriques orientées dans le sens de la lumière.', 4),
    ('7bd28480-cc63-51ee-9ed5-c7e6f6b86579'::uuid, '8c247ffe-a336-591d-bae2-58764bd185a5'::uuid, 'Objet à OA = −20 cm, f′ = 10 cm. Où se forme l’image ?', 'mcq', '["OA′ = 20 cm","OA′ = 10 cm","OA′ = −20 cm","OA′ = 5 cm"]'::jsonb, 0, '1/OA′ = 1/10 − 1/20 = 1/20.', 5),
    ('87b77e23-a3f7-5b0f-baef-cc9550d7bb8c'::uuid, '8c247ffe-a336-591d-bae2-58764bd185a5'::uuid, 'Un grandissement γ = −2 signifie une image…', 'mcq', '["Renversée et deux fois plus grande","Droite et deux fois plus grande","Renversée et deux fois plus petite","Droite et deux fois plus petite"]'::jsonb, 0, 'Le signe indique le sens, la valeur absolue la taille.', 6),
    ('fe3808e1-da1e-5c49-9570-d435e05645a8'::uuid, '8c247ffe-a336-591d-bae2-58764bd185a5'::uuid, 'Pour obtenir l’effet loupe, l’objet doit être placé…', 'mcq', '["Entre le foyer objet et la lentille","Très loin de la lentille","Exactement au foyer image","Derrière la lentille"]'::jsonb, 0, 'L’image est alors virtuelle, droite et agrandie.', 7),
    ('b9b50e78-694f-59ce-8879-7c106235a10a'::uuid, '8c247ffe-a336-591d-bae2-58764bd185a5'::uuid, 'Une image virtuelle peut être recueillie sur un écran.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Seule une image réelle se forme sur un écran ; l’image virtuelle est vue à travers la lentille.', 8),
    ('e75101bc-4bb1-5a99-ae9c-bb2563a9e537'::uuid, '8c247ffe-a336-591d-bae2-58764bd185a5'::uuid, 'Le grandissement vaut aussi…', 'mcq', '["OA′ / OA","OA / OA′","OA × OA′","f′ / OA"]'::jsonb, 0, 'γ = A′B′ / AB = OA′ / OA.', 9),
    ('27b35800-b5fb-505b-b524-d01ecd3aa224'::uuid, '8c247ffe-a336-591d-bae2-58764bd185a5'::uuid, 'L’image d’un objet très éloigné se forme…', 'mcq', '["Dans le plan focal image","Au centre optique","Au foyer objet","À l’infini"]'::jsonb, 0, 'Les rayons arrivent parallèles et convergent dans ce plan.', 10),
    ('235faa8a-520e-59b1-873c-1a8df2dd706c'::uuid, '8c247ffe-a336-591d-bae2-58764bd185a5'::uuid, 'Avec un sténopé plus petit, l’image devient…', 'mcq', '["Plus nette mais moins lumineuse","Plus lumineuse et floue","Droite","Virtuelle"]'::jsonb, 0, 'Moins de lumière passe, mais chaque point donne une plus petite tache.', 11),
    ('567b9667-81f9-5f83-8c2b-b14fc2966290'::uuid, '8c247ffe-a336-591d-bae2-58764bd185a5'::uuid, 'Objet à OA = −30 cm, image à OA′ = +15 cm. Le grandissement vaut…', 'mcq', '["−0,5","2","0,5","−2"]'::jsonb, 0, 'γ = 15 / (−30).', 12),
    ('e85524c6-4d22-54b9-a663-1d59a084bca5'::uuid, '7c41161f-c2be-5036-812d-f8a82b7fb84f'::uuid, 'Le nombre d’ouverture N vaut…', 'mcq', '["f′ / D","D / f′","f′ × D","D²"]'::jsonb, 0, 'f′ est la focale, D le diamètre de l’ouverture du diaphragme.', 1),
    ('568657c5-2cd8-5b5f-9428-7b1afbdf20bb'::uuid, '7c41161f-c2be-5036-812d-f8a82b7fb84f'::uuid, 'Focale 100 mm, diamètre d’ouverture 25 mm : N vaut…', 'mcq', '["4","0,25","2 500","125"]'::jsonb, 0, 'N = 100 / 25 = 4, soit f/4.', 2),
    ('eba94195-17f5-5f4a-9832-4ba373eaf2e3'::uuid, '7c41161f-c2be-5036-812d-f8a82b7fb84f'::uuid, 'Un petit nombre d’ouverture (f/2) correspond à…', 'mcq', '["Une grande ouverture, beaucoup de lumière","Une petite ouverture","Un temps de pose long","Une grande profondeur de champ"]'::jsonb, 0, 'N = f′ / D : D grand donne N petit.', 3),
    ('1fbdf1e6-2273-55a7-9830-fcba7141e50f'::uuid, '7c41161f-c2be-5036-812d-f8a82b7fb84f'::uuid, 'Pour augmenter la profondeur de champ, on…', 'mcq', '["Augmente le nombre d’ouverture (on ferme)","Ouvre au maximum","Augmente la focale","Rapproche le sujet"]'::jsonb, 0, 'Un diaphragme fermé étend la zone nette.', 4),
    ('ccbf8e40-4975-597b-958e-c2f1784da8a5'::uuid, '7c41161f-c2be-5036-812d-f8a82b7fb84f'::uuid, 'Un temps de pose court permet surtout…', 'mcq', '["De figer un mouvement","D’augmenter la lumière reçue","D’augmenter la profondeur de champ","De réduire la résolution"]'::jsonb, 0, 'Le sujet n’a pas le temps de bouger pendant l’exposition.', 5),
    ('6c009c75-6ead-5002-8e7a-ec7abfd2be6f'::uuid, '7c41161f-c2be-5036-812d-f8a82b7fb84f'::uuid, 'Quand la focale augmente, l’angle de champ…', 'mcq', '["Diminue","Augmente","Reste constant","Double toujours"]'::jsonb, 0, 'Un téléobjectif cadre serré.', 6),
    ('59e55aaa-406f-5d07-8961-142abad72b14'::uuid, '7c41161f-c2be-5036-812d-f8a82b7fb84f'::uuid, 'On passe de f/4 à f/5,6. Pour garder la même exposition, le temps de pose doit…', 'mcq', '["Doubler","Être divisé par deux","Rester le même","Être multiplié par quatre"]'::jsonb, 0, 'La lumière reçue par seconde est divisée par deux.', 7),
    ('fad72b13-5a2a-5d99-8e56-c0b6f097314c'::uuid, '7c41161f-c2be-5036-812d-f8a82b7fb84f'::uuid, 'Monter la sensibilité ISO augmente le bruit de l’image.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’amplification du signal amplifie aussi le bruit électronique.', 8),
    ('0798e85b-5693-56f2-baad-86a2cbdb3e0e'::uuid, '7c41161f-c2be-5036-812d-f8a82b7fb84f'::uuid, 'La mise au point consiste à…', 'mcq', '["Placer le capteur là où se forme l’image nette","Régler le temps de pose","Changer de sensibilité","Choisir le format du fichier"]'::jsonb, 0, 'Elle dépend de la distance du sujet.', 9),
    ('16f1b28e-151c-598a-9ecb-f48b70be4d3b'::uuid, '7c41161f-c2be-5036-812d-f8a82b7fb84f'::uuid, 'Un capteur de 4 000 × 3 000 pixels compte…', 'mcq', '["12 millions de pixels","7 000 pixels","1,2 million de pixels","120 millions de pixels"]'::jsonb, 0, '4 000 × 3 000 = 12 000 000.', 10),
    ('7fd34642-6a82-5794-841e-e1e133ad9d38'::uuid, '7c41161f-c2be-5036-812d-f8a82b7fb84f'::uuid, 'Pour un portrait à l’arrière-plan flou, on choisit…', 'mcq', '["Une grande ouverture (petit N)","Un petit diaphragme (grand N)","Un grand-angle très court","Un temps de pose très long"]'::jsonb, 0, 'La profondeur de champ est alors faible.', 11),
    ('6a23d48e-3bca-5ad6-af39-dbf550958d21'::uuid, '7c41161f-c2be-5036-812d-f8a82b7fb84f'::uuid, 'Chaque pixel d’un capteur convertit la lumière en…', 'mcq', '["Charge électrique","Chaleur","Son","Pression"]'::jsonb, 0, 'C’est l’effet photoélectrique, avant la numérisation.', 12),
    ('88503080-a7a5-53d1-aee6-22db8bc8c655'::uuid, 'de40c909-dda2-5f04-ac07-3390c614778b'::uuid, 'En codage RVB 24 bits, chaque composante est codée sur…', 'mcq', '["8 bits","24 bits","3 bits","1 bit"]'::jsonb, 0, '3 composantes × 8 bits = 24 bits par pixel.', 1),
    ('4afdfd2a-767e-5c03-950d-710a1760967f'::uuid, 'de40c909-dda2-5f04-ac07-3390c614778b'::uuid, 'Combien de valeurs différentes une composante codée sur 8 bits peut-elle prendre ?', 'mcq', '["256","8","255","1 024"]'::jsonb, 0, '2⁸ = 256 valeurs, de 0 à 255.', 2),
    ('826a706b-beab-561d-893e-9c03ee76a89b'::uuid, 'de40c909-dda2-5f04-ac07-3390c614778b'::uuid, 'Le code RVB (255, 255, 0) correspond à…', 'mcq', '["Jaune","Cyan","Magenta","Blanc"]'::jsonb, 0, 'Rouge + vert en synthèse additive donne jaune.', 3),
    ('35790c6b-8502-5775-a64f-0d056c9da44c'::uuid, 'de40c909-dda2-5f04-ac07-3390c614778b'::uuid, 'Un octet vaut…', 'mcq', '["8 bits","10 bits","1 bit","1 024 bits"]'::jsonb, 0, 'C’est l’unité de base de la mémoire.', 4),
    ('46791f2b-ab10-5e3d-bc72-389d3596dd6c'::uuid, 'de40c909-dda2-5f04-ac07-3390c614778b'::uuid, 'Taille non compressée d’une image de 1 000 × 1 000 pixels en RVB 24 bits ?', 'mcq', '["3 Mo","1 Mo","24 Mo","3 ko"]'::jsonb, 0, '10⁶ pixels × 3 octets = 3 × 10⁶ octets.', 5),
    ('d1c4aec0-32a6-5eec-8d70-0c73f7255cf5'::uuid, 'de40c909-dda2-5f04-ac07-3390c614778b'::uuid, 'Le débit binaire s’exprime en…', 'mcq', '["bit·s⁻¹","octets","hertz","pixels"]'::jsonb, 0, 'C’est le nombre de bits transmis par seconde.', 6),
    ('3538c33c-314b-58d7-905b-a4ea2494a434'::uuid, 'de40c909-dda2-5f04-ac07-3390c614778b'::uuid, 'Un fichier de 10 Mo transmis à 40 Mbit·s⁻¹ met…', 'mcq', '["2 s","0,25 s","4 s","400 s"]'::jsonb, 0, '10 × 10⁶ × 8 = 8 × 10⁷ bits ; 8 × 10⁷ / 4 × 10⁷ = 2 s.', 7),
    ('762a22b1-e63d-5846-a25d-c7a7e2b8c8d4'::uuid, 'de40c909-dda2-5f04-ac07-3390c614778b'::uuid, 'Une image en niveaux de gris sur 8 bits pèse trois fois moins que la même en RVB 24 bits.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '1 octet par pixel au lieu de 3.', 8),
    ('a6821807-6050-5e4c-a5e8-d67f5d9d7ede'::uuid, 'de40c909-dda2-5f04-ac07-3390c614778b'::uuid, 'Combien de couleurs permet le codage RVB 24 bits ?', 'mcq', '["Environ 16,8 millions","256","768","Environ 1 million"]'::jsonb, 0, '256³ ≈ 16 777 216.', 9),
    ('75f9336b-f357-585a-ab00-aae92dd58961'::uuid, 'de40c909-dda2-5f04-ac07-3390c614778b'::uuid, 'Le code (0, 0, 0) correspond au…', 'mcq', '["Noir","Blanc","Gris","Rouge"]'::jsonb, 0, 'Aucune lumière émise.', 10),
    ('5b1fb8fe-c854-5ecb-8d59-db980134dfe7'::uuid, 'de40c909-dda2-5f04-ac07-3390c614778b'::uuid, 'La compression JPEG permet surtout…', 'mcq', '["De réduire la taille du fichier","D’augmenter le nombre de pixels","D’améliorer toujours la qualité","De supprimer les couleurs"]'::jsonb, 0, 'Elle peut entraîner une perte de qualité.', 11),
    ('4f825209-6bd4-5965-bb78-bbd5cf162639'::uuid, 'de40c909-dda2-5f04-ac07-3390c614778b'::uuid, 'La définition d’une image est…', 'mcq', '["Son nombre de pixels","Sa taille imprimée en cm","Son débit","Sa luminosité"]'::jsonb, 0, 'La résolution d’impression, elle, se compte en pixels par pouce.', 12),
    ('92ea9ede-fa75-5567-9ce3-6e4a5f664af6'::uuid, 'b87240bc-9198-52e2-9490-da6031ad0d64'::uuid, 'Le rôle du capteur est de…', 'mcq', '["Convertir la grandeur mesurée en grandeur électrique","Afficher le résultat","Stocker les données","Alimenter le circuit"]'::jsonb, 0, 'C’est le premier maillon de la chaîne de mesure.', 1),
    ('313109d7-d9f7-519b-baa8-146a14818666'::uuid, 'b87240bc-9198-52e2-9490-da6031ad0d64'::uuid, 'Le conditionneur…', 'mcq', '["Transforme le signal du capteur en tension exploitable","Convertit la tension en nombre","Mesure directement la température","Remplace le capteur"]'::jsonb, 0, 'Pont diviseur ou amplificateur sont des conditionneurs typiques.', 2),
    ('a367db8d-adad-5c24-9b13-c1a7601e0088'::uuid, 'b87240bc-9198-52e2-9490-da6031ad0d64'::uuid, 'Que fait un CAN ?', 'mcq', '["Il convertit une tension analogique en nombre binaire","Il amplifie un signal","Il chauffe le capteur","Il filtre la lumière"]'::jsonb, 0, 'Convertisseur analogique-numérique.', 3),
    ('af6f030c-29f3-5341-b302-0243d84b406a'::uuid, 'b87240bc-9198-52e2-9490-da6031ad0d64'::uuid, 'Quantum d’un CAN de 8 bits sur 0 – 5 V ?', 'mcq', '["Environ 19,5 mV","0,625 V","5 mV","1,6 V"]'::jsonb, 0, 'q = 5 / 256 ≈ 0,0195 V.', 4),
    ('ffaf70bb-e2bf-553c-bf82-aab20cca0754'::uuid, 'b87240bc-9198-52e2-9490-da6031ad0d64'::uuid, 'La sensibilité d’un capteur est…', 'mcq', '["La variation de la sortie pour une variation unité de l’entrée","Sa plage de mesure","Son prix","Sa masse"]'::jsonb, 0, 'C’est la pente de la caractéristique de transfert.', 5),
    ('9165e07d-ee34-5a77-9144-be878877da53'::uuid, 'b87240bc-9198-52e2-9490-da6031ad0d64'::uuid, 'Une thermistance CTN a une résistance qui…', 'mcq', '["Diminue quand la température augmente","Augmente quand la température augmente","Ne varie pas","Dépend de la lumière"]'::jsonb, 0, 'CTN : coefficient de température négatif.', 6),
    ('8f1b8ad7-542f-5594-9804-2582fcdf5575'::uuid, 'b87240bc-9198-52e2-9490-da6031ad0d64'::uuid, 'Augmenter le nombre de bits du CAN diminue le quantum.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La plage est découpée en davantage de niveaux.', 7),
    ('edc0b528-b913-522e-9225-f3156eb4121b'::uuid, 'b87240bc-9198-52e2-9490-da6031ad0d64'::uuid, 'Un spectrophotomètre mesure une concentration par…', 'mcq', '["Étalonnage","Lecture directe sur une règle","Pesée","Chronométrage"]'::jsonb, 0, 'Il mesure l’absorbance, reliée à la concentration par des étalons.', 8),
    ('c5a0d6c3-53d4-542e-9c03-434cad166860'::uuid, 'b87240bc-9198-52e2-9490-da6031ad0d64'::uuid, 'Capteur de sensibilité 10 mV·°C⁻¹ ; la tension augmente de 0,25 V. Variation de température ?', 'mcq', '["25 °C","2,5 °C","0,025 °C","250 °C"]'::jsonb, 0, '0,25 V = 250 mV ; 250 / 10 = 25 °C.', 9),
    ('c1a0c85a-1fff-5f9b-bd64-507f71564a37'::uuid, 'b87240bc-9198-52e2-9490-da6031ad0d64'::uuid, 'L’étendue de mesure d’un instrument est…', 'mcq', '["L’intervalle entre ses valeurs minimale et maximale mesurables","Sa plus petite graduation","Sa précision","Son temps de réponse"]'::jsonb, 0, 'Elle fait partie du cahier des charges.', 10),
    ('6f1d3a9f-bc84-5cb6-9a09-b0b4896d60d4'::uuid, 'b87240bc-9198-52e2-9490-da6031ad0d64'::uuid, 'La résolution d’une chaîne de mesure est fixée par…', 'mcq', '["Son maillon le plus grossier","Son maillon le plus fin","L’afficheur seulement","La couleur des fils"]'::jsonb, 0, 'Un excellent CAN ne corrige pas un capteur peu sensible.', 11),
    ('a57acbe4-3ee3-5d32-acdd-d2a413be3efc'::uuid, 'b87240bc-9198-52e2-9490-da6031ad0d64'::uuid, 'Comment établit-on la caractéristique de transfert d’un thermomètre à thermistance ?', 'mcq', '["Par étalonnage avec un thermomètre de référence","En lisant la notice seulement","Par une CCM","Par titrage"]'::jsonb, 0, 'On relève la tension à plusieurs températures connues.', 12),
    ('c6a82a05-b263-533b-9832-88028c941a7f'::uuid, '207f5003-3526-5133-885f-7a4f82dbd0a8'::uuid, 'Une mesure en tout ou rien donne une sortie qui prend…', 'mcq', '["Deux états seulement","Une infinité de valeurs","Trois états","Une valeur en degrés"]'::jsonb, 0, 'Seuil franchi ou non.', 1),
    ('1bdb1bf4-abb7-5ff1-89a5-ddc26e2b0c50'::uuid, '207f5003-3526-5133-885f-7a4f82dbd0a8'::uuid, 'Dans une régulation tout ou rien, si la température est sous la consigne…', 'mcq', '["Le chauffage s’allume","Le chauffage s’éteint","L’alarme sonne toujours","Rien ne se passe"]'::jsonb, 0, 'Il s’éteint quand la température dépasse la consigne.', 2),
    ('b1a9cbc6-ed09-5c7e-b710-9c4f6930126a'::uuid, '207f5003-3526-5133-885f-7a4f82dbd0a8'::uuid, 'Pourquoi la température oscille-t-elle autour de la consigne ?', 'mcq', '["À cause de l’inertie du système","Parce que le capteur est cassé","Parce que le programme est faux","À cause de la couleur du bain"]'::jsonb, 0, 'Le système continue d’évoluer un peu après chaque commutation.', 3),
    ('b40cae28-546f-597b-97ad-ef91622fd868'::uuid, '207f5003-3526-5133-885f-7a4f82dbd0a8'::uuid, 'L’hystérésis est…', 'mcq', '["L’écart entre le seuil d’allumage et le seuil d’extinction","La température de consigne","La durée de chauffage","Le quantum du CAN"]'::jsonb, 0, 'Elle limite le nombre de commutations.', 4),
    ('f294c7c2-4e3b-500a-ab9f-ae2e7ae45b06'::uuid, '207f5003-3526-5133-885f-7a4f82dbd0a8'::uuid, 'Augmenter l’hystérésis rend les commutations…', 'mcq', '["Plus rares, avec des oscillations plus larges","Plus fréquentes","Impossibles","Plus précises"]'::jsonb, 0, 'C’est un compromis entre précision et usure.', 5),
    ('c73db661-1a14-5d95-bcc1-7bbd3ea52210'::uuid, '207f5003-3526-5133-885f-7a4f82dbd0a8'::uuid, 'Pour changer le seuil d’une alarme programmée, on…', 'mcq', '["Modifie la valeur du seuil dans le code","Change le capteur","Débranche le microcontrôleur","Ajoute un CAN"]'::jsonb, 0, 'On attend des élèves qu’ils adaptent un code fourni.', 6),
    ('1dce5091-cdd4-556e-a880-a8a50eb36f52'::uuid, '207f5003-3526-5133-885f-7a4f82dbd0a8'::uuid, 'Une régulation tout ou rien maintient exactement la consigne, sans aucune oscillation.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle oscille toujours autour de la consigne.', 7),
    ('819f3505-61ea-5b3c-bfe0-66038658ea52'::uuid, '207f5003-3526-5133-885f-7a4f82dbd0a8'::uuid, 'Un incubateur réglé à 37 °C avec des seuils 36,5 et 37,5 °C allume son chauffage…', 'mcq', '["Sous 36,5 °C","Au-dessus de 37,5 °C","À exactement 37 °C","En permanence"]'::jsonb, 0, 'Il s’éteindra au-dessus de 37,5 °C.', 8),
    ('e77d04a5-255c-5d56-8609-f97d29c46fa3'::uuid, '207f5003-3526-5133-885f-7a4f82dbd0a8'::uuid, 'Quel exemple relève d’un dispositif d’alerte en tout ou rien ?', 'mcq', '["Une alarme de congélateur au-dessus de −12 °C","Un spectrophotomètre","Une balance","Une burette"]'::jsonb, 0, 'Seul compte le franchissement du seuil.', 9),
    ('4c1d8acd-fde6-51e0-a9be-5e0f9afee5b9'::uuid, '207f5003-3526-5133-885f-7a4f82dbd0a8'::uuid, 'Dans la chaîne en tout ou rien, la comparaison au seuil peut être faite par…', 'mcq', '["Un microcontrôleur","Une fiole jaugée","Une lentille","Un réfrigérant"]'::jsonb, 0, 'Il lit la tension et exécute le programme.', 10),
    ('7c250268-3d9c-56ed-8181-fb90293d8ca2'::uuid, '207f5003-3526-5133-885f-7a4f82dbd0a8'::uuid, 'Sur un enregistrement de régulation, la période des oscillations est…', 'mcq', '["La durée entre deux maximums successifs","La température maximale","La consigne","Le temps de montée initial"]'::jsonb, 0, 'Elle renseigne sur la fréquence des commutations.', 11),
    ('97275764-d337-5306-a3cd-a885c8bcaed9'::uuid, '207f5003-3526-5133-885f-7a4f82dbd0a8'::uuid, 'Deux seuils identiques d’allumage et d’extinction provoqueraient…', 'mcq', '["Des commutations incessantes autour de la consigne","Une température parfaitement stable","L’arrêt définitif du chauffage","Une baisse de la consigne"]'::jsonb, 0, 'D’où l’intérêt d’une hystérésis.', 12),
    ('6d02f5a5-1cee-5dea-8d2e-92c88f7b63d0'::uuid, '6be1bce6-6ef1-540d-80fd-b0d782fb610b'::uuid, 'Quelle est la première phase d’un projet ?', 'mcq', '["S’approprier le sujet et définir la problématique","Rédiger la conclusion","Faire les mesures","Présenter à l’oral"]'::jsonb, 0, 'On cerne et simplifie le problème avant d’agir.', 1),
    ('37d5a3a5-7b7c-5e6c-b8dc-e9df63b15ed9'::uuid, '6be1bce6-6ef1-540d-80fd-b0d782fb610b'::uuid, 'Laquelle de ces formulations est une vraie problématique ?', 'mcq', '["La conductivité permet-elle de détecter un mouillage du lait supérieur à 10 % ?","Étudier le lait","Le lait et la chimie","Faire des expériences sur le lait"]'::jsonb, 0, 'Elle est précise et mesurable.', 2),
    ('a2406e11-705e-5067-a5a0-124712eaa4c2'::uuid, '6be1bce6-6ef1-540d-80fd-b0d782fb610b'::uuid, 'Un cahier des charges fixe…', 'mcq', '["Ce que doit faire la solution et ses contraintes","Les résultats attendus à l’avance","La note du projet","L’ordre de passage à l’oral"]'::jsonb, 0, 'Tous les choix du projet se justifient par rapport à lui.', 3),
    ('d7428581-fa01-554d-a008-af734e96823b'::uuid, '6be1bce6-6ef1-540d-80fd-b0d782fb610b'::uuid, 'Dans le cahier de laboratoire, on note les mesures…', 'mcq', '["Brutes, au moment où on les fait","Recopiées au propre après coup","Seulement si elles sont bonnes","Arrondies sans unité"]'::jsonb, 0, 'C’est la trace fidèle et datée du travail.', 4),
    ('98cab44b-92bb-5437-ae9d-1ad46aadc559'::uuid, '6be1bce6-6ef1-540d-80fd-b0d782fb610b'::uuid, 'Valider des résultats, c’est notamment…', 'mcq', '["Estimer les incertitudes et confronter aux objectifs","Recommencer jusqu’à obtenir la valeur voulue","Supprimer les mesures gênantes","Changer la problématique"]'::jsonb, 0, 'L’esprit critique fait partie de la démarche.', 5),
    ('e0e58508-e0a3-52f0-b02b-86312b10bb76'::uuid, '6be1bce6-6ef1-540d-80fd-b0d782fb610b'::uuid, 'À l’oral, il faut éviter…', 'mcq', '["De lire ses notes","D’annoncer la problématique","De montrer un graphique lisible","D’expliquer ses choix"]'::jsonb, 0, 'Un oral se parle, il ne se lit pas.', 6),
    ('495ed795-310c-54d6-99e4-a85e83ef92d8'::uuid, '6be1bce6-6ef1-540d-80fd-b0d782fb610b'::uuid, 'Un résultat décevant doit être caché lors de la présentation.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On l’explique et on en tire des pistes d’amélioration.', 7),
    ('74aa9901-335f-5485-b147-8f8361809bb2'::uuid, '6be1bce6-6ef1-540d-80fd-b0d782fb610b'::uuid, 'La planification consiste à…', 'mcq', '["Répartir les tâches et fixer les étapes dans le temps","Faire toutes les mesures en même temps","Choisir la couleur des diapositives","Rédiger la bibliographie"]'::jsonb, 0, 'Elle évite de manquer de temps ou de matériel.', 8),
    ('15a1ce79-de35-5df6-9886-2a24372d5af8'::uuid, '6be1bce6-6ef1-540d-80fd-b0d782fb610b'::uuid, 'Le projet de terminale peut être présenté…', 'mcq', '["Au Grand oral","Uniquement par écrit","Jamais à l’oral","Seulement aux parents"]'::jsonb, 0, 'La question présentée au Grand oral s’appuie souvent sur les spécialités.', 9),
    ('49452e90-b01a-5983-8eae-3cbf192b8807'::uuid, '6be1bce6-6ef1-540d-80fd-b0d782fb610b'::uuid, 'Pourquoi rencontrer des chercheurs ou visiter des entreprises ?', 'mcq', '["Pour relier le programme aux métiers et trouver des idées","Pour éviter les cours","Pour obtenir les résultats du projet","Pour remplacer le cahier de laboratoire"]'::jsonb, 0, 'C’est l’ouverture vers le monde de la recherche ou de l’industrie.', 10),
    ('8a967dfd-fe0d-5a31-9919-e3d904c8a120'::uuid, '6be1bce6-6ef1-540d-80fd-b0d782fb610b'::uuid, 'La note concise de fin de projet sert à…', 'mcq', '["Rendre compte du travail et confronter les résultats aux objectifs","Recopier le cours","Lister le matériel acheté","Remplacer l’oral"]'::jsonb, 0, 'Chaque élève y montre ce qu’il a compris.', 11),
    ('3bea38b5-9b04-5153-9d7a-f775174ef7f7'::uuid, '6be1bce6-6ef1-540d-80fd-b0d782fb610b'::uuid, 'Une hypothèse doit être…', 'mcq', '["Testable par une expérience","Toujours vraie","Formulée après les résultats","Hors du sujet"]'::jsonb, 0, 'Le protocole est conçu pour la mettre à l’épreuve.', 12),
    ('5bf0eb9a-0529-58cb-a112-940204cfe2d2'::uuid, 'be69ec2a-a8a7-5e2d-9151-e070fe0a5d2f'::uuid, 'Pour un résultat c = c₁ × V_E / V₀, on combine les incertitudes…', 'mcq', '["En additionnant les incertitudes absolues","En additionnant les carrés des incertitudes relatives, puis en prenant la racine","En gardant seulement la plus petite","En les multipliant entre elles"]'::jsonb, 1, 'Pour un produit ou un quotient de grandeurs indépendantes, ce sont les incertitudes relatives au carré qui s’additionnent.', 1),
    ('0570b0cc-8b9b-5b3e-ace2-2c4994828970'::uuid, 'be69ec2a-a8a7-5e2d-9151-e070fe0a5d2f'::uuid, 'Les incertitudes relatives valent 2 %, 0,2 % et 0,1 %. Laquelle faut-il réduire en priorité ?', 'mcq', '["Celle de 0,1 %","Celle de 0,2 %","Celle de 2 %","Aucune, elles se compensent"]'::jsonb, 2, 'La source dominante fixe presque seule l’incertitude finale : c’est elle qu’on attaque.', 2),
    ('2b6427aa-00a3-56b4-a279-eb64fa20e1c5'::uuid, 'be69ec2a-a8a7-5e2d-9151-e070fe0a5d2f'::uuid, 'Une burette a une tolérance de ± 0,05 mL. Son incertitude-type (type B) vaut environ…', 'mcq', '["0,029 mL","0,05 mL","0,10 mL","0,0029 mL"]'::jsonb, 0, 'u = Δ / √3 = 0,05 / 1,73 ≈ 0,029 mL.', 3),
    ('31400d43-5b12-5a0d-9b8f-2f169bcc8bfb'::uuid, 'be69ec2a-a8a7-5e2d-9151-e070fe0a5d2f'::uuid, 'Augmenter la prise d’essai d’un titrage permet surtout de…', 'mcq', '["Supprimer l’erreur systématique","Changer la valeur de la concentration","Diminuer l’incertitude relative sur le volume équivalent","Rendre la réaction totale"]'::jsonb, 2, 'Un volume équivalent plus grand, pour la même erreur absolue de lecture, donne une erreur relative plus petite.', 4),
    ('990678ad-ddcf-5178-8924-3a93a55c2b52'::uuid, 'be69ec2a-a8a7-5e2d-9151-e070fe0a5d2f'::uuid, 'Incertitudes relatives de 0,3 % et 0,4 % : l’incertitude relative combinée vaut…', 'mcq', '["0,7 %","0,5 %","0,1 %","0,12 %"]'::jsonb, 1, '√(0,09 + 0,16) = √0,25 = 0,5 %.', 5),
    ('29150bb7-add4-5bba-bcf0-089e72333d87'::uuid, 'be69ec2a-a8a7-5e2d-9151-e070fe0a5d2f'::uuid, 'Un histogramme très resserré mais décalé de la référence traduit une série…', 'mcq', '["Juste et fidèle","Juste mais peu fidèle","Ni juste ni fidèle","Fidèle mais peu juste"]'::jsonb, 3, 'Peu de dispersion (fidèle), mais un décalage systématique (pas juste).', 6),
    ('f7dc3aa5-48e9-5c71-ac89-2fabbbdbe79a'::uuid, 'be69ec2a-a8a7-5e2d-9151-e070fe0a5d2f'::uuid, 'Améliorer une source d’erreur déjà négligeable réduit nettement l’incertitude finale.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les carrés des petites contributions pèsent très peu dans la somme : seul le terme dominant compte vraiment.', 7),
    ('f8ba1b88-9769-5b73-8332-b4b626e9f2da'::uuid, 'be69ec2a-a8a7-5e2d-9151-e070fe0a5d2f'::uuid, 'c = 0,0856 mol/L avec u(c) = 0,0012 mol/L. Quelle écriture est correcte ?', 'mcq', '["c = 0,0856 mol/L, u = 0,0012 mol/L","c = 0,08560 mol/L, u = 0,001 mol/L","c = 0,09 mol/L, u = 0,0012 mol/L","c = 0,086 mol/L, u = 0,00123 mol/L"]'::jsonb, 0, 'L’incertitude garde deux chiffres significatifs et la valeur est arrondie au même rang décimal.', 8),
    ('81ccde94-e86b-589a-b16f-d4190154897e'::uuid, 'be69ec2a-a8a7-5e2d-9151-e070fe0a5d2f'::uuid, 'x = 5,32 ; x_réf = 5,20 ; u(x) = 0,04. Le résultat est…', 'mcq', '["Compatible, z = 1,5","Incompatible, z = 3","Compatible, z = 0,3","Impossible à juger"]'::jsonb, 1, 'z = 0,12 / 0,04 = 3, supérieur à 2 : on cherche une erreur systématique.', 9),
    ('36383905-73ac-5aee-84cd-3f98604f079b'::uuid, 'be69ec2a-a8a7-5e2d-9151-e070fe0a5d2f'::uuid, 'Quel outil le programme cite-t-il pour représenter la dispersion d’une série de mesures ?', 'mcq', '["Le diagramme en secteurs","La frise chronologique","L’histogramme","Le diagramme de prédominance"]'::jsonb, 2, 'L’histogramme, tracé au tableur ou par un programme, montre la forme et la largeur de la dispersion.', 10),
    ('8e123634-8ea8-59e8-a27a-33c20c5b7190'::uuid, 'be69ec2a-a8a7-5e2d-9151-e070fe0a5d2f'::uuid, 'Dans un titrage colorimétrique, repérer le virage « un peu tard » est une erreur…', 'mcq', '["Liée à l’opérateur et à la méthode","Liée uniquement à l’instrument","Impossible à éviter par principe","Liée à la valeur de référence"]'::jsonb, 0, 'L’œil et le choix de l’indicateur interviennent : un suivi pH-métrique réduit cette source.', 11),
    ('54f5d9c5-90e0-5379-b66d-79af825cd66b'::uuid, 'be69ec2a-a8a7-5e2d-9151-e070fe0a5d2f'::uuid, 'Pour choisir le matériel adapté à la précision attendue, on privilégie pour prélever 10,00 mL…', 'mcq', '["Une éprouvette graduée","Un bécher gradué","Une pipette jaugée","Une fiole jaugée de 100 mL"]'::jsonb, 2, 'La pipette jaugée délivre un volume précis ; l’éprouvette et le bécher sont bien moins précis.', 12),
    ('62d6e624-1990-55d4-b6b4-f589c65be152'::uuid, '11a0a0da-e48d-5859-86ab-45475b63b443'::uuid, 'Le quotient de réaction de la dissolution de AgCl(s) s’écrit…', 'mcq', '["[AgCl]","[Ag⁺] × [Cl⁻] / [AgCl]","[Ag⁺] + [Cl⁻]","[Ag⁺] × [Cl⁻]"]'::jsonb, 3, 'Le solide n’apparaît pas dans le quotient de réaction.', 1),
    ('504a7177-b4b9-5fbc-a6d1-87055bc486d6'::uuid, '11a0a0da-e48d-5859-86ab-45475b63b443'::uuid, 'Si Qr > Ks, que se passe-t-il ?', 'mcq', '["Le solide se dissout","Un précipité se forme","Rien, le système est à l’équilibre","La température augmente"]'::jsonb, 1, 'Le système évolue dans le sens qui fait baisser Qr : les ions précipitent.', 2),
    ('f0eaf58e-e030-551d-b505-fce833c3c6f4'::uuid, '11a0a0da-e48d-5859-86ab-45475b63b443'::uuid, 'Pour AgCl, Ks = 1,8 × 10⁻¹⁰. La solubilité vaut environ…', 'mcq', '["1,3 × 10⁻⁵ mol/L","1,8 × 10⁻¹⁰ mol/L","9 × 10⁻¹¹ mol/L","1,3 × 10⁻¹⁰ mol/L"]'::jsonb, 0, 's = √Ks ≈ 1,3 × 10⁻⁵ mol/L.', 3),
    ('6b8cbf82-eb58-5e04-b4f0-76f5a94b43e2'::uuid, '11a0a0da-e48d-5859-86ab-45475b63b443'::uuid, 'Ajouter des ions chlorure à une solution saturée de AgCl…', 'mcq', '["Augmente la solubilité de AgCl","Ne change rien","Diminue la solubilité de AgCl","Dissout tout le précipité"]'::jsonb, 2, 'C’est l’effet d’ion commun : Qr dépasse Ks, du AgCl précipite.', 4),
    ('cdd24438-7c75-5b19-a33d-08b8d7b4d26e'::uuid, '11a0a0da-e48d-5859-86ab-45475b63b443'::uuid, 'La constante de cellule k relie…', 'mcq', '["La conductivité σ et la conductance G","La concentration et le pH","Ks et la température","La masse et le volume"]'::jsonb, 0, 'σ = k × G : k dépend seulement de la géométrie de la cellule.', 5),
    ('5c63f0f5-12ed-5158-b3a7-b91e9daad792'::uuid, '11a0a0da-e48d-5859-86ab-45475b63b443'::uuid, 'Dans la loi de Kohlrausch, les concentrations s’expriment en…', 'mcq', '["mol/L","g/L","mol/m³","mol/kg"]'::jsonb, 2, 'Avec λ en S·m²/mol, il faut des mol/m³ pour obtenir σ en S/m.', 6),
    ('bec411af-d92f-5a15-a40b-a500456ed74c'::uuid, '11a0a0da-e48d-5859-86ab-45475b63b443'::uuid, 'Quels ions ont une conductivité molaire ionique exceptionnellement grande ?', 'mcq', '["Na⁺ et Cl⁻","H₃O⁺ et HO⁻","K⁺ et NO₃⁻","Ag⁺ et Cl⁻"]'::jsonb, 1, 'Leur mobilité particulière explique les fortes variations de σ lors d’un titrage acide-base.', 7),
    ('b33eb080-5a02-52c1-9b69-e4f3a8669056'::uuid, '11a0a0da-e48d-5859-86ab-45475b63b443'::uuid, 'Dans un titrage conductimétrique, l’équivalence se repère…', 'mcq', '["Au changement de pente de la courbe σ = f(V)","Au maximum de la courbe de pH","Au changement de couleur de la solution","Quand σ s’annule"]'::jsonb, 0, 'La courbe est faite de segments ; leur intersection donne V_E.', 8),
    ('129d992a-df93-5b33-a8e4-ac15bc947ba4'::uuid, '11a0a0da-e48d-5859-86ab-45475b63b443'::uuid, 'Les hydroxydes métalliques précipitant à des pH différents, on peut séparer des ions en réglant le pH.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est la précipitation sélective des hydroxydes, utilisée en traitement des effluents.', 9),
    ('2cfc876b-ac3e-591d-bca3-7265cb16fae4'::uuid, '11a0a0da-e48d-5859-86ab-45475b63b443'::uuid, 'Pourquoi refroidit-on une solution chaude saturée pour recristalliser un solide ?', 'mcq', '["Parce que Ks augmente en général quand on refroidit","Parce que la conductivité augmente","Parce que le solide devient un gaz","Parce que Ks diminue en général quand la température baisse"]'::jsonb, 3, 'La solubilité baisse, le solide dissous en excès cristallise.', 10),
    ('97c3b572-276c-5b21-bd74-9f535fd80573'::uuid, '11a0a0da-e48d-5859-86ab-45475b63b443'::uuid, 'Pour doser par étalonnage conductimétrique, on travaille en solution diluée car…', 'mcq', '["σ y est proportionnelle à la concentration","σ y est nulle","Le pH y vaut 7","Les ions n’y conduisent plus"]'::jsonb, 0, 'La proportionnalité σ = a × c n’est vérifiée qu’aux faibles concentrations.', 11),
    ('51150c06-f13a-5348-ad80-ae90b21d4dd6'::uuid, '11a0a0da-e48d-5859-86ab-45475b63b443'::uuid, 'Titrage de 10,0 mL de Cl⁻ par Ag⁺ à 0,050 mol/L : V_E = 12,0 mL. c(Cl⁻) vaut…', 'mcq', '["0,042 mol/L","0,060 mol/L","0,050 mol/L","0,120 mol/L"]'::jsonb, 1, 'c = 0,050 × 12,0 / 10,0 = 0,060 mol/L (réaction mole à mole).', 12),
    ('dc150c95-9027-55f3-b3d9-366597e93c1c'::uuid, '1b34dd0c-4777-5d88-8934-f9755390872c'::uuid, 'Entre deux acides faibles, le plus fort est celui qui a…', 'mcq', '["Le plus grand pKa","Le plus petit Ka","Le plus petit pKa","La plus grande masse molaire"]'::jsonb, 2, 'Un petit pKa correspond à un grand Ka : l’acide se dissocie davantage.', 1),
    ('a76a1e5d-cbd3-5c4a-ad1d-f740ec50e289'::uuid, '1b34dd0c-4777-5d88-8934-f9755390872c'::uuid, 'La relation de Henderson-Hasselbalch s’écrit…', 'mcq', '["pH = pKa + log([A⁻]/[AH])","pH = pKa − log([A⁻]/[AH])","pH = Ka × [A⁻]","pH = − log Ka + [AH]"]'::jsonb, 0, 'Elle découle directement de l’expression de Ka.', 2),
    ('15ac2639-4d0f-52d9-bde6-0f9e81353e30'::uuid, '1b34dd0c-4777-5d88-8934-f9755390872c'::uuid, 'À pH = 6, pour un couple de pKa 4,8, l’espèce prédominante est…', 'mcq', '["La forme acide","Aucune des deux","Les deux à égalité","La forme basique"]'::jsonb, 3, 'pH > pKa : c’est la base conjuguée qui prédomine.', 3),
    ('9667d0bf-84de-5651-9128-6fd8d7362e95'::uuid, '1b34dd0c-4777-5d88-8934-f9755390872c'::uuid, 'Le pH d’une solution d’acide chlorhydrique à 1,0 × 10⁻² mol/L vaut…', 'mcq', '["12","2","1","0,01"]'::jsonb, 1, 'Acide fort : pH = − log c = 2.', 4),
    ('055ee050-3374-5640-8a6d-5b83128f50d9'::uuid, '1b34dd0c-4777-5d88-8934-f9755390872c'::uuid, 'Le pH d’une solution de soude à 1,0 × 10⁻³ mol/L vaut (25 °C)…', 'mcq', '["3","7","11","13"]'::jsonb, 2, 'Base forte : pH = 14 + log c = 14 − 3 = 11.', 5),
    ('a9977c22-4fda-5208-b8f5-b4e6780b65af'::uuid, '1b34dd0c-4777-5d88-8934-f9755390872c'::uuid, 'Diluer une solution d’acide faible fait…', 'mcq', '["Augmenter son coefficient de dissociation","Diminuer son coefficient de dissociation","Changer son pKa","Le transformer en acide fort"]'::jsonb, 0, 'Plus l’acide est dilué, plus il se dissocie, même si le pH remonte.', 6),
    ('b1af2ffc-984b-5651-8ea1-4c7b268b1523'::uuid, '1b34dd0c-4777-5d88-8934-f9755390872c'::uuid, 'À la demi-équivalence du titrage d’un acide faible par une base forte…', 'mcq', '["pH = 7","pH = pKa","pH = 14","pH = 2 × pKa"]'::jsonb, 1, 'La moitié de l’acide a été transformée : [AH] = [A⁻], donc pH = pKa.', 7),
    ('46d09e13-da43-58c1-b78d-a335d7725f75'::uuid, '1b34dd0c-4777-5d88-8934-f9755390872c'::uuid, 'Pour un titrage dont le pH à l’équivalence vaut 8,7, quel indicateur choisir ?', 'mcq', '["Hélianthine (3,1 – 4,4)","Bleu de bromothymol (6,0 – 7,6)","Rouge de méthyle (4,2 – 6,2)","Phénolphtaléine (8,2 – 10)"]'::jsonb, 3, 'La zone de virage doit contenir le pH à l’équivalence.', 8),
    ('1b3a73c6-1673-5446-b515-327e1a1d779d'::uuid, '1b34dd0c-4777-5d88-8934-f9755390872c'::uuid, 'Dans un titrage indirect, la quantité de l’espèce dosée est obtenue…', 'mcq', '["Par différence entre l’excès introduit et ce qui reste","Directement au volume équivalent","Par la lecture du pKa","Par la couleur de la solution"]'::jsonb, 0, 'On titre le réactif restant, puis on retranche.', 9),
    ('a8b162fe-d302-5696-9f12-a7d061407303'::uuid, '1b34dd0c-4777-5d88-8934-f9755390872c'::uuid, 'Une solution tampon voit son pH varier fortement par une dilution modérée.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le rapport [A⁻]/[AH] ne change pas à la dilution : le pH reste presque constant.', 10),
    ('7555f7bc-0215-55ab-89a8-f97852414d05'::uuid, '1b34dd0c-4777-5d88-8934-f9755390872c'::uuid, 'Avec un tableur, le volume équivalent correspond…', 'mcq', '["Au minimum de la courbe pH = f(V)","Au point où pH = pKa","Au maximum de la dérivée dpH/dV","Au premier point de mesure"]'::jsonb, 2, 'Le saut de pH est le plus raide à l’équivalence : la dérivée y est maximale.', 11),
    ('fdbaeb4b-4696-59f3-86c7-7ad9ee7fee86'::uuid, '1b34dd0c-4777-5d88-8934-f9755390872c'::uuid, '10,0 mL d’acide titrés par la soude à 0,200 mol/L : V_E = 8,0 mL. c(acide) vaut…', 'mcq', '["0,25 mol/L","0,16 mol/L","0,080 mol/L","0,40 mol/L"]'::jsonb, 1, 'c = 0,200 × 8,0 / 10,0 = 0,16 mol/L.', 12),
    ('2c1b96d3-9427-5ab8-bebe-2547cf62a356'::uuid, 'ef4dd4bf-db9f-5f4b-a038-079220f19550'::uuid, 'Quelle est l’électrode de référence théorique des potentiels standard ?', 'mcq', '["L’électrode au calomel saturé","L’électrode de platine seule","L’électrode standard à hydrogène","L’électrode de verre"]'::jsonb, 2, 'Par convention, l’ESH a un potentiel nul.', 1),
    ('ce219610-bbb9-57d1-b512-b63817bd0eac'::uuid, 'ef4dd4bf-db9f-5f4b-a038-079220f19550'::uuid, 'Dans la relation de Nernst, augmenter [Ox] fait…', 'mcq', '["Augmenter le potentiel du couple","Diminuer le potentiel du couple","Changer E°","Ne rien changer"]'::jsonb, 0, 'Le terme log([Ox]/[Red]) augmente.', 2),
    ('dedaafc5-1a54-5bd1-9212-e8275334e950'::uuid, 'ef4dd4bf-db9f-5f4b-a038-079220f19550'::uuid, 'Couples Fe³⁺/Fe²⁺ (0,77 V) et Sn⁴⁺/Sn²⁺ (0,15 V). La réaction spontanée a lieu entre…', 'mcq', '["Fe²⁺ et Sn⁴⁺","Fe³⁺ et Sn²⁺","Fe³⁺ et Sn⁴⁺","Fe²⁺ et Sn²⁺"]'::jsonb, 1, 'L’oxydant le plus fort (Fe³⁺) réagit avec le réducteur le plus fort (Sn²⁺).', 3),
    ('15e2bec2-1bba-5cb8-a75e-3a895ac50e1b'::uuid, 'ef4dd4bf-db9f-5f4b-a038-079220f19550'::uuid, 'Une réaction prévue totale mais qu’on n’observe pas à l’échelle de l’heure est…', 'mcq', '["Impossible","Mal équilibrée","Endothermique","Bloquée cinétiquement"]'::jsonb, 3, 'La thermodynamique donne le sens, pas la vitesse : un catalyseur peut débloquer la réaction.', 4),
    ('6c443b41-dd5d-5699-9948-8be99fb45590'::uuid, 'ef4dd4bf-db9f-5f4b-a038-079220f19550'::uuid, 'Dans un titrage potentiométrique, l’équivalence se repère…', 'mcq', '["Au saut de potentiel","Quand la tension s’annule","Au premier ajout","Quand le pH vaut 7"]'::jsonb, 0, 'Le potentiel varie brutalement au voisinage de l’équivalence.', 5),
    ('2315595e-0e60-5bf1-83df-dac34d778f9e'::uuid, 'ef4dd4bf-db9f-5f4b-a038-079220f19550'::uuid, 'Lors d’une électrolyse, l’anode est le siège…', 'mcq', '["D’une réduction","D’une oxydation","D’une précipitation","D’aucune réaction"]'::jsonb, 1, 'Anode : oxydation ; cathode : réduction, dans une pile comme dans un électrolyseur.', 6),
    ('9bdd06c3-82e9-58d1-8499-1bc9795974c3'::uuid, 'ef4dd4bf-db9f-5f4b-a038-079220f19550'::uuid, 'L’anode d’un électrolyseur est reliée…', 'mcq', '["Au pôle − du générateur","À la terre","Au pôle + du générateur","À l’électrode de référence"]'::jsonb, 2, 'Le pôle + arrache des électrons à l’anode : c’est là que se fait l’oxydation.', 7),
    ('3521db53-244d-5b11-b0c8-9194952022b2'::uuid, 'ef4dd4bf-db9f-5f4b-a038-079220f19550'::uuid, 'Une électrolyse est une transformation…', 'mcq', '["Spontanée","Forcée par un générateur","Toujours totale","Sans échange d’électrons"]'::jsonb, 1, 'Elle fait avancer le système dans le sens inverse de son sens spontané.', 8),
    ('a6bacc9b-8f9c-550d-a447-dc20130d2227'::uuid, 'ef4dd4bf-db9f-5f4b-a038-079220f19550'::uuid, 'Un courant de 2,0 A circule pendant 965 s. Quelle quantité d’électrons ?', 'mcq', '["0,020 mol","1 930 mol","2,0 mol","0,20 mol"]'::jsonb, 0, 'Q = 1 930 C ; n = 1 930 / 96 500 = 0,020 mol.', 9),
    ('f466bb08-f31c-54e7-999b-510fc9d0036f'::uuid, 'ef4dd4bf-db9f-5f4b-a038-079220f19550'::uuid, 'Le rendement faradique compare…', 'mcq', '["La tension appliquée et la tension minimale","La masse d’anode et la masse de cathode","La quantité de produit obtenue et celle que la charge aurait dû produire","Deux potentiels standard"]'::jsonb, 2, 'Une partie du courant sert souvent à des réactions parasites (dégagement de dihydrogène).', 10),
    ('73e6d6b1-0fc9-5fb2-b911-b701b8d5941c'::uuid, 'ef4dd4bf-db9f-5f4b-a038-079220f19550'::uuid, 'Certaines électrolyses permettent de recycler des métaux.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’affinage à anode soluble récupère par exemple un cuivre très pur à partir de cuivre impur.', 11),
    ('6e68b2fd-9667-5442-8a49-af916e839f16'::uuid, 'ef4dd4bf-db9f-5f4b-a038-079220f19550'::uuid, 'Pour la réaction entre Fe³⁺ (0,77 V) et Sn²⁺ (0,15 V) avec n = 2, log K vaut environ…', 'mcq', '["10","6","42","21"]'::jsonb, 3, 'log K = 2 × 0,62 / 0,059 ≈ 21 : la réaction est totale.', 12),
    ('ef6af129-745f-59f5-849b-4071d1f4fc37'::uuid, '7005d5da-085d-574a-8eac-82205b734355'::uuid, 'L’estérification entre un acide carboxylique et un alcool est…', 'mcq', '["Rapide et totale","Lente et limitée par un équilibre","Impossible sans lumière","Une oxydation"]'::jsonb, 1, 'Elle conduit à un équilibre : environ 67 % avec des réactifs équimolaires.', 1),
    ('9f1f0824-85f8-581d-bdf0-a0a3d3dd64d6'::uuid, '7005d5da-085d-574a-8eac-82205b734355'::uuid, 'Le montage de Dean-Stark permet…', 'mcq', '["D’éliminer l’eau formée et de déplacer l’équilibre","De mesurer le pH","De refroidir le milieu","D’identifier le produit"]'::jsonb, 0, 'L’eau est entraînée et piégée : l’équilibre avance vers l’ester.', 2),
    ('9a948a18-c225-59c5-9da1-9620d117799c'::uuid, '7005d5da-085d-574a-8eac-82205b734355'::uuid, 'L’oxydation ménagée d’un alcool secondaire donne…', 'mcq', '["Un aldéhyde","Un acide carboxylique","Une cétone","Un ester"]'::jsonb, 2, 'Un alcool primaire donne un aldéhyde puis un acide ; un secondaire donne une cétone.', 3),
    ('7f9524d2-d1ca-5195-8dc4-ec3a98cdc974'::uuid, '7005d5da-085d-574a-8eac-82205b734355'::uuid, 'La réduction d’une cétone par NaBH₄ donne…', 'mcq', '["Un alcool primaire","Un alcool secondaire","Un alcool tertiaire","Un acide"]'::jsonb, 1, 'Le carbone du groupe carbonyle porte deux chaînes : l’alcool obtenu est secondaire.', 4),
    ('b3f553da-adb4-5f6d-baa0-90081c26a2cd'::uuid, '7005d5da-085d-574a-8eac-82205b734355'::uuid, 'La saponification d’un ester est…', 'mcq', '["Totale","Limitée par un équilibre","Une estérification","Impossible en milieu basique"]'::jsonb, 0, 'L’ion carboxylate formé ne réagit plus : rien ne revient en arrière.', 5),
    ('410071bc-9328-5536-b249-e0fb0c448242'::uuid, '7005d5da-085d-574a-8eac-82205b734355'::uuid, 'Quel changement de réactif rend l’estérification totale ?', 'mcq', '["Remplacer l’alcool par de l’eau","Remplacer l’acide par un anhydride d’acide","Diluer le milieu","Supprimer le catalyseur"]'::jsonb, 1, 'L’anhydride est plus réactif et la réaction ne produit pas d’eau.', 6),
    ('55f3573d-5a4f-5783-a76b-746d6021a62b'::uuid, '7005d5da-085d-574a-8eac-82205b734355'::uuid, 'Un catalyseur modifie la valeur du rendement final d’un équilibre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il accélère l’atteinte de l’équilibre sans déplacer celui-ci.', 7),
    ('9dc49ee6-c0ff-55b6-b847-ca9d6811bcdd'::uuid, '7005d5da-085d-574a-8eac-82205b734355'::uuid, 'Un bon solvant de recristallisation dissout le produit…', 'mcq', '["Peu à chaud, beaucoup à froid","Beaucoup à chaud et à froid","Pas du tout","Beaucoup à chaud, peu à froid"]'::jsonb, 3, 'Le produit cristallise au refroidissement, les impuretés restent en solution.', 8),
    ('d0623676-e201-5b86-9196-53bd859af046'::uuid, '7005d5da-085d-574a-8eac-82205b734355'::uuid, '0,50 mol d’ester attendu, 0,35 mol obtenu. Le rendement vaut…', 'mcq', '["35 %","50 %","70 %","143 %"]'::jsonb, 2, '0,35 / 0,50 = 0,70.', 9),
    ('d7b99326-b597-5e69-998c-e752d453efbf'::uuid, '7005d5da-085d-574a-8eac-82205b734355'::uuid, 'Pour extraire une huile essentielle de lavande, on utilise…', 'mcq', '["L’hydrodistillation","La saponification","Le Dean-Stark","Le titrage"]'::jsonb, 0, 'La vapeur d’eau entraîne les composés odorants, qu’on récupère après condensation.', 10),
    ('c3607a9a-60b5-55e3-b45d-fa3635af818c'::uuid, '7005d5da-085d-574a-8eac-82205b734355'::uuid, 'Un amide se forme en faisant réagir…', 'mcq', '["Un alcool et un aldéhyde","Un ester et de l’eau","Une cétone et un réducteur","Un acide (ou chlorure d’acyle) et une amine"]'::jsonb, 3, 'Le groupe caractéristique amide relie un carbonyle et un atome d’azote.', 11),
    ('9fea7310-3a9a-523a-9222-858532a8b870'::uuid, '7005d5da-085d-574a-8eac-82205b734355'::uuid, 'Selon la chimie verte, pour comparer deux protocoles, on regarde notamment…', 'mcq', '["Seulement la couleur du produit","Les déchets, l’énergie, la toxicité des solvants et le rendement","Seulement le prix du flacon","La masse de la verrerie"]'::jsonb, 1, 'Le meilleur protocole n’est pas toujours celui qui a le plus grand rendement.', 12),
    ('f51eefc3-a40d-58f9-8db0-7b9c0c03a617'::uuid, 'aadd80b4-1928-5798-8527-668c7d1f2cd5'::uuid, 'En RMN du proton, le nombre de signaux indique…', 'mcq', '["Le nombre total d’atomes de carbone","Le nombre de groupes de protons équivalents","La masse molaire","Le nombre de liaisons doubles"]'::jsonb, 1, 'Des protons de même environnement donnent un seul signal.', 1),
    ('37b3a0f5-4dc2-5388-a95d-61632f0bca79'::uuid, 'aadd80b4-1928-5798-8527-668c7d1f2cd5'::uuid, 'Un groupe de protons ayant 2 protons voisins donne…', 'mcq', '["Un triplet","Un doublet","Un singulet","Un quadruplet"]'::jsonb, 0, 'Règle des (n + 1) : 2 + 1 = 3 pics.', 2),
    ('fda832a2-e02c-586a-a582-4def09216695'::uuid, 'aadd80b4-1928-5798-8527-668c7d1f2cd5'::uuid, 'La courbe d’intégration renseigne sur…', 'mcq', '["La couleur de la molécule","La température de fusion","Le nombre relatif de protons de chaque groupe","La polarité du solvant"]'::jsonb, 2, 'La hauteur de chaque marche est proportionnelle au nombre de protons.', 3),
    ('8bdd21b5-5d9c-52af-a958-f509a7e594ec'::uuid, 'aadd80b4-1928-5798-8527-668c7d1f2cd5'::uuid, 'Un proton porté par un carbone lié à un atome d’oxygène a un déplacement chimique…', 'mcq', '["Plus petit que celui d’un CH₃ de chaîne","Égal à zéro","Toujours négatif","Plus grand, vers 3,3 – 4,3 ppm"]'::jsonb, 3, 'L’oxygène électronégatif « déblinde » le proton : δ augmente.', 4),
    ('4891ad82-e87d-535f-bd65-372e2c986397'::uuid, 'aadd80b4-1928-5798-8527-668c7d1f2cd5'::uuid, 'Le signal d’un proton d’aldéhyde se situe vers…', 'mcq', '["9 – 10 ppm","0,9 ppm","2 ppm","5 ppm"]'::jsonb, 0, 'C’est l’un des signaux les plus caractéristiques d’un spectre RMN.', 5),
    ('85dd49d5-dd74-5234-bb3b-8a08af79b52f'::uuid, 'aadd80b4-1928-5798-8527-668c7d1f2cd5'::uuid, 'Combien de signaux donne l’éthanoate d’éthyle CH₃–CO–O–CH₂–CH₃ ?', 'mcq', '["Deux","Trois","Quatre","Huit"]'::jsonb, 1, 'Deux CH₃ d’environnements différents et un CH₂.', 6),
    ('e6a83605-dd05-55c0-a14b-66503279dbeb'::uuid, 'aadd80b4-1928-5798-8527-668c7d1f2cd5'::uuid, 'Dans l’éthanoate d’éthyle, le CH₃ lié au C=O donne…', 'mcq', '["Un triplet","Un quadruplet","Un singulet","Un doublet"]'::jsonb, 2, 'Le carbone voisin (celui du C=O) ne porte aucun hydrogène.', 7),
    ('ef3189aa-ce36-5000-ad61-eb0e9f35a25f'::uuid, 'aadd80b4-1928-5798-8527-668c7d1f2cd5'::uuid, 'La référence des déplacements chimiques (δ = 0) est…', 'mcq', '["L’eau","Le TMS (tétraméthylsilane)","Le chloroforme","Le benzène"]'::jsonb, 1, 'Tous les δ sont mesurés par rapport au signal du TMS.', 8),
    ('c7c8c0ee-6cb9-50c6-9374-afb5a92d84bf'::uuid, 'aadd80b4-1928-5798-8527-668c7d1f2cd5'::uuid, 'Une intégration 1 : 1,5 peut correspondre à 2 H et 3 H.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’intégration donne des rapports ; on les convertit en nombres entiers.', 9),
    ('fb13ea85-d89a-5533-a27b-cae66e79ad80'::uuid, 'aadd80b4-1928-5798-8527-668c7d1f2cd5'::uuid, 'Pour confirmer la présence d’un groupe C=O, on utilise surtout…', 'mcq', '["La RMN seule","Le pH-mètre","La conductimétrie","La spectroscopie IR (bande vers 1 700 cm⁻¹)"]'::jsonb, 3, 'IR et RMN se complètent : l’une donne les groupes, l’autre le squelette.', 10),
    ('4d86dcf6-16ae-5f3a-8126-dc21bc1e8993'::uuid, 'aadd80b4-1928-5798-8527-668c7d1f2cd5'::uuid, 'Le CH₃ de l’éthanol CH₃–CH₂–OH apparaît sous forme de…', 'mcq', '["Singulet","Quadruplet","Triplet","Doublet"]'::jsonb, 2, 'Ses voisins sont les 2 H du CH₂ : 2 + 1 = 3 pics.', 11),
    ('ca869924-4e03-5559-8131-fe7cf7d0fbec'::uuid, 'aadd80b4-1928-5798-8527-668c7d1f2cd5'::uuid, 'Un signal vers 11 ppm, large et singulet, évoque…', 'mcq', '["Un CH₃ d’alcane","Un proton d’acide carboxylique","Un proton aromatique","Un CH₂ lié à un carbonyle"]'::jsonb, 1, 'Le proton de –COOH est très déblindé (10 – 13 ppm).', 12),
    ('1c8cf6df-0f3a-5b9b-95fa-77e08448059c'::uuid, '75648af5-2b21-5d8f-b1df-bcb73f8b33f5'::uuid, 'Un carbone asymétrique est lié à…', 'mcq', '["Deux groupes identiques","Quatre groupes différents","Un atome d’oxygène","Une double liaison"]'::jsonb, 1, 'C’est la condition la plus fréquente de chiralité d’une molécule.', 1),
    ('3b3348ce-e593-5c8e-b147-a9f1df07d091'::uuid, '75648af5-2b21-5d8f-b1df-bcb73f8b33f5'::uuid, 'Deux énantiomères ont…', 'mcq', '["Des températures d’ébullition différentes","Des formules brutes différentes","Les mêmes propriétés physiques usuelles mais des pouvoirs rotatoires opposés","Toujours les mêmes effets biologiques"]'::jsonb, 2, 'Seules la lumière polarisée et les interactions avec d’autres molécules chirales les distinguent.', 2),
    ('98c29925-2d2e-511b-a4aa-35e307b57bec'::uuid, '75648af5-2b21-5d8f-b1df-bcb73f8b33f5'::uuid, 'Un mélange racémique…', 'mcq', '["N’a aucune activité optique","Est un seul énantiomère","Dévie fortement la lumière","Est un diastéréoisomère"]'::jsonb, 0, 'Les deux énantiomères en quantités égales compensent leurs déviations.', 3),
    ('d7011edb-c163-5b69-b8d1-8d9e4dca6bee'::uuid, '75648af5-2b21-5d8f-b1df-bcb73f8b33f5'::uuid, 'On peut séparer deux diastéréoisomères par distillation ou recristallisation car…', 'mcq', '["Ils sont énantiomères","Leurs propriétés physiques diffèrent","Ils ont la même température de fusion","Ils n’ont pas de carbone"]'::jsonb, 1, 'Contrairement aux énantiomères, les diastéréoisomères ont des propriétés physiques distinctes.', 4),
    ('4263afb8-638d-5e95-8388-c946c395ff50'::uuid, '75648af5-2b21-5d8f-b1df-bcb73f8b33f5'::uuid, 'Dans la loi de Biot α = [α] × ℓ × c, ℓ s’exprime en…', 'mcq', '["mètres","centimètres","nanomètres","décimètres"]'::jsonb, 3, 'Par convention historique, la longueur de la cuve est en dm.', 5),
    ('098f3a70-792f-5a04-8dac-961859fc37ab'::uuid, '75648af5-2b21-5d8f-b1df-bcb73f8b33f5'::uuid, 'α(pur) = − 20° et α(mélange) = − 5° à même concentration. L’excès énantiomérique vaut…', 'mcq', '["25 %","75 %","5 %","400 %"]'::jsonb, 0, 'ee = 5 / 20 × 100 = 25 %.', 6),
    ('2a98c19c-8b2d-5b77-8a74-4bbfef98ffb1'::uuid, '75648af5-2b21-5d8f-b1df-bcb73f8b33f5'::uuid, 'Le carbocation le plus stable est…', 'mcq', '["Primaire","Méthyle","Tertiaire","Ils sont tous aussi stables"]'::jsonb, 2, 'Les groupes alkyle voisins stabilisent la charge positive.', 7),
    ('20fcbaf9-5109-5c03-8291-fa5b94fc3118'::uuid, '75648af5-2b21-5d8f-b1df-bcb73f8b33f5'::uuid, 'Pour les carbanions, l’ordre de stabilité est le même que pour les carbocations.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est l’inverse : un carbanion primaire est plus stable qu’un tertiaire.', 8),
    ('fec0ef8e-372b-5ad3-8245-83e10899bcbc'::uuid, '75648af5-2b21-5d8f-b1df-bcb73f8b33f5'::uuid, 'Une flèche courbe part…', 'mcq', '["D’un site riche en électrons vers un site pauvre","D’un site pauvre vers un site riche","D’un atome d’hydrogène vers le solvant","Du produit vers le réactif"]'::jsonb, 0, 'Elle représente le déplacement d’un doublet d’électrons.', 9),
    ('c67a49e8-0b57-5dd7-a198-7e1ba5796db1'::uuid, '75648af5-2b21-5d8f-b1df-bcb73f8b33f5'::uuid, 'Les formes mésomères d’un ion carboxylate…', 'mcq', '["Sont deux molécules différentes en équilibre","Décrivent la délocalisation des électrons sur les deux oxygènes","N’existent que dans le vide","Sont des énantiomères"]'::jsonb, 1, 'La structure réelle est intermédiaire ; la délocalisation stabilise l’ion.', 10),
    ('f87e20f4-2b58-5070-993c-1872b9436283'::uuid, '75648af5-2b21-5d8f-b1df-bcb73f8b33f5'::uuid, 'Un catalyseur…', 'mcq', '["Est consommé par la réaction","Apparaît dans l’équation-bilan","Déplace l’équilibre","Est régénéré à la fin du mécanisme"]'::jsonb, 3, 'Il intervient dans une étape puis est restitué.', 11),
    ('51aae66f-efe0-5b9c-89a6-22886a3f7753'::uuid, '75648af5-2b21-5d8f-b1df-bcb73f8b33f5'::uuid, 'Les isomères Z et E d’un alcène sont des…', 'mcq', '["Énantiomères","Isomères de constitution","Diastéréoisomères","Formes mésomères"]'::jsonb, 2, 'Ils ne sont pas images l’un de l’autre dans un miroir.', 12),
    ('9bc717ed-da28-5485-8657-376013c7a615'::uuid, '006aa1bf-33e3-5bd9-aa20-b6a924f2b752'::uuid, 'La période propre d’un oscillateur masse-ressort vaut…', 'mcq', '["T₀ = 2π √(k / m)","T₀ = 2π √(m / k)","T₀ = m × k","T₀ = 2π m / k"]'::jsonb, 1, 'Plus la masse est grande, plus l’oscillation est lente.', 1),
    ('a0a1f514-0f2b-56d9-ad60-c726b62f0f15'::uuid, '006aa1bf-33e3-5bd9-aa20-b6a924f2b752'::uuid, 'Dans un circuit LC idéal, l’énergie…', 'mcq', '["Disparaît à chaque période","Passe de l’inductance au condensateur et se conserve","Ne dépend que de la résistance","Est toujours nulle"]'::jsonb, 1, 'Sans résistance, l’énergie oscille entre forme magnétique et forme électrique.', 2),
    ('d37dad94-0068-5b8b-9c31-2dda8b1b14f7'::uuid, '006aa1bf-33e3-5bd9-aa20-b6a924f2b752'::uuid, 'La résonance se produit quand la fréquence imposée est…', 'mcq', '["Très inférieure à f₀","Nulle","Proche de la fréquence propre f₀","Le double de f₀"]'::jsonb, 2, 'L’amplitude est alors maximale.', 3),
    ('bdf6ccb0-37f6-5164-b66c-b8634ee8c680'::uuid, '006aa1bf-33e3-5bd9-aa20-b6a924f2b752'::uuid, 'Un oscillateur très peu amorti a…', 'mcq', '["Un facteur de qualité élevé et une résonance aiguë","Un facteur de qualité nul","Une résonance très large","Aucune résonance"]'::jsonb, 0, 'Q = f₀ / Δf : une bande passante étroite donne un Q grand.', 4),
    ('cb29d730-afe2-5083-a5b2-76b3ff2499ea'::uuid, '006aa1bf-33e3-5bd9-aa20-b6a924f2b752'::uuid, 'Une onde mécanique progressive transporte…', 'mcq', '["De la matière","De l’énergie sans transport de matière","Des électrons","Seulement de la chaleur"]'::jsonb, 1, 'Chaque point du milieu oscille autour de sa position d’équilibre.', 5),
    ('2c069fb9-4902-5d85-ae0c-297256eee250'::uuid, '006aa1bf-33e3-5bd9-aa20-b6a924f2b752'::uuid, 'Une onde de 500 Hz se propage à 340 m/s. Sa longueur d’onde vaut…', 'mcq', '["0,68 m","1,47 m","170 000 m","0,068 m"]'::jsonb, 0, 'λ = v / f = 340 / 500 = 0,68 m.', 6),
    ('d0e9c3f3-f6fb-5b10-96e6-27fc39fa0f99'::uuid, '006aa1bf-33e3-5bd9-aa20-b6a924f2b752'::uuid, 'La longueur d’onde est une périodicité…', 'mcq', '["Temporelle","Énergétique","Spatiale","Électrique"]'::jsonb, 2, 'La période T est la périodicité temporelle.', 7),
    ('adb6bdbe-5eef-5d6c-94e3-e377110d9eec'::uuid, '006aa1bf-33e3-5bd9-aa20-b6a924f2b752'::uuid, 'Si l’amplitude d’une onde double, la puissance transportée est…', 'mcq', '["Divisée par 2","Multipliée par 2","Inchangée","Multipliée par 4"]'::jsonb, 3, 'Elle est proportionnelle au carré de l’amplitude.', 8),
    ('60a8d23e-09c4-5858-927e-6fab7f631c58'::uuid, '006aa1bf-33e3-5bd9-aa20-b6a924f2b752'::uuid, 'Le spectre d’un signal périodique de fréquence 200 Hz contient des raies à…', 'mcq', '["200, 400, 600 Hz…","200 Hz seulement","100, 300, 500 Hz","0 Hz seulement"]'::jsonb, 0, 'Le fondamental et ses harmoniques, multiples entiers de 200 Hz.', 9),
    ('899f707e-9d14-50d4-965f-522ee63b2f22'::uuid, '006aa1bf-33e3-5bd9-aa20-b6a924f2b752'::uuid, 'La diffraction est d’autant plus marquée que l’ouverture est…', 'mcq', '["Grande devant λ","Petite, de l’ordre de λ","Opaque","Colorée"]'::jsonb, 1, 'θ ≈ λ / a : quand a diminue, θ augmente.', 10),
    ('4fe7f45e-c13d-5991-a343-15122f666e3d'::uuid, '006aa1bf-33e3-5bd9-aa20-b6a924f2b752'::uuid, 'Quand une onde passe de l’air à l’eau, sa fréquence change.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La fréquence est imposée par la source ; la célérité et donc λ changent.', 11),
    ('d50397a6-d725-5871-a893-d1916042cfb2'::uuid, '006aa1bf-33e3-5bd9-aa20-b6a924f2b752'::uuid, 'Un point situé à 6,8 m d’une source sonore (340 m/s) reproduit son mouvement avec un retard de…', 'mcq', '["2,0 s","0,20 s","0,020 s","50 s"]'::jsonb, 2, 'τ = d / v = 6,8 / 340 = 0,020 s.', 12),
    ('b2ba2370-4d29-5174-be56-90ad83b79609'::uuid, '86a44f2f-2aa4-59ec-871a-72bf8bd9ca09'::uuid, 'Le son se propage dans le vide.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Onde mécanique, il lui faut un milieu matériel.', 1),
    ('1399deea-48fb-5089-b304-c92777e018ed'::uuid, '86a44f2f-2aa4-59ec-871a-72bf8bd9ca09'::uuid, 'La hauteur d’un son est liée à…', 'mcq', '["L’amplitude du signal","La fréquence du fondamental","La célérité","Le nombre d’harmoniques"]'::jsonb, 1, 'Un son aigu a une fréquence fondamentale élevée.', 2),
    ('5d053203-9c9b-5ed3-9994-48227b8e5a3d'::uuid, '86a44f2f-2aa4-59ec-871a-72bf8bd9ca09'::uuid, 'Deux instruments jouent la même note mais sonnent différemment : ils diffèrent par…', 'mcq', '["La hauteur","La fréquence du fondamental","Le timbre","La célérité du son"]'::jsonb, 2, 'Le timbre dépend de la composition en harmoniques.', 3),
    ('a49ed24a-9021-5876-89b8-9d01ea520087'::uuid, '86a44f2f-2aa4-59ec-871a-72bf8bd9ca09'::uuid, 'Une intensité sonore de 1,0 × 10⁻⁶ W/m² correspond à un niveau de…', 'mcq', '["60 dB","6 dB","120 dB","-60 dB"]'::jsonb, 0, 'L = 10 log(10⁻⁶ / 10⁻¹²) = 10 × 6 = 60 dB.', 4),
    ('c9830a27-cbc3-51ac-b6d9-80caf4a647d5'::uuid, '86a44f2f-2aa4-59ec-871a-72bf8bd9ca09'::uuid, 'Doubler l’intensité sonore augmente le niveau de…', 'mcq', '["2 dB","10 dB","6 dB","3 dB"]'::jsonb, 3, '10 log 2 ≈ 3 dB.', 5),
    ('d5e01f1e-88cd-505f-a39e-678d3e7c04a1'::uuid, '86a44f2f-2aa4-59ec-871a-72bf8bd9ca09'::uuid, 'Dans une onde stationnaire, deux nœuds consécutifs sont distants de…', 'mcq', '["λ / 2","λ","2λ","λ / 4"]'::jsonb, 0, 'Un fuseau mesure une demi-longueur d’onde.', 6),
    ('3fa5c641-af77-5473-b381-cba3e82ae3dd'::uuid, '86a44f2f-2aa4-59ec-871a-72bf8bd9ca09'::uuid, 'Pour une corde fixée aux deux bouts, les fréquences propres sont…', 'mcq', '["fₙ = n × v / (4L)","fₙ = n × v / (2L)","fₙ = v / (nL)","fₙ = 2nL / v"]'::jsonb, 1, 'La corde doit contenir un nombre entier de demi-longueurs d’onde.', 7),
