    ('397cafea-4722-5af2-b3bf-a816d3cfe9cd'::uuid, '51c443a4-cd8c-5960-b688-4dff9ea4fdfc'::uuid, 'La résistance thermique d’une paroi vaut…', 'mcq', '["λ × S / e","e × λ × S","e / (λ × S)","S / (e × λ)"]'::jsonb, 2, 'Plus la paroi est épaisse et isolante, plus R_th est grande.', 3),
    ('bd8b8555-51ea-5585-a95d-8997cd52ccde'::uuid, '51c443a4-cd8c-5960-b688-4dff9ea4fdfc'::uuid, 'Pour une paroi à plusieurs couches, les résistances thermiques…', 'mcq', '["Se multiplient","S’additionnent","S’annulent","Se soustraient"]'::jsonb, 1, 'Les couches sont traversées l’une après l’autre, comme des résistances en série.', 4),
    ('29a96bdc-9d71-59ea-91ed-a4e7b5459a65'::uuid, '51c443a4-cd8c-5960-b688-4dff9ea4fdfc'::uuid, 'Φ = 400 W à travers une paroi de résistance 0,050 K/W. L’écart de température vaut…', 'mcq', '["8 000 K","0,000125 K","400 K","20 K"]'::jsonb, 3, 'ΔT = Φ × R_th = 400 × 0,050 = 20 K.', 5),
