    ('ab441f2a-59ce-53e9-b9df-3a4e740be5a6'::uuid, '6554b389-b1a7-5a4f-857e-a747cc3eb72d'::uuid, 'Dans une distillation fractionnée, le reflux sert à…', 'mcq', '["Refroidir le bouilleur","Accélérer le chauffage","Supprimer la colonne","Améliorer la séparation"]'::jsonb, 3, 'Renvoyer du distillat multiplie les équilibres liquide-vapeur dans la colonne.', 10),
    ('cc1fd801-da60-5b4f-995c-4f4f501ea273'::uuid, '6554b389-b1a7-5a4f-857e-a747cc3eb72d'::uuid, '2 mol d’éthanol et 3 mol d’eau : la fraction molaire en éthanol vaut…', 'mcq', '["0,40","0,67","0,60","2"]'::jsonb, 0, 'x = 2 / (2 + 3) = 0,40.', 11),
    ('eba52262-75c1-5e58-9eed-edb2fd0a3cba'::uuid, '6554b389-b1a7-5a4f-857e-a747cc3eb72d'::uuid, 'Un capteur de pression au fond d’une cuve permet de mesurer…', 'mcq', '["La température","La hauteur de liquide","La conductivité","Le pH"]'::jsonb, 1, 'La pression hydrostatique est proportionnelle à la hauteur de liquide.', 12),
    ('dbe81449-068d-55e7-8f1f-8485b7b367e2'::uuid, '4b9e0308-b625-55f9-b2b4-2200f7712027'::uuid, 'Quel est le coefficient total de l’épreuve de SPCL ?', 'mcq', '["7","9","16","14"]'::jsonb, 2, 'Partie écrite coefficient 7 et partie pratique coefficient 9.', 1),
