    ('8d2671d3-bfff-5d1c-b7dd-d0000181db41'::uuid, '4b9e0308-b625-55f9-b2b4-2200f7712027'::uuid, 'Combien de points la maîtrise de la langue représente-t-elle à l’écrit ?', 'mcq', '["2 points sur 20","5 points sur 20","Aucun","10 points sur 20"]'::jsonb, 0, 'Orthographe, syntaxe, vocabulaire juste et raisonnement bien formulé.', 3),
    ('887b1d6b-a46f-53d5-a572-dcb8e09db537'::uuid, '4b9e0308-b625-55f9-b2b4-2200f7712027'::uuid, 'Le sujet écrit comporte…', 'mcq', '["Une seule dissertation","Un QCM de 40 questions","Deux exercices liés","Trois ou quatre parties indépendantes"]'::jsonb, 3, 'Elles portent de manière équilibrée sur différents domaines du programme.', 4),
    ('65b856d3-1852-59a3-ac0c-a4ad1454c56e'::uuid, '4b9e0308-b625-55f9-b2b4-2200f7712027'::uuid, 'Quel est le coefficient de la partie pratique (ECE) ?', 'mcq', '["7","9","4","16"]'::jsonb, 1, 'La pratique pèse plus que l’écrit.', 5),
    ('083a8042-16f6-5bd1-ba6f-064463650cb0'::uuid, '4b9e0308-b625-55f9-b2b4-2200f7712027'::uuid, 'Les sujets de l’ECE viennent…', 'mcq', '["D’une banque nationale","Du professeur de la classe uniquement","Des élèves eux-mêmes","Du projet de l’année"]'::jsonb, 0, 'Ils sont à dominante chimie, physique, ou mixtes.', 6),
    ('f5b21e5e-24c7-5fef-b543-46f0d81bb2ec'::uuid, '4b9e0308-b625-55f9-b2b4-2200f7712027'::uuid, 'Dans la compétence « valider » de l’ECE, on attend notamment…', 'mcq', '["De ranger la paillasse","De recopier le protocole","D’identifier les sources d’erreur et d’estimer l’incertitude","De choisir le sujet"]'::jsonb, 2, 'Puis d’analyser de manière critique la cohérence du résultat.', 7),
    ('63b8d42b-57e2-5353-a155-0c3a61f7b47c'::uuid, '4b9e0308-b625-55f9-b2b4-2200f7712027'::uuid, 'Le projet de SPCL est mené par…', 'mcq', '["Un élève seul","Toute la classe","Le professeur","Un groupe de 2 à 4 élèves"]'::jsonb, 3, 'C’est un projet d’équipe unique mené sur la durée.', 8),
    ('85772f48-8644-5ba0-a4c9-a3c8823fb306'::uuid, '4b9e0308-b625-55f9-b2b4-2200f7712027'::uuid, 'Le projet de l’année peut servir de support au Grand oral.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le programme le prévoit explicitement, ainsi que pour l’ETLV.', 9),
    ('574849ef-05c5-5836-a6bd-6362a6a87f4a'::uuid, '4b9e0308-b625-55f9-b2b4-2200f7712027'::uuid, 'Les notions de première ne peuvent jamais être mobilisées à l’épreuve de terminale.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La note de service précise qu’elles peuvent être mobilisées.', 10),
    ('e983dc5d-6081-5001-b6e4-a2dccd9491c8'::uuid, '4b9e0308-b625-55f9-b2b4-2200f7712027'::uuid, 'À l’écrit, un calcul bien présenté comporte…', 'mcq', '["Seulement le résultat","La formule littérale, l’application numérique et le résultat avec unité","Un schéma obligatoire","Le résultat arrondi à l’entier"]'::jsonb, 1, 'La démarche est notée même si le résultat final est faux.', 11),
    ('0e0460dc-2bc1-58bd-8f0f-1ddb98cd11f8'::uuid, '4b9e0308-b625-55f9-b2b4-2200f7712027'::uuid, 'Pendant l’ECE, le respect des règles de sécurité relève de la compétence…', 'mcq', '["S’approprier","Communiquer","Réaliser","Valider"]'::jsonb, 2, 'Réaliser, c’est mettre en œuvre le protocole en respectant la sécurité.', 12)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('biochimie-biologie', 'biochimie-biologie-biotechnologie', 'biotechnologies', 'spcl', 'spcl');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('biochimie-biologie', 'biochimie-biologie-biotechnologie', 'biotechnologies', 'spcl', 'spcl')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 391 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 391 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
